/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20231107-7","meetingId":"r05-cm11","date":"2023年11月7日","dateIso":"2023-11-07","committee":"厚生委員会","time":"午後 １時００分～午後 ３時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"なかなか今の説明を伺っても、詳しいところがよく分からないという思いがしていまして、具体的にお聞かせいただきたいと思っています。それから、4)のところでも課題整理というのが書いてありますので、ここも併せて伺いたいと思います。","respondent":"東野福祉計画課長","answer":"品川区としては、さきに申しましたように、いろいろなところが連携した形で、まずは区民の方がお近くの窓口、関係する窓口のところでご相談をいただき、そこで解決できない問題を持ち寄って、その本人ではなく、相談されたところが持ち寄って、解決の糸口を探していく。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"そこのケース会議というのは、先ほど多機関協働事業でケース検討ということで、先ほど口頭で、こことここが参加するということで言われたのですけれども、多機関協働事業のところにはどこの部署が関わってくるのかというのをもう一回、本当はここに書いていただきたかったと思うのですけれども、どういうところが関わっているのかということを伺いたいのと、それから。","respondent":"東野福祉計画課長","answer":"当然、職員みんなに浸透しているかという部分は、まだまだ足りない部分だと考えていますので、それにつきましては、職員への研修など、昨年も行っているのですけれども、今年度も行った上で。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"複合的な相談で、精神疾患を抱え、貧困で、難病を抱え、家族のみんな具合が悪くて、ひきこもりを抱えるみたいな、本当に複合的で、これは本当にみんなが関わって相談されたら、すごく進むのではないかと思うようなことが、なかなか大変だなという思いをしながらしている部分があるのですけれども、そういうのも今度は、ケース会議にかかりながら、ネットワークで相談をしながら。","respondent":"東野福祉計画課長","answer":"これまでも区としては、そういった方への対応をどうするかというのは、実はやってきたところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"坂井市のところで、結構いろいろとモデル事業をやったりとか、そういうこともあって、こういう事業には国からの補助金がこのように出るということも幾つかご報告いただいたのですけれども、そういう点では、品川区のこれからされようとしていること、または、今なされていることで、国からの補助金というのが出ている部分があるのか、出ているのであれば。","respondent":"東野福祉計画課長","answer":"こちらにつきましては、今、手元に資料がないので、どのぐらいの補助率とかというのはあれなのですけれども、国からいただいた補助金、国が推奨している法的なところも整備して、推奨しているという部分がありますので、そういった補助金なども利用しまして。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"今回の視察ばかり言って申し訳ないのですけれども、視察のところで、大阪の八尾市で、１０万円の給付金の申請がなかった世帯というのは、支援が行き届かない世帯だろうということで、徹底して全ての世帯、３,０００世帯あるということでしたけれども、そこを１,０００万円の委託費をかけて徹底して訪問して、その中で、２０代・３０代のひきこもりの実態とか。","respondent":"東野福祉計画課長","answer":"福祉計画課が中核機関かという部分なのですけれども、福祉計画課は、この重層事業の取りまとめを行ってありますが、重層事業自体は区全体で取り組んでいくものと考えておりますので、私が考えている中核というのは、品川区全体と考えています。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問","question":"最後、１点だけいいですか。では、皆さんの後にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"ひがし委員","kind":"質問","question":"私が質問したかったところは、会議の進め方のところについてなのですけれども、今回、ケース検討の会議で８件、令和５年度にされたということで、少しずつ会議等も進んでいてよかったなと思っています。このやり方についてなのですけれども、開催の時期とかはどうしているのか、定期的に月一でやっていますというようにやっているのか。","respondent":"東野福祉計画課長","answer":"先ほども少しご紹介させていただきました子ども家庭支援センターですとか、保健センターといった出先のメンバーも入って、検討を進めております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"ひがし委員","kind":"質問","question":"せっかく進めていくのだったら、所管の方々も、コーディネートして呼んでというのが大変かなと思うので、固定化してやっていくというのも一つの手ではないかと思っていて、関係していない機関だから参加しないのではなくて、今回は関係しないけれども、みんなの話を聞くことで、プロフェッショナルの１人の人をつくるのではなくて、みんながスキルアップになるというところでいうと。","respondent":"東野福祉計画課長","answer":"今現在は試行期間という形で行っているものを、本格実施に向けて、どう取り組んでいくかという部分が重要になってくると思いますので、各自治体で取り組んでいるようなやり方、それから、固定メンバーだけとは限らずとか、メンバー構成などにつきましても。","voiceIndex":20,"id":"exchange-008"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ前向きに検討して、職員の方々の負担の軽減にもなるかなと思うので、調整の窓口としてコーディネーターを置いていますとか、つなげる支援室という部署をつくりましたとかというところを、それぞれの視察へ行ったところでは言っていて、そういう方を１人置かないとできないぐらいのボリューム感だし、大切なことなのかなと思うので、どこが担当か分からなくてというところだと大変だと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-009"},{"speaker":"おぎの委員","kind":"質問","question":"アウトリーチを通じた支援事業というところなのですけれども、困っている方というのは、表に現れてこない方がすごく多いと思いますので、ほかの自治体とかでも、直接家に訪ねてきたりとか、細かいケアをされているところもありまして、そうしますと、協力者も大分、社会福祉協議会だったり、民生委員だったり、いろいろな方の協力を得てやっていく形になると思いますが、そういったものを広げて。","respondent":"東野福祉計画課長","answer":"ただ、ほかの方々へのという部分がありますので、その辺の仕組みについては、今後、多機関協働も含めまして考えていきたいと思っています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"おぎの委員","kind":"質問・要望","question":"すごく困られている方で、どこに相談していいか分からないとかも、そもそも孤独・孤立になって、ほかの外の方との人間関係の構築自体ができていないと、相談も行けない状態になっていますので、表に出てこない方をどうやって支援していくのかは、本当に難しいと思いますが、ぜひやっていっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"他の自治体というところで、社会福祉法第１０６条の４によると、重層的支援体制整備事業を行うことができるという規定で、この条文の文言どおりだと、やらなくてもいいという自治体も理論上あるのかなと思っているのですけれども、実態的に、現状、重層的支援体制整備事業はどの程度の自治体がやろうとしているのでしょうか。","respondent":"東野福祉計画課長","answer":"今、委員がおっしゃったような、例えば過去からそういった取組を行っているような自治体もあろうかと思いますので、そういったところがどこまでできているかは別としましても、全国的な取組がされているというところは間違いがないかなと考えています。","voiceIndex":28,"id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"重層的支援体制整備事業、品川区が目指す重層的支援体制という一番上の文章のところで、最後に、望まない孤独・孤立を発見し伴走しながら支援すると書いてあるのですけれども、重層的支援体制整備事業は、それこそ先ほどおっしゃったとおり、８０５０問題とか、高齢者の問題とか、生活困窮者の問題とか、障害の問題とか、様々だと思うのですけれども、わざわざ最後のところで。","respondent":"東野福祉計画課長","answer":"アプローチ３は、多機関協働が該当してくる。これを左側の表と比べますと、まさにこれが重なってくる部分ですので、区としてはその部分も併せて、今後一緒に推進してまいりたいという考えで、こちらの支援、区が目指すというところにも書かせていただきました。","voiceIndex":30,"id":"exchange-013"},{"speaker":"筒井委員","kind":"確認","question":"ということで、孤独・孤立対策を重点的に対策するために重層的支援体制整備事業をやるというわけではないということですか。それを確認でもう一度。","respondent":"東野福祉計画課長","answer":"重層事業の取組は、区が令和３年から始めているもので、孤独・孤立対策は、先ほどお話させていただきました各事業の中での取組を行っているものを、組織横断的に取り組んでいくということになっておりますので、順番でいくと、どちらかというと。","voiceIndex":32,"id":"exchange-014"},{"speaker":"こんの委員","kind":"確認","question":"1)現状と課題というところから、一つ確認させてください。しづらさというところにある課題にこそ、重層的支援体制をつくる鍵があるのではないか。今まで仕組み、制度はあるけれども、支援しづらかったと感じていらっしゃるということは、要するに連携なのか、そこに眠っている課題というのは洗い出されたのか、まずそこをお伺いしたいと思います。","respondent":"東野福祉計画課長","answer":"こちらの支援のしづらさにつきましては、私が今の部署に来て目にしたのが、地域福祉計画の専門職アンケートというところで、確かにいろいろな課題を持った人に対して、自分の専門的なところでのアプローチはできるけれども、それ以外のところへつなぐという部分が。","voiceIndex":35,"id":"exchange-015"},{"speaker":"こんの委員","kind":"確認","question":"今確認をさせていただいた、専門性のある方のところに来た相談が、それだけで、ほかにも必要な、この方が抱えている問題が見えているのだけれども、それ以上のことができないというのは、本当に今まであった。窓口として、非常に皆さんにも周知されている。そうしたところの具体的な、最後まで寄り添う人というのはどういうイメージなのか、その辺も教えてください。","respondent":"東野福祉計画課長","answer":"ですから、ケース会議で出てきた、この人に対してはこういう支援をしましょうということが決まった段階で、それに対して、今窓口で受けた人が対応するのか、それから、その人に一番身近な相談、例えば地域の相談のできる人がいるのかどうか、または。","voiceIndex":37,"id":"exchange-016"},{"speaker":"こんの委員","kind":"質問","question":"最後にご答弁いただいた件ですけれども、そうなると、何をするかというところで、いろいろな所管、必要な機関が集まって、するということですが、何をするかで動く方と、そこの会議には出たけれども、実際は動かないでいる人と、でも、相談者を取り巻く関係部署の方々も、この方に支援をしたらどのように進捗状況を連携するというか、情報を共有するものも必要だと思いますが。","respondent":"東野福祉計画課長","answer":"もちろん、その支援をした後、どうなったかという部分については、参加されたところにフィードバックを行っておりますので、では、それを何年後までやるかとか、その辺についてはまた検討の余地はあるかと思うのですけれども、今現在はケース会議の検討。","voiceIndex":39,"id":"exchange-017"},{"speaker":"こんの委員","kind":"確認","question":"その連携が、関わる各所管の方たちが見られる状態といいますか、情報が共有できる状態にあることが必要ではないかと思うところです。こういう方をどう見つけるかというところが大事かなと思うのですけれども、その辺については、実態調査のアンケートも行うということですが、これは関係機関の方々、区民にも何か調査をするのでしたでしょうか、その確認です。","respondent":"東野福祉計画課長","answer":"品川区としても、各所管で窓口を持っているところについては、先ほど委員からもお話ありました接遇も含めまして、いろいろな専門スキルなどを持っている方も配置されていると思いますので、そういった方が中心になった形での。","voiceIndex":41,"id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問","question":"重層的支援体制の検討中ということだと思うのですけれども、これは、どういう組織で重層的支援体制について検討されて、どんな形で検討されているのか、その点について伺いたいのですけれども、坂井市で相談支援包括化推進会議というのが毎年行われて、そこの会議に参加する課とか、それから関係事業所とか、そういうところがどんどん広がっていって、そこの中で毎年研修とか、いろいろなグループワークとか。","respondent":"東野福祉計画課長","answer":"取りまとめを行っているのは私ども福祉計画課でございまして、庁内におきましては、関係している課において庁内検討会というのを年に２回行っております。それから、庁内検討会の前に推進会議というものを毎月行っているという状況です。","voiceIndex":46,"id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、推進会議というのは、福祉計画課の中で推進会議というのが持たれているのか、その推進会議のメンバーと、庁内で検討されている課がどこなのかについても伺いたいと思います。","respondent":"東野福祉計画課長","answer":"庁内検討会は、今後の方針を決めていくという会議になりますので、庁内の関係している課長級、それから、そこの部長も入った形で検討しています。","voiceIndex":48,"id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、毎月されている推進会議というのは、多機関協働事業ケース検討を行うところとイコールみたいな形でしょうか。一番初めに、高齢者福祉課、障害者支援課、それからＨＥＡＲＴＳとか、いろいろ言われました。参加されているところを、もう一回だけ教えていただけますか。","respondent":"東野福祉計画課長","answer":"ケース会議も先ほど、２か月に一回とお話させていただいたのですけれども、推進会議につきましては、基本、毎月開催をしております。こちらのメンバーとしましては、福祉部の各所管、子ども未来部の各所管、ただ、保育課とか、そのような施設の関係のところは除いてあります。","voiceIndex":50,"id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問","question":"品川区としては、重層的支援体制はこういうことでやっていきますというのがまとまるのは、いつ頃になるのですか。","respondent":"東野福祉計画課長","answer":"本格実施が令和７年度からということを目指して進めておりますので、取りまとめについては令和６年度、来年度末までにはまとめたいと考えています。","voiceIndex":52,"id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問","question":"もう一つ、具体的なところなのですけれども、孤独・孤立対策のところでは、若い人をターゲットにアンケートもしてくるということだったのですが、その後で高齢者もということだったのですけれども、今でも高齢者の、例えば独り暮らしの方とかは、民生委員の方を通じて、独り暮らし高齢者の実態というのは把握されているのではないかと思うのですが。","respondent":"東野福祉計画課長、川原高齢者地域支援課長","answer":"次が来年度行う予定となっておりまして、そこで高齢者のニーズの把握をしています。ただ、年齢的には７５歳以上というところになりますので、後期高齢者以上という形になります。ちなみに参考までに、今月の実施予定につきましては、１１月１８日土曜日にオンラインでの認知症サポーター養成講座、そして、１１月３０日木曜日にオレンジフェスタ。","voiceIndex":54,"id":"exchange-023"},{"speaker":"おぎの委員","kind":"質問・要望","question":"こちらを小学生に絞った理由というのは、ほかにも中学生、高校生とか、あると思うのですが、認知症に関して小学生に向けて、こういった活動をされたという理由と、最後の補聴器のところで、１５０件申請が出ておりますが、助成決定は６１件で、助成数が２２件ということになっているのですけれども、この数字は、まだ審査中なのか、審査が通らなかったのか、内訳をお聞かせいただきたいと思います。","respondent":"川原高齢者地域支援課長","answer":"２点ご質問をいただきました。１点目、小学生向けの認知症サポーター養成講座を開始した理由です。令和４年度からは中学生までに範囲を広げてサポーター養成講座を実施したところ、非常にニーズが高いと感じました。","voiceIndex":59,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなので、啓発というのがもっと大事になってくるのかなと思うのですけれども、啓発の部分というのは、認知症サポーターの養成という形でされるのが、啓発というところでの取組なのかというところをお聞かせいただきたいのと、あと、サポーター養成講座が４３回と、下の数が累計ということになっているので、令和４年から令和３年を引いた数の９２６人が。","respondent":"川原高齢者地域支援課長","answer":"目標値については、あくまでも１年度で何人ということで、掲げてはいないのですけれども、昨年度以上というところでは、今年度も実施していきたいということで考えてあります。","voiceIndex":62,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"様々工夫していただいていると思います。もう一つ、先ほどの高齢者の補聴器のことなのですけれども、申請が１５０件というのは、多分、予算化して８０件ぐらいだったと思うので、かなり希望する人が多いのだなと思うのですけれども、１５０件のうち、結局、助成が決定したのは６１件なのですが、これからも含めて、受けられるというのはおおよそ何件ぐらいまでになるのかという件数を教えていただきたい。","respondent":"川原高齢者地域支援課長","answer":"これをしたことによって、７月の助成時にも、既に講演会でも申請書を配っていたので、スタートと同時に多くの申請を頂いたところで、やはり普及啓発の一環として効果的だったと考えていますので、今後も実施をしてまいりたいと考えているところではあります。","voiceIndex":64,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"認知症サポーター養成講座なのですけれども、累計で２万人近くの方が受講されているということなのですが、繰り返して講座を受けられている方もいらっしゃるのか、また、これを受けられている方というのは、ご家族に認知症の方がいらっしゃる方なのか、それとも、本当に純粋に認知症ということを理解して、知識を深めるために受けられている方がどのくらいいるのか。","respondent":"川原高齢者地域支援課長","answer":"民生委員に新たになられる方に関しても、実施をしていますので、そういった高齢者の方と接する方たちにも、啓発という意味で講座を受けていただいているところです。","voiceIndex":67,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。お願いします。岡山市で認知症対策というか、介護予防教室の内容の一環として、ｅスポーツを活用しているということを今回の行政視察でお聞かせいただいたのですけれども、品川区でこうしたｅスポーツを活用した認知症対策、もしくは介護予防サービスの事業として扱うということは検討されているというか、今後どのようにお考えをされているのでしょうか。","respondent":"川原高齢者地域支援課長","answer":"認知症予防という観点でも、脳トレのようなゲームもありますので、そういったところでも活用できないかというのは、引き続き検証を図ってまいりたいと考えています。","voiceIndex":69,"id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-029"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"認知症予防にもなりつつ、機能訓練にもなる。この２つが一番、高齢者の方のやってみたいことという要望で多かったと思います。つまり、運動したいという要望があったときに、すぐに通所介護事業所とか、介護保険に関わる、給付に関わるようなところに案内しなくてはいけないというところに、歯がゆさを感じる方がケアマネジャーに結構いらっしゃるのです。","respondent":"川原高齢者地域支援課長","answer":"実際に昨年度の試行的な実施として、委員がおっしゃったように、ゲーム機の操作が難しかったり、時間がかかったりというところがありますので、私どもの課でスマホ教室を実施しておりまして、その一環として。","voiceIndex":73,"id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひともよろしくお願いいたします。もう１点、別のところで一つだけ。なぜもっと早く認定を受けて、サポートを受けなかったのだろうという方も結構いらっしゃるので、この文言をずっと使い続けるのは、誤解を生む可能性が高いかなと思うので、もう少しこの文言を検討されたほうがいいのかなというところで、要望になります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-031"},{"speaker":"こしば副委員長","kind":"質問","question":"そうすると、どこで認知症を発見するか、周りが気づくかということが大きくなってくるのかなと。数もどのぐらいあるのか、正確に覚えていないのですけれども、周りに家族がいれば、発見が早まるかもしれませんが、いないとなかなか進まないということにもなってきますので、その辺り、品川区で今後の検討もあるかと思いますけれども、お考えを教えていただけたらと思います。","respondent":"川原高齢者地域支援課長","answer":"今回の検診にご協力いただいた医療機関というのは３０か所ではあったのですけれども、地域の身近な相談の場所というところで、地図と、医師会ごとの医院の名称をくるみガイドに掲載していますので、そちらも併せて、区民にも周知をしてまいりたいと考えているところです。","voiceIndex":77,"id":"exchange-032"},{"speaker":"こしば副委員長","kind":"質問","question":"実際にはもう少し数が多いということで、安心をしました。これらの受診をしまして、認知症と診断されたときというのは、そこのお医者さんのほうで今後の診療、治療につながってくるということでよろしいのでしょうか。","respondent":"川原高齢者地域支援課長","answer":"精密な検査に関してはもう少し大きいところで、荏原病院と中継の医療機関というところで、地域の医療機関とつながっている病院がありますので、そこでの診断を受けたりとか、その方の進捗と進行の状況によって、各医師が判断をして。","voiceIndex":79,"id":"exchange-033"},{"speaker":"こんの委員","kind":"質問","question":"いろいろなメニューを用意してくださっているので、多分いろいろな箇所に行く人は、いろいろなところに行かれる、１か所でという人もいるだろうとなると、こういうメニューをたくさん増やしていくことが、この先いいのか、それとも、内容をもっと充実するというのが必要なのか、その辺は、この事業に対して運動系を、認知症予防事業の脳力アップ、それから栄養改善の事業というところは、今の実績も含めて。","respondent":"川原高齢者地域支援課長","answer":"やっていくに当たっては、やはり知識がある方の指導が必要なので、そういったところに講師を派遣していくという形で、介護予防の推進員という方を派遣させていただいているところですので、受講する、そこからさらに発展して、自分たちでつなげる。","voiceIndex":82,"id":"exchange-034"},{"speaker":"こんの委員","kind":"質問","question":"通いの場は、去年から登録で始まったと。確かにこれを広げていくということは、自主的にやっていくのは、もっと健康に、自分たちでより意識を持って進めていかれるという、これは非常に大事なことだと思います。専門家を派遣していただくという体制、分かりました。この取組については、今後どのようにフレイル予防というところに関連してくるのですか。いま一度教えてください。","respondent":"川原高齢者地域支援課長","answer":"今年度、試行的という形で、普及啓発イベントの一つとして実施をしたところ、非常にニーズが高かったのと、検診事業は現在、残念ながら７５歳限定という形になってありますので、そこに達していない方、そして７５歳以上の方も参加の申込みがあってということで。","voiceIndex":84,"id":"exchange-035"},{"speaker":"こんの委員","kind":"質問・要望","question":"頭の健康チェックは今後、その実施したことによって見えてきたことから、今後もということですけれども、早い段階から、認知症にならないようにするためにはという意識で、先ほどの通いの場ではないですけれども、自主的に自分たちで予防していく動きができると、もっといいのかなと思うと、この健康チェックというのはこれから大事な事業にもなるのかなと思いますので。","respondent":"川原高齢者地域支援課長","answer":"ご意見ありがとうあります。頭の健康チェックでご自身の脳と元気度のチェックを測ることをきっかけに、各種認知症予防のいろいろな事業であるとか、あとは自分たちで何かに取り組むという形の、通いの場への活動へと、さらに広げていければと考えています。","voiceIndex":86,"id":"exchange-036"},{"speaker":"鈴木委員","kind":"提案","question":"品川区でも認知症のサポーター養成講座というのは、講演を１回聞くと、オレンジのリングをいただいて、サポーターに登録できるようになるという感じなので、割と簡単になれると思うのですけれども、そこからさらにもっと詳しく、サポートリーダーみたいな研修というのもされているのではないかと思うのですが、そのサポートリーダーという方はどれぐらいいらっしゃるのかということと、それから。","respondent":"川原高齢者地域支援課長","answer":"これらの養成講座とか、全てをコーディネートしてくださっている認知症の地域支援推進員という方が、区内には８名いらっしゃって、その方を中心に、こういったサポーター養成講座を修了した方、ステップアップ講座を修了した方、そして。","voiceIndex":89,"id":"exchange-037"},{"speaker":"鈴木委員","kind":"質問","question":"品川区の高齢者地域支援課の中に、初期集中支援チームというのができていたのではなかったですか。専門看護師とか、専門職とかが何人かいて、そして、どこかの専門のドクターが入って、初期集中支援チームというのができていたイメージがあったのですけれども、そういう形で今、動いているというわけではないということですか。","respondent":"川原高齢者地域支援課長","answer":"初期集中支援チームに関しては、２地区、品川地区と荏原地区という形で、品川地区は訪問看護ステーションであるとか、クリニックの医師などがチームを組んでいて、荏原地区に関しても、認知症の専門医、保健師、介護福祉士などがチームを組んで。","voiceIndex":91,"id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3674#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":38006,"voices":97}},{"id":"r05-20231107-8","meetingId":"r05-cm11","date":"2023年11月7日","dateIso":"2023-11-07","committee":"建設委員会","time":"午後 １時００分～午後 ４時３９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"京浜急行バス株式会社のバス路線における系統廃止","agenda":"京浜急行バス株式会社のバス路線における系統廃止","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"乗車人数も伺えればと思います。今回、品川区に対しての意見聴取があったということで、その意見聴取の返答というのですか、そういう答えというのは何かあるのかどうか、あったとすれば、それはどういった内容なのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"それからもう一つが、別紙２のほうに、大森駅発で１７時１４分発、こちらが森３０というものでございまして、こちらは、大森駅を出発して大森海岸駅、それから大井競馬場駅前、それから中央公園を通って、お台場方面に行って、そこから今度は、冒頭ご説明した。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、これがどう反映されたかというのは区としてもつかんでいないということなのか、そこも伺いたいと思います。今回廃止をされた場合、それに代わる交通手段というのは区としてはどのように考えていらっしゃるのか、意見の中でも、減便や既存路線の再編等を検討していただきたいということで求めていますので、そうしたところの区の考えも伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区の意見に対しての回答といいますか、一つ、冒頭ではご説明したのですが、道路運送法上、この意見聴取というのが、廃止を許可すべきか許可すべきでないかという判断のために関東運輸局が行うものではなくて、今回で言うと。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"代替手段としてはりんかい線ということで、それも確かに一つの手段であるとは思うのですけども、この路線がなくなることの影響があると考えているというところですので、大田区などとも協力して、路線の再検討などを求めるべきではないかなと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区としては、意見聴取に対しての意見として、このルート全体の見直しの中であるいは減便の中で、路線の存続といいますか、検討いただけないかということで意見は出させていただいたですが、これは運輸局のホームページにも公表されておりますが、関係自治体として。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西本委員","kind":"確認","question":"１点だけ確認をしたいと思いますが、コミュニティバスの路線を検討するときに、いろいろと交通機関を総合して今のコミュニティバスという形の路線を決めたと思うのです。それに対して今後いろいろと検討が進められる中で、こういう、廃止になるということでは、またそのときの分析状況が変わってくるかと思うのですが、その影響はどういうふうに考えられておりますでしょうか。","respondent":"鈴木都市計画課長","answer":"ただ、廃止の路線本数とすると１８便ですので、それから、大きくはやはり大井町とお台場を結ぶ公共交通、コミュニティバスというのは計画の中でもしっかり位置づけておりますが、鉄道と路線バスを補完する交通手段だですので、今、りんかい線が。","voiceIndex":12,"id":"exchange-004"},{"speaker":"西本委員","kind":"確認","question":"コミュニティバスの検討の中での影響はないというのが確認できたと思いますが、この路線を見ると、ただもったいないなという感じはします。いろいろな検討をしながら、多分こういう運行できないということは今後出てくると思うのです。それを、ではコミュニティバスがどういう補完をしていったらいいかというのが今後出てくるかと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"逆に、増便とか創設という観点でお伺いしたいのですが、例えば、補助第２６号線が開通しまして、武蔵小山から大井町を経由しての路線が新たにできましたけれども、あれは武蔵小山方面から１本で区役所方面に行けるということで利便性が高まったと思いつつ、ただ、１時間に１本しかないとかですから、増便をしたほうがいいのではないかという思いがある一方で、いわゆる収益の関係、営利団体ですから。","respondent":"鈴木都市計画課長","answer":"今、補助第２６号線の新設路線のお話をいただきましたが、東急バスから常々伺っているのは、まずはやはり、小さく始めてと言ったらあれですけども、まず、着実に始めて周知いただいて利用いただいて、その状況をしっかり見ながら、当然ながら利益につながるような増便というのは。","voiceIndex":16,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"小さく産んで大きく育つような意味でも、行政としても、いわゆる公共交通機関をご利用くださいというような、いろいろな場面で呼びかけをするケースがあるかと思うのですけども、今度、新庁舎ができるに当たって、交通アクセスをどうするかというのはまだこれからなのでしょうけれども、例えばですが、新庁舎前にバス停ができて、そこはいろいろな方面から区役所に行ける。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"若林委員","kind":"質問・要望","question":"廃止の理由で４つの黒ポチがありますけども、２番目の、これまでも減便などを行ってきたというのは、もしお分かりになれば、どんなご様子だったか、具体的に教えていただきたいのが一つと、最後のポチに、改善基準告示の改正による影響と、これはどういうことかお聞かせいただきたいと思います。これまで、いわゆるこういう路線バスの廃止については、この品川区内、３社かな、廃止はあったのでしょうか。","respondent":"鈴木都市計画課長","answer":"この改善基準告示というところは今、非常にテレビ等でも２０２４年問題ということで、特に運転士の労働、特に残業時間の規制が強化されるというところで、例えばですが、一旦業務を、運転を終了してから、これまでは８時間後には次の運転ができたのが。","voiceIndex":20,"id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"そうすると２０１８年、５年前に約４０万人で、５年後、約２４万人で、大井町、品川区内から東京湾を渡ってお台場に行く、最初に設定をした京急の目的というのですか、経営方針があって、それがいつスタートしたのか分からないのですけども、今日になって約２４万人まで落ち込んできたと。","respondent":"鈴木都市計画課長","answer":"大井町駅とお台場を結ぶ、井３０という路線の運行が開始されたのが平成９年の９月１日からというところで、基本的に京急から伺っているのは、やはりお台場地区の開発、まちづくりの進展に合わせて運行を開始し、系統としてはその後、便数を増加させる等の取組を行ってきたと。","voiceIndex":22,"id":"exchange-009"},{"speaker":"若林委員","kind":"意見","question":"ただ、一区間としてなくなるので今回報告があったということで、今後その、今七十数％という数字もありましたけども、この路線バス、地方ではよく聞く話だったなとテレビ報道等で聞くのですけど、品川も、やはりそういう意味では、これは地方だけの問題ではなくて、東京、品川という一地域、地方でも、やはりそういう波が押し寄せてきているのだなというふうに理解をして、その辺の今後の変化。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-010"}]},{"id":"topic-02","title":"「品川区空き家等対策計画の中間見直し」（素案）について（パブリックコメントの実施）","agenda":"「品川区空き家等対策計画の中間見直し」（素案）について（パブリックコメントの実施）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、別紙のＡ３の資料で、不適正管理状態から改善された空き家は３６件というところと、空き家のうち不適正管理が９７件というところがあるのですけれども、昨年と比べると７件増えているのですが、新たな空き家の数とその改善された数から見ると、改善されたほうが多いので減るのではないかという感じなのですが、今、実際には７件増えているということで。","respondent":"竹田住宅課長","answer":"今申し上げた管理不全空家と、従来からある特定空家と、どう違うのかというところなのですが、幾つか例を挙げてご説明しますと、建築物の場合、管理不全空家ですと、屋根の変形とか外装材の剥落もしくは脱落なのですが、特定空家については。","voiceIndex":29,"id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"何となく、不適正管理状態と管理不全空家の状況は分かりました。それで、先ほどの数のところは、空き家はそうなのです。私も計算してそうなったので、それは分かったのですけども、不適正管理の数がどういう計算で出されているのかというところを伺いたいと思います。","respondent":"竹田住宅課長","answer":"それで、これは法的に決まっているものではないのですが、私どものほうで、令和４年度でいいますと、５４１のうち９７件程度が近隣の方に悪影響を及ぼしている空き家であるというふうに認識しまして、９７という数を記載しています。","voiceIndex":31,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"空き家のうち、不適正管理は９７戸と、それで、新たな空き家が２６戸、５４１の中で増えていると思うのですけれども、それが全部不適正管理空家だとしても、改善されたのは３６戸あるので、単純計算１０減るということになるのですが、昨年から見ると９０から９７に７戸増えているというのはどういう計算で出されているのかというのを伺いたいです。いかがでしょうか。","respondent":"竹田住宅課長","answer":"それで、この、一番上の段の９０とか９７とか括弧書きの数字ですけれども、こちらはほかの足し引きによって導かれる数字ではなく、全体の、令和４年度ですと５４１のうち、幾つ不適正管理状態なのかということで、私どもが認識している数が９７というふうに認識しています。","voiceIndex":33,"id":"exchange-013"},{"speaker":"のだて委員","kind":"提案","question":"そうしたら次の質問に移りたいと思うのですけれども、この間いろいろ、品川区として取組はやられていると思うのですが、その中で実際に、空き家の改修助成というのも行われていると思うのですが、この実績、何件あったのかというのを伺いたい。今回、初めてこの目標の数値を決定したということで、それに至った経緯ですか、前回決めなくて今回決めたというところを伺いたいと思います。","respondent":"竹田住宅課長","answer":"それから提案ですが、１年間に３０件ほど、所有者あるいは相続人の方にお送りしているのですが、すぐにはなかなか反応がなくて、お送りしたのにご返答いただけなかったのかというふうに思う場面が多いのですが、時間がたって、３か月とか４か月たってから、相続人等の方から。","voiceIndex":35,"id":"exchange-014"},{"speaker":"のだて委員","kind":"提案","question":"民間の提案のところで先ほど、年間３０件送っている、解決につながったというお話だったのですが、相談窓口の件数とは別ということでいいのですね。そこの民間の提案が活用された件数でいいのかという確認と、実際どういった活用をされたかというところを伺いたいと思います。併せて伺います。","respondent":"竹田住宅課長","answer":"住宅にお困りの方に結びつける取組ですが、空き家は、先ほど申し上げたとおり、耐震基準を満たさないような建物も多数ありますので、人が住める状態にするには一定、費用等もかかるところですので。","voiceIndex":37,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"耐震性のところがちょっとそれがあったか分かりませんけれども、と思いますので、そこはぜひ活用できるようにしていただきたいというふうに思います。定期的な修繕のところは、実施はしないということだと思うのですけども、ぜひそうした、長く使っていけるようにするということが、様々、環境への配慮など重要だと思いますので、そうしたこともぜひ今後考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"幾つか教えてください。これ、相談もかなりしていただいていると思うのです。だから改正になっているのでしょうけれど、これを誰がどのように周知させるのでしょうかということです。これは住宅課がやるのですか。そうすると、一体誰がやるのというところで、いろいろな部署に関わってくるのではないかなと思うのですが、それをどのように対処していこうとしているのか教えてください。","respondent":"竹田住宅課長","answer":"法改正等の制度の周知ですが、今回の法改正はもちろん全国的なことですので、国も可能な限り周知を、ＰＲをしていくということですので、もちろん、そちらに協力して区としても制度の周知をしていくと同時に、住宅課でも広報紙やホームページに載せる等々。","voiceIndex":41,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"ちょっと気になっていますので、予算立ても含め、人の手配も含め、職員の数も含めて、どう見直しを図ろうとしているのか図ろうとしていないのか、する必要はないのかというのをお聞きしたいと思います。だけど、区というのはもう現場の住民たちがどう行動を取ってくれるかということが必要なわけなので、この辺のやり方、今後の検討というのはいかがな状況になっていますでしょうか。","respondent":"竹田住宅課長","answer":"法改正をどのように周知していくかということなのですが、関心のない方にお話をしても、なかなか興味を示していただけない、あるいは記憶に残らないというところもあろうかと思いますので、こういった。","voiceIndex":43,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"調査するのが年間１,０００件以上あるということで、委託をしているということなのですが、ですから、来年度これをやろうとしたときに、今の現状でいいのですか、その予算、今日は分かりません、どういう予算をかけていってどれぐらいの経費がかかっているのかというのはここではお聞きしませんけれども、現実としてこのままでいいのですか、これ改正になって新たにいろいろやっていくよという中で。","respondent":"竹田住宅課長","answer":"区民の方に関心を持っていただくという点ですが、今回、様々な法改正がありましたので、内容に応じて、広く浅く広報すべきものと、関係する方に深く丁寧にご説明していくものと、大きく分けて２つあろうかと思いますので、それぞれの内容に合わせて周知方法を変えて。","voiceIndex":45,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"今回の、空き家等対策計画の中間見直しということでありますが、今までの議論というかご説明を伺うと、空き家の中でも、不適正管理の空き家を減らす、あるいはもっと進んでしまった、管理不全空家を減らすというところに重点が置かれた取組だと思うのですが、総じて空き家対策というのは、のだて委員も少し触れられていたのですけれども。","respondent":"竹田住宅課長","answer":"国の調査によると、空き家の所有者の方に、なんで空き家にしておくのですかという調査の結果があるのですが、主なものをご紹介しますと、物置として必要だ、解体費用をかけたくない、更地にしても使い道がない、それから特に困っていない等々。","voiceIndex":48,"id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"というか、この数と、除却というのはもう完全に、管理不全状態の家を除却したという、もう壊して更地にしたということだと思うのですが、その数と居住確認された数を一緒にする意味が、この数字にどういう意味合いがあるのかというのはちょっと理解ができないのですが、そこをまずお聞かせいただきたいと思います。","respondent":"竹田住宅課長","answer":"すみません、先ほどの説明がよろしくなかったので改めてご説明するのですが、令和３年度の不適正管理が９０から９７に増えているというのは、令和３年度に４３件新たな空き家が増えましたけれども、不適正なものが３６件減っていますので、都合７件増えていますので。","voiceIndex":50,"id":"exchange-021"},{"speaker":"田中委員","kind":"確認","question":"それと、目標として、これまで取組によって、令和４年は３６件で、今後は、不適正管理から改善する数を４０に目標を定めるということで、これはいいことだと思うのですけれども、冒頭もちょっと言ったのですけれども、要はそもそも不適正管理状態にさせないということを、目標は不適正になったものを減らすということなのですが。","respondent":"竹田住宅課長","answer":"居住確認されたものと除却された空き家数を同じ欄に掲載するのはどうなのかということのご質問ですが、先ほど申し上げたとおり、空き家という定義からはなくなったという点では一緒ですが、性格が少し違うものですので、スペースの関係で一緒にしてしまったのですが、今後は。","voiceIndex":52,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"今回、中間見直しとして行うに当たってのパブリックコメントを求めるということのご報告なのですけれども、パブリックコメントをされる方というのは恐らく、何というのでしょうか、空き家状態、不適正管理状態の所有者の方からの意見ではなくて、空き家の周辺に住んでいらっしゃる方からの声がほとんどなのではないかなというふうに思われるわけですが、手続上。","respondent":"竹田住宅課長","answer":"そういったことを十分加味しながら、最善のものとして今回、おつくりしたのですが、区民の方に見ていただくことによって、私どもの考える方向性や、実際にやることに間違いと意見の相違がないのかどうかをご意見いただく、あるいは、いや。","voiceIndex":54,"id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"私の思いとしては、今回パブリックコメントをすることを通じて、連絡がつかなかった方にも、こういうパブリックコメントがなされているということを知ったことによって、地権者に名のり出てもらうようなというのでしょうか、そういう対応にもつながるような、パブリックコメントとしての取組にしていただけると、根本的なところの改善にも通ずるところもあるのかなという期待もしたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"この数字のところなのですけども、不適正管理のところで、先ほど、新たな空き家から改善された空き家を引いた数がプラスになっているという話だったのですが、そうするとその前の年を見ると、令和２年度が４９件が空き家で、不適正管理から改善されたのが２４件なので２５件増えてしまうということになるのですけど、実際は９０件で１７件減っているということになるわけですが。","respondent":"竹田住宅課長","answer":"不適正管理でなかった空き家が不適正管理になるケースもあります。改善された空き家の中には除却された空き家も一部含んでおりますので、下の表の３行目、４行目は一部重複している数が含まれておりますので、すみません、分かりにくくなっておりまして申し訳ございません。","voiceIndex":58,"id":"exchange-025"}]},{"id":"topic-03","title":"品川区公園施設長寿命化計画の改定","agenda":"品川区公園施設長寿命化計画の改定","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"確認をさせていただきたいと思うのですが、今回、保全の仕方が予防型と事後型というのがあると思うのですが、これはどういった形で分けられているのかというところと、この健全度、判定した中で、Ｃが３５４件、Ｄが９件ということで、これはどういったものがあるのか、どういったものが多いのかということも含めて伺いたいと思います。","respondent":"高梨公園課長","answer":"予防保全と事後保全の違いについてですけども、国による対策の指針におきまして、例えば、公園の中の舗装のようなものは、なかなか計画的な修繕により寿命を延ばすというものが困難であるというようなことで位置づけがされておりまして、一定、最初から事後保全、要するに。","voiceIndex":64,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"なんとなく区内の状況が分かったかなという気がします。計画的にいろいろ、平準化なども行って進めていくということですけれども、どういった事象で起こるか分かりませんけども、緊急的に必要なことがあった場合にはどうするのか、そこの対処の仕方を伺いたいのと、この間、そうした老朽化などで子どもたちが事故に遭ったとかといったことはあったのかどうか伺います。","respondent":"高梨公園課長","answer":"当然これに基づいて維持管理を進めていくのですが、やはり公園ごと、施設ごとによって使われ方が違いますので、今、委員からご指摘がありましたとおり、まだまだ寿命はあるのだけども緊急的に対応が必要な、不適切な対応、使われ方をしたりとかということで破損して。","voiceIndex":66,"id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそういったことがないように、適切に管理、保全をしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと教えてほしいのですが、こういう遊具であったり、いろいろするときに、減価償却という考えもあると思うのです。物を買ったときに、いずれも資産という形が償却されていく。それに加えて補償期間というのが何でもあります。遊具などは特にそうだと思うのですけど、耐用年数とかというふうな形になると思うのです。","respondent":"高梨公園課長","answer":"今回、公園施設にとどまらず、国が、それぞれの様々な施設で長寿命化計画というものを推奨している背景には、やはりこれから、減価償却、使用見込み期間が過ぎたからもうどんどん新しいものに替えていくというよりは、人口減少等を迎える中で。","voiceIndex":70,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"例えばそのゼロになっている中でまた、使い続けているという状況になってくると、会計上、答えられる範囲でいいのですけど、使い続けるという意味でいうと、財政上の計算の仕方であったりとか資産の考え方とかというのは、関係してくるのではないのかなと思うのですが、その辺はいかがですか。もしも担当が違ったら別に構わないです。","respondent":"高梨公園課長","answer":"複式簿記のほうの間違いがあるといけないので、あまりめったやたらなことは言えないかなというふうに思っているのですが、公園を管理している立場から言いますと、確かに減価償却で建物等についてはゼロになっているという部分があると思うのですけども、長寿命化を図ることで。","voiceIndex":72,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、安全性というのは当然ながら、公園という施設には必要なことですので、修繕をするという、補修していくというのは当然必要だし、管理が強化されるということになると理解しておりますので、その辺をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"一方、今回、長寿命化ということで、利用頻度との関係性も、やはりその寿命には影響するのだと思いますが、中央公園の事例は逆の視点ですので、なぜ言ってしまったのかというのがあるのですが、要は、特に子どもにとって、やはり楽しい、一生懸命思い切り遊びたいというものはどうしても頻度が高くなってしまって、寿命が短くなってしまう可能性も出てきてしまうわけですが。","respondent":"高梨公園課長","answer":"１年に１回やってありますので、その中で子どもが遊ぶ遊具につきましては、例えば今年Ｂでしたけど、やはり利用頻度が非常に高くて、利用の状態がほかの公園は違って、一気にＣ、Ｄに近づいたということがあれば、やはりこの計画にとらわれることなくその場、その年。","voiceIndex":76,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、今回の改定は、令和５年９月の改定ですが、最初のものは平成２５年に計画が策定されて、今回改定ということにつながっていますが、今回の見通しとして、縮減効果が９５０万円余ということでありますが、最初の策定時から今回の改定までの間の、いわゆる導入効果というのはどれぐらいで、その金額に対して、今回の９５０万円余というのは、さらに増えたものなのかどうなのか。","respondent":"高梨公園課長","answer":"先ほど健全度調査の、１０年前との比較でもご説明しましたが、今回大分、公園の全体改修も含めて改修が進んでまいりまして、これからの１０年については、過去１０年に比べると、新しい施設も増えてきたということなので。","voiceIndex":78,"id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"森澤区長も事務事業評価、力を入れていかれるということで、この間の決算特別委員会でも、資料を活用させていただきながら議論を進めてまいりましたが、当初の策定からさらに今回はより見直しをすることによって、新たな９５０万円余が出てきたということは、物すごくすばらしいことだと思いますので、ぜひ不断の努力を継続していただきたいと思います。ぜひよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-034"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"そうすると、また、なくなってしまう、もう結局、昭和４４年に西武鉄道から譲り受けたというものの中で、例えばそういったものの使い道の方向性というか考え方というのですか、例えばＳＬを主として、何かほかの都市と、譲り受けたどこかの都市があるでしょうから、何かそういうところとつないでまたこうやって広めていくとか、これちょっと課が変わってしまうのかよく分からないのですけども。","respondent":"高梨公園課長","answer":"一方、今、ご案内がありました東品川公園のＳＬであるとか、戸越公園の薬医門等もほかの自治体等もつながりがあるものだと聞いてありますし、そういったものの扱いにつきましては、この計画の中では事後保全という形で、一定の期間が過ぎたら、やはり壊れてしまうものですね。","voiceIndex":82,"id":"exchange-035"}]},{"id":"topic-04","title":"公園児童遊園等維持修繕工事における未精算金の発生","agenda":"公園児童遊園等維持修繕工事における未精算金の発生","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回の単価契約工事、これはどういうものなのか、仕組みを伺いたいと思います。それと、今回のこの未精算金の発生という事態、これが課長に報告が上がる前に、公園課の職員は何人の方が知っていたのか伺います。","respondent":"高梨公園課長","answer":"２番目に、私への報告前にどの程度の人間が知っていたかですが、問題を抱えていた係が、構成といたしまして係長２名、係員が８名ということで、全部で１０名の係なのですが、係員によってそれぞれ認識の差はありましたが、一定このような状況が起きていたというところは。","voiceIndex":89,"id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"工事契約のところでは、この単価契約工事というのは、公園課以外ではこうした契約をしているところはないのかどうか、伺いたいと思います。そうした視点も含めて、今後の再発防止策については検討していただきたいと思うのですが、いかがでしょうか。","respondent":"高梨公園課長","answer":"こういった問題が、時間がたてばたつほど問題がどんどん大きくなっていくものだというふうに感じておりますので、改めて、軽微なものでも構わないので、問題点、これはちょっと問題になり得るなというふうに感じたものについては。","voiceIndex":91,"id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、全体で、２年分でいくと５,５００万円ほどだという事態になっているということですので、しっかりと今後、プロジェクトチームを立ち上げるということですので、さらに、この原因究明と再発防止、しっかりとやっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"この件は、こういう現状になっていたというのはいつからですかという、令和４年度から起きていて、ということで２年間なのか、それともずっとそういう状況だったのかという、それを教えてください。その影響がどういうものがあったのか。その辺はどうだったのか、完全にこちら側の職員の意識によって滞ってしまったという結果だったのかということをお聞きしたいと思います。","respondent":"高梨公園課長","answer":"管理する場所を一旦まとめてというところも一つの案かと思いますけども、公園の維持補修工事はやはり、区民の方々等からいただいた陳情を、できるだけ機動的にいち早く直して、安全な状況で、また。","voiceIndex":95,"id":"exchange-039"},{"speaker":"西本委員","kind":"確認","question":"このチェックはチェック、違うと思うのです。確認しなければいけない事象というのはとてもたくさんあると思うのです。それで担当にあれどうなっているの、これどうなっているのというぐらいの確認、そういう管理者がいてもいいのではないかなと強く思いますので、そこはちょっとＰＴの中で検証していただいて、職員の意識を改革、大切ですよ、意識改革は必要なのです、でも、やはりそれではミスが起きます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"ご説明を伺いまして、関係事業者の方々へは丁寧な対応を取っていただけているということ、また、先方からもご理解いただけているということで、二度とこういう状況はないようにと、ぜひまた、引き続きお願いをしたいと思います。","respondent":"高梨公園課長","answer":"ＰＴの中でも、そういった内容を取り入れながら、二度と起こさないよう、再発防止策という形で取り組んでまいりたいというふうに考えております。","voiceIndex":99,"id":"exchange-041"},{"speaker":"若林委員","kind":"質問","question":"それからもう一つは、今年度の３８件については、これは年度内処理がされていくというご説明だと多分思うのですけども、令和４年度の５６件については、これは令和４年度の、いわゆる会計処理決算には載らないということで、そうすると令和５年度の会計決算に載ってくるのだろうなと思うのですけど、どういった項目でこれが表記されてくるのか、これもお聞きしておきたい。","respondent":"高梨公園課長","answer":"２番目の、上司への報告前に、いつから共有していたかというところなのですが、全員で共有していたかどうかというようなところなのですけども、係長につきましては、今年度新しく替わっていますけども、その引継ぎ段階で、どうやらそういう未精算案件があるということを知り。","voiceIndex":103,"id":"exchange-042"},{"speaker":"若林委員","kind":"質問・要望","question":"上司への報告のくだりですけども、そうすると、令和４年度の中で、一定の何人かの方が、いわゆる係の中で共有をしていたということで、この年度内処理ということ、最初は、読んだとき、お一人の方の、ということなのかなと思ったら、今のお話を聞くと複数の方の、また、それも管理職ではないけれども、一定の役職、いわゆる部下を持った方のことということで、これは組織的には。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-043"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"やはりヒューマンエラーが起こることはありますが、あるからこそ、あったときに、ではこのチームでどう守っていこうかなという、そういう温かい労働環境が、やはり一番大事なのかなと思っていますので、このＰＴの立ち上げの中で、そういった職員を守るわけではないですけど、十人十色いろいろな考え方がある中で、こういうことがまた。","respondent":"高梨公園課長","answer":"いろいろな職員がいますので、ただ、しっかりとその中でルールづけして、このタイミングではこの日付を必ずこの帳簿に書きなさいとか、それをすることで、別の人が見て、あれ、これ進んでいないけどどうなってるのか、というふうに。","voiceIndex":107,"id":"exchange-044"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"西本委員","kind":"質問","question":"水辺の活用ということで、大分前から品川区は取り組んでいるというふうには認識しております。なので、しっかりやられていると思います。私たちもよく分かっている話だし、課題などもそれぞれ、報告などありますので、認識はありますけれども、将来にわたってと考えたときの大きな視点に立ったときに、この水辺の活用、品川区はどのように捉えていくのでしょうか、ということはいかがでしょうか。","respondent":"北原河川下水道課長","answer":"今、水辺の取組を進めてきているのですが、もちろん区外もありますし、区内でも水辺に近い人に対して浸透してきているのですが、もっと広い意味で、いろいろな方に品川区の水辺を知っていただいたり、来ていただくという取組が大事だと考えていますので。","voiceIndex":114,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"もう民間レベルだと、既にやっているのです。お隣の方々と協力体制を取りながら、議員レベルでも、私は入っていませんけど、そういう活用のための勉強会を開いたり、いろいろな交流を持っているというのはあるのです。その中で品川区の立ち位置とか役割は相当大きくなってくるのではないかなと期待も込めているのですけど、そういう方向では何か動きがあるのか、あったら教えていただきたいと思います。","respondent":"北原河川下水道課長","answer":"やはり委員もおっしゃっていただいたように、民間レベルではいろいろなところと連携しているというお話もありますので、やはり、我々は施設を整備したりしてきたのですけども、それを民間の人にもきちんと使っていただいたり、そういった中で。","voiceIndex":116,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、もう少し広がりのある将来性のある方向にもうそろそろ持っていかないといけないのではないかなという視点があるので、そこは、東京都との関係ももちろんであるし、国の動きもあるので、それから、例えば飛行機の関係であったりとか、いろいろな意味で、水辺にこだわる、そこにとどまるのではなくて、いろいろな方向に、この水辺というところのキーワードということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-047"},{"speaker":"田中委員","kind":"質問・要望","question":"その活用するに当たって、様々な規制があったりするものを行政として緩和するとか、あるいはその活用しやすい環境を整える、水辺に関して言えば水質改善だとか、そういったものに取り組むことが行政としての役割なのかなというふうに捉えているのですけれども、所管事務調査をするに当たって、いわゆる地元の民間の事業者の方々から区に対して、こういうことの規制を緩和してほしいとか。","respondent":"北原河川下水道課長","answer":"施設についてもいろいろ、こういったものがあったらいいとかご意見をいただいているところでして、そちらについても、利用状況等も踏まえながら、今後は、追加の整備が必要なのか検討していくのが大事なのかなと思っています。","voiceIndex":120,"id":"exchange-048"},{"speaker":"田中委員","kind":"質問・要望","question":"様々な場面でぜひ地元の方からの声もしっかりお聞きいただいて対応していただけたらと思いますが、その関連で、東品川海上公園のいわゆる非動力船のＳＵＰとか、ちょっと一段下がったところで乗り入れできるような桟橋ですけれども、ここで乗った以上は、どこか、先行ったところでも降りなければいけないわけで、一つ、地元の声として伺っているのは、例えば五反田の船着場のところに、やはり。","respondent":"北原河川下水道課長","answer":"障害物を取り除く工事の進捗状況というお話かと思うのですが、今、順次進めてきておりまして、今年度でおおむね最下流までやるのですけれども、一部上流の部分で、先ほど目黒区の太鼓橋から品川区の市場橋の辺りで、東京都がしゅんせつの工事をやるという所があるのですが。","voiceIndex":122,"id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"立会川で言えばＪＲの地下水が来ているということもあるのですけども、目黒川で言うと地下鉄の浅草線からも地下水が出ているかと思うのですが、最近、東急目黒線も地下化されていてとか、あるいは、中央環状線で、今度道路のほうですけども、結構地下の施設が増えてきているのですが、そういったところから、まず、地下水が出るのかどうかというのもあるのですが。","respondent":"北原河川下水道課長","answer":"ただ、それが莫大なお金がかかってしまうということで難しいという結論にはなってございまして、今日おっしゃっていただいた視点に近い形で検討はしているのですけども、参考にさせていただけたらと思っています。","voiceIndex":124,"id":"exchange-050"},{"speaker":"田中委員","kind":"質問","question":"目黒区に水質浄化施設が整備中、下目黒一丁目付近ということなのですが、これは、東京都の施設なのですか、それとも目黒区が単独というか目黒区が主体となって造っている施設なのかというのはどうなのでしょう。","respondent":"北原河川下水道課長","answer":"こちらの施設は、品川区でいう立会川に設置されているものと同じものを目黒区が設置するという工事になっておりまして、やはりそこの辺りが一番泥がたまりやすくて、水質の悪化も著しいというところで、目黒区のほうで設置をするものになります。","voiceIndex":126,"id":"exchange-051"},{"speaker":"田中委員","kind":"意見","question":"ごめんなさい、品川区でというのは、月見橋の施設でしたか。品川区のというのは具体的にどういう施設かが、すみません。","respondent":"北原河川下水道課長","answer":"この説明資料の表面の下に、立会川の水質改善ということで、平成２０年度より高濃度酸素溶解水による水質改善を実施ということであるのですが、これは川底に酸素を送って水質が悪化するのを防ぐという施設になっておりまして。","voiceIndex":128,"id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"冒頭申し上げましたように、行政の果たすべき役割として、多くの区民の皆さんに親しんでいただける水辺環境づくりが、まずは、行政としての役割だと思いますし、また、その中には規制緩和だとかも入ってくると思いますので、地元の利用者の声をぜひ聞いていただいて、有効に活用していただけるように取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-053"},{"speaker":"若林委員","kind":"質問","question":"今田中委員が話題に出されたので、目黒区で行われる高濃度酸素溶解水、これ何年前でしたか、もう１０年はたつかな、品川区で、ほぼ同じ場所で、あれも市場橋でやりましたね。その流れで、今回、お隣の区なので、別にとやかく言うことはないですが、例えば、当時の品川区の情報とか、今回目黒区がやるという、それでもやるという、何か目黒区との連携があるのか、まずお聞きします。","respondent":"北原河川下水道課長","answer":"以前、多分平成２０年度ぐらいに目黒川でも実験をやっているというのは、記録としてあるのですが、それが、どうだったかというところまでは今、手元にございませんで、ただ今回、目黒区との関係としては。","voiceIndex":132,"id":"exchange-054"},{"speaker":"若林委員","kind":"提案","question":"先ほど来もありますけれども、いわゆるそういう、例えば、目黒川でいうともう、連携先は目黒区、あと、源の近くでいうと世田谷区も、世田谷区はちょっともう、目黒川といっても全然違う水質のところなので、そうすると唯一、横の連携というと目黒区との連携で、今回こういう高濃度酸素、それは品川区も記録が一定あるというところで経験者ということで、そういう意味でも、まさに。","respondent":"北原河川下水道課長","answer":"私どもとしても、しゅんせつがどのぐらい効果があるかといったところを確認するために毎年調査をやっておりますので、そういった結果も伝えながら、できるだけまずは東京都にやっていただく、それができない場合に、ではどういったやり方があるのか。","voiceIndex":134,"id":"exchange-055"},{"speaker":"若林委員","kind":"質問・要望","question":"社会実験、らくらく舟旅通勤、私も乗って楽しんでまいりましたが、体験させていただいたけども、ぜひ、これから東京都と連携してまた、品川区の社会実験を踏まえて、そういう舟旅、舟運の活用もするというところなので、ぜひ、いろいろな意味で申し上げましたけども、東京都との連携とか、計画を立てた後、仕事がスムーズにいくように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-056"},{"speaker":"のだて委員","kind":"確認","question":"年間の船着場の回数、最初の説明だと、年間、令和４年度は約６００回ということだったのですが、計画策定のところの目標で見ると、現状は年１５０回と書いてあるので、これはどちらが正しいのか、どういうことなのかというところを伺いたいと思います。それと、今回この計画を策定する方向だということで、計画を策定するメリットを伺いたいと思います。","respondent":"北原河川下水道課長","answer":"計画を策定する目的といった部分になるのですが、品川区としては、船着場の整備とかライトアップとか、様々な施設整備を実施してきておりまして、土台となる整備は一定程度、できてきたと考えています。","voiceIndex":138,"id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"水質改善の点はほかの委員の方からもありましたので、ぜひ、進めていただきたいというふうに思うのと、こうした船着場をいろいろ整備して、その周辺での再開発などにつながっていかないようにしていただきたいというふうに思うのですが、それを計画のところでも、そうならないようにしていただきたいと思うのですけども、いかがでしょうか。","respondent":"北原河川下水道課長","answer":"あくまで、今回の計画は開発について定めるものではございませんので、直接この計画でそれが進むということは考えてございません。","voiceIndex":140,"id":"exchange-058"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません、先ほど、冒頭申し上げたように、行政の役割としての取組の中で、まず、社会実験をしたのですけれども、利用者の声としては満足度が高かったということなのですが、いわゆる実験した側の評価というのでしょうか、この実験をしたことによって新たな課題が見つかったとか、これをでは、その実験ではなくて実用化するに当たって、何かその障害となるといいますか。","respondent":"北原河川下水道課長","answer":"地元関係者との関係についてですが、例えば東品川二丁目ですと、もう少し利用が増えてくれば、もう少し緩和しても了解が得られるのかなとか、そういうところも考えているところでして、我々としてどういう提案ができるのか、また、そういう。","voiceIndex":143,"id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4392#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":58740,"voices":147}},{"id":"r05-20231107-9","meetingId":"r05-cm11","date":"2023年11月7日","dateIso":"2023-11-07","committee":"文教委員会","time":"午後 １時００分～午後 ４時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和５年特別区および東京都人事委員会勧告等","agenda":"令和５年特別区および東京都人事委員会勧告等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２つの勧告があるのですが、幼稚園教諭と独自教員、どちらがどちらに関わる勧告なのかというのを教えてもらいたいのと、あと、両勧告の意見とも、メンタルヘルス対策の推進等がうたわれていると思います。現場では、学校と幼稚園では、現状どのような対策が取られているのか、伺えればと思います。","respondent":"中谷指導課長","answer":"２つご質問いただいたうちの１つ目ですが、月例給に関しまして、幼稚園教員は特別区、そして、固有教員は東京都のものを踏まえているというところ、そして、特別給につきましては、幼稚園教員、固有教員共に。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"そこはすごく重要だと。業務負担を減らすということが一番大事なことだと思うのですけれども、併せて、セルフケアですとか、あるいは、先ほど紹介したように、誰でも抱え得る問題であるというメンタルについての知識ですとか、あるいは相談できる窓口とか、そういった点の対策という点ではいかがでしょうか。お伺いします。","respondent":"中谷指導課長","answer":"所属長は、月の平均で高かったという場合に、学校の教職員にも改めてしっかり超過勤務時間の縮減に向けて取り組んでいこうということも投げかけていますし、個別にもしっかり一人一人の先生方と共有すると。","voiceIndex":7,"id":"exchange-002"}]},{"id":"topic-02","title":"令和５年度（６年度採用）品川区立学校教育職員採用候補者選考状況","agenda":"令和５年度（６年度採用）品川区立学校教育職員採用候補者選考状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"２点お伺いしますが、まず、第一次選考のとき、辞退者が４名ということであるのですけれども、その辞退の中身というのがもし分かれば教えていただきたいというのが１つと、もう一つが、６月の文教委員会の報告では、現在、在籍者数が２５名というところだと。今回５名程度採用という報告だったと思うのですけれども、内定者が６名ということなのですが、これはなぜなのかというのをお伺いしたいと思います。","respondent":"中谷指導課長","answer":"今回の採用選考を経ていく中で、総合的に判断をいたしまして、結果としてはプラス１となる６名程度を採用していくということが妥当であるという判断をしたため、今回は１人増えているという状況です。","voiceIndex":13,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"当日何も連絡しないで来ないのだと、少しびっくりしたのですけれども、なかなか厳しい状況だと思います。それと、総合的にプラス１ということで、やはり新年度までに辞退者が出るのではないかという判断が、予想があるということでよろしいのか、そこら辺、理由をお伺いしたいと思います。","respondent":"中谷指導課長","answer":"今回に関してもというところですが、まだそういった予想を立てているわけではないのですけれども、しかしながら、これまでの過去の経緯というところも踏まえながらというところは含めて、今回の判断をさせていただいたというところになります。","voiceIndex":15,"id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"意見","question":"理由の中で、地域とともにつくるという点と、９年の一貫教育、これは募集のときにも品川区のほうで強調しているところだと思いますので、こういう思いを持って入ってきて、採用して、教壇に立っていただく先生方を、なかなか大変なこともあると思うので、教育委員会と、あと、現場の先輩方や先生がフォローして、それこそずっと品川の先生でいていただけるように、支援をぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-005"}]},{"id":"topic-03","title":"令和５年度品川区学力定着度調査および令和５年度全国学力・学習状況調査の結果","agenda":"令和５年度品川区学力定着度調査および令和５年度全国学力・学習状況調査の結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料の分からないところを伺いたいのですが、品川区の調査のほうの、教科に関する調査の結果概要、６番、ここ、棒グラフがありますけれども、「正答率分布」となっておるのですが、全国のほうは、同じようなグラフのところで「正答数」と、異なっているのですけれども、この異なっている理由と、結局、このグラフは違うものだという、何が違うのかというのを伺いたいと思います。","respondent":"中谷指導課長","answer":"全国学力・学習状況調査の同じくグラフの横軸というのは、正答数となっております。正答率と正答数は、換算の仕方が違うものにはなりますが、見方としては同じものであると解釈いただければと存じます。","voiceIndex":25,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。こちらはなぜそうなっているのか、理由などを分析していただいておりましたら、お伺いしたいと思います。","respondent":"中谷指導課長","answer":"一番大事なことは、Ｄ層Ｃ層をできるだけ少なくするという、そのための授業改善というところが最も大事になると考えております。","voiceIndex":27,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"同じ品川区の子どもだと思うのですけれども、学年が進むと、中学校から私立に行く人が増えるということなのかもしれないのですけれども、そこら辺をどのように分析しているのかというのを、なぜそうなるのかというのを、品川区として区教委としてどのように分析しているのか伺ったので、教えていただきたいと思います。宿題のことですか。","respondent":"中谷指導課長","answer":"１つ目の質問ですが、やはり学年が上がるにつれて身につけていくべきものが低まってしまうというところについては、品川区教育委員会としては、一貫教育の９年間の中で、いかにつながりのある子どもたちにとっての学びをしっかり保障していくかというところだと考えていますので。","voiceIndex":29,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は、この結果から、そういう機会を確保するというのはすごく大事だと思っていまして、少し伺いたいのですけれども、品川区では、現在どのように全ての子どもたちが学びに主体的に取り組むという環境、これを整えているのかというのを伺いたいのが１つと、それと、今後、そういう世界の事例なども研究していただいて、様々な授業を幅広く見て、そういう子どもたちが主体的に学びに向かえるような。","respondent":"中谷指導課長","answer":"１つ目のグラフの見方というところなのですけれども、やはり品川区の学力定着度調査というのは、指導者にとっていかに指導を改善できるかという視点がとても重要であると捉えておりまして、今回のこのクロス集計の結果から。","voiceIndex":31,"id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。私から、２点、質問します。これを踏まえて、今後、現場の先生方、学校に対して、理科に関しての指導方法の改善を指導課としてはどのように行っていくのか、教えていただきたいと思います。","respondent":"中谷指導課長","answer":"こういったところでも、約４割程度が、あまり調べていない、そのままにしてしまうと回答している傾向が近年あります。","voiceIndex":35,"id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問","question":"２点お伺いします。１点目が、全国のほうで、５番の各教科の平均正答率の「英語（話す）」のところで、東京都の中学校英語「話すこと」の結果は未提供だとなっていますが、この理由を教えてください。例えば、７、８、９年生で、品川区でも、７年生と８年生の理科が全国平均より低いと。されているのであれば、その傾向はどうなっているか、教えてください。","respondent":"中谷指導課長","answer":"最初のご質問の、全国学力・学習状況調査の英語の東京都の中学校英語の「話すこと」の結果が未提供だったというところなのですけれども、こちら、本日の文教委員会において出したい数値でもあったので、直接、東京都教育委員会にもお問合せはさせていただいたのですが。","voiceIndex":38,"id":"exchange-011"},{"speaker":"石田（し）委員","kind":"質問","question":"でも、例えば、ある学校のある学級では、７年生のときにそうだったけれども、８年生のときには、その学校がよくなったりするときもあるわけではないですか。例えば、今まで理科が全国平均より下回っていたのに、７年生から８年生になったら急に全国平均より高まった学校があったとすると、同じ子が受けているわけだから、その子たちに何かあったわけです。","respondent":"中谷指導課長","answer":"もう一つで、一方で教育委員会としてというところにおいては、先ほど申し上げた教育検討委員会の中で、学校の管理職の先生にも代表として入っていただいておるのですけれども、その中でいい取組というのを積極的に出していただくようにしています。","voiceIndex":42,"id":"exchange-012"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"例えば、ログを拾っていけば、それなりにその学校でどういった調べ方を子どもたちがしていたら学力が上がったのかとか、どういうことをやっていたら、逆に下がってしまったのかとか、特に理科とか、目とか視覚で見るものというのは、こうやってタブレットとかを使うことによって、私は効果があると思っていて、なので、そういったものをどんどん、要は、データはいろいろ昔よりも出てきているわけで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-013"},{"speaker":"ゆきた委員","kind":"質問","question":"品川区の学力調査についても、全国の学力調査についても、調査内容というのが、教科に関する調査と生活習慣や学習環境に関する調査ということで、２項目調査されていると思われるのですけれども、２つ目の生活習慣といったところで、これが私は、生活習慣というと、家庭の中のことも含めてという認識をしてしまうのですけれども、これは学校の中での生活習慣ということで認識はよろしいのかというところと。","respondent":"中谷指導課長","answer":"今、こちらに関しては、教科のほうに焦点化をさせていただいているものになるので、生活習慣や学習環境に関する調査の質問出しは資料の中にはないというところをご了承いただければと思います。","voiceIndex":46,"id":"exchange-014"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"学力の面でも、また、生活習慣とか学習環境というのは密接に関わってくることだと思われますので、その両輪が円滑に回転してこそ、子どもの成長も前進というものがあると思われるので、もちろん生活習慣のところも分析しながら、統計は取っていらっしゃると思われますけれども、どちらの両面についても、円滑に分析しながら対策を取り続けていっていただければと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-015"},{"speaker":"せお委員","kind":"質問・要望","question":"私からは２点お聞きしたいのですけれども、まず、１点目が、先ほど石田しんご委員からもあった質問にも関連するのですが、そういったよくなっていったという好事例とかを共有していただくという点でも、先ほど多分、冒頭のご説明のところでちらっとＣ、Ｄ層でも何か働きかけるみたいなお話があったのですけれども、そこは具体的にどうやって取り組んでいくのかというところを教えてください。","respondent":"中谷指導課長","answer":"そこがなかなかやはり乗り越えていけるかというところで、すごく授業改善の必要性が高まるところであると捉えておりますので、これをいかに品川としては、９年間の英語科の教育をやっておりますので、８年生だけに負荷がかからないような。","voiceIndex":50,"id":"exchange-016"},{"speaker":"せお委員","kind":"質問・要望","question":"Ｃ、Ｄ層に関しては、先ほどのお話と一緒で、そういったＩＣＴなども活用してよくなっていった事例などを共有する場は欲しいと思うので、そういったところもぜひ情報共有する場をつくっていただきたいと。そこは要望いたします。そこで皆さん、生徒が英語を嫌いにならないように、１年生からせっかくやっていて、そこで本当に３０％も低くなるという。そこも要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問","question":"そんなことはないと思うのですけれども、それは業者のほうに、どれぐらいの母数なのかというのを、発注している側としては認識しないと、この結果自体が比較できないと思うのですが、その点はいかがですかというのが１つ。それから、もう一つは、これは４月に行われているので、９年生の結果は、８年生までの学習の成果なのだろうということだと思います。取りあえずお願いします。","respondent":"中谷指導課長","answer":"２つ目のご質問で、授業以外の学びというところなのですけれども、ＩＣＴというのは、やはり家庭の中でどう充実していくかというところで、引き続き研究を進めていきたいと思っている先ほどのお話です。","voiceIndex":54,"id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それが１つと、やはり学校の先生方の負担につながるので、なかなか厳しい部分があるかと思うのですが、勉強合宿とか未来塾で集中的にやるものが多いのですが、やはり１年２年たってから復習するというのはなかなか厳しいところがあるので、ある一定の習った後に、定着していない児童や子どもたちにはそういった定着するような機会を何とかつくっていければいいと思うのですが、その点と。","respondent":"中谷指導課長","answer":"やはりご指摘いただいたとおり、教職員の負担が増えないというところに配慮することがとても大事だと考えていますので、未来塾のように、地域の方にご支援いただく中で、子どもたちの学びを進めるというような取組が非常に大事であると考えています。","voiceIndex":56,"id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、未来塾の話を最後にするのですが、そういう地域の人材を使って学習支援をしているということは大変すばらしいことなのですけれども、そこで教えていただける方に、来た児童や生徒に対して、どこか分からないところはあるかというのではなく、この調査結果などを活かして、その子たちがこういった分野が苦手であるということを、個人情報の範囲がありますけれども、例えば、それを見ながらやるのでも。","respondent":"中谷指導課長","answer":"この辺りは、やはりタイミングを逃さず、子どもにアドバイスをするというところが大事であると考えていますので、そういったところを決しておろそかにしないように、充実できるようにということで、働きかけをしていきたいと思います。","voiceIndex":58,"id":"exchange-020"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"それぞれの委員のご質問の中から大分理解が進んだと思うのですけれども、基本的には、品川区学力定着度調査の中でも、クロス集計というのは、指導方法の工夫、改善等に活かしていくということで、教員の方がこういう結果を踏まえて、自分たちでもう少しこの辺を工夫したらいいということを振り返るということだと思うのですけれども。","respondent":"中谷指導課長","answer":"２つ目の、社会の江戸時代の課題についてなのですけれども、江戸時代の問題への無回答率の高さというところからは、やはりこの時代の製造業の変化がテーマになっているのですけれども、ここをしっかり２つの問屋制家内工業と工場制手工業を比較したりというところで。","voiceIndex":61,"id":"exchange-021"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"それで、やはり課題という言葉一つくくったとしても、なかなかいろいろな課題があると思いますので、それを一つ一つクリアにしていくというのは本当に難しい作業だと思いますけれども、こういうテストをする以上、そのテストが子どもたち一人一人にとっての課題のクリアにつながって、自分たちの成長が考えられるような、感じられるようなものにしていっていただきたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"１点だけ。品川区の学力定着度調査と全国の調査のそれぞれの業者名というのですか。それを教えてもらえればと思います。","respondent":"中谷指導課長","answer":"品川区学力定着度調査の業者は、東京書籍になります。それから、全国学力・学習状況調査については、国立教育政策研究所、文部科学省になります。","voiceIndex":65,"id":"exchange-023"}]},{"id":"topic-04","title":"いじめ重大事態の発生状況","agenda":"いじめ重大事態の発生状況","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"それと、２つ目は、２年前の重大事態では、いじめ対策委員会、今、この４件、調査中になっていますけれども、このいじめ対策委員会の調査報告書に対しても、教育委員会に対して必要な調査が不十分だ等の問題点を指摘されていたわけですが、今回それを受けて、いじめ対策委員会が調査をしているわけですが、調査の方法ですとか、姿勢というのですか。それが何か変わった点はあるのか、伺いたいと思います。","respondent":"米田教育次長","answer":"スピードの問題ですが、これはまた調査結果を踏まえて、細かい詳細、どういう時系列でどう動いてきたかというのは、これから一定程度公表していくような形になると思いますので、その辺のところのご評価は様々な方々からいただくようになると思いますけれども、そういった意味で。","voiceIndex":73,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。もちろんいじめがゼロになるというのが一番いいのですけれども、子どもたちというか、人間の営みですから、いじめの芽というのは常に起こっているのかと思うのです。そこがまさに教育の出番だと思うのですけれども、そこについてはまずどうなのか。いじめをしようという子どもが生まれにくいといいますか、そういう学校をつくるための取組について伺います。","respondent":"米田教育次長","answer":"数多くが、やはり傍観者と言われる人間になります。その辺のところで、いわゆるいじめというのがどういうものがいじめに当たるのかというのは、改めて子どもたちにとっても再認識をしてもらう必要があると思います。","voiceIndex":75,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"そもそもいじめに走ってしまうというのは、いろいろストレスがあると思うので、加害者のほうも様々な問題を抱えている土壌があるのかという思いがあって、先ほどそういった質問をしたのですが、仮にいじめの重大事態になる前の、いじめの芽というのですか、そういうのが生まれたときに、そもそも子ども同士とか、先生を含む学級集団の中で解決できるという学校をつくっていただきたいと思っているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"確認","question":"１つだけ確認したいのですけれども、いじめの重大事態の認定時期というのがあるのですが、いじめをした月というか日と、それから、いじめ重大事態に認定した時期と、それから、ホームページにあるように、教育長から区長に報告した時期、それが、ホームページを見たのですけれども、発生時期から認定する時期まで、きっと調査でかかっているのでしょうけれども。","respondent":"米田教育次長","answer":"いじめの認知が全て重大事態に結びつくというものでもありませんので、それが比較的近いものもあるかもしれませんけれども、基本的には、いじめの認知と重大事態の認定の時期というのは、一定のずれがあるとご理解いただければと思います。","voiceIndex":83,"id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"質問","question":"特に様々、今回大きな問題になったのは、そこの期間が長かったということが問題だと指摘されているわけでありまして、ですから、それは逆に言えば、それだけ現場の先生方が調査して指導していたということももちろん裏返せばあるわけだとは思うのですけれども、そういう意味で、発生から認定までの、これはきっと調査報告のときにお話が詳しく出てくることだと思うので、今日はお答えは結構ですから。","respondent":"米田教育次長","answer":"それで、併せて区長部局のほうにも、書面の正式な形というのはやはり一定の月日がかかるわけですけれども、それ以外にも報告の方法というのはありますので、正式な形と、ある種、発生しているということの区長部局への連絡というのは。","voiceIndex":85,"id":"exchange-028"},{"speaker":"石田（し）委員","kind":"意見","question":"１点だけ。それがきちんとした報告。それをホームページに上げるのはいいのだけれども、議会に報告もそうだけれども、私はその前の段階で、耳打ちという言葉が適切かどうか分からないけれども、区長とその間、話していないわけではないのでしょうと思ってしまう。いろいろな事案で。いじめだけではなくて。例えば、教育についていろいろ区長と教育長が話す機会がある。よろしくお願いします。","respondent":"米田教育次長","answer":"今、一つの事例として、委員から挙げられたようなやり方も含め、コミュニケーションは取らせていただいておりますということは申し上げします。ですので、正式な報告も、あれの件が来たねというようなことで、区長部局とは連携を図っているとご認識いただければと思います。","voiceIndex":88,"id":"exchange-029"}]},{"id":"topic-05","title":"八潮児童センターにおける公金紛失の対応","agenda":"八潮児童センターにおける公金紛失の対応","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"金庫に保管されていた２万２,１００円のうち９,９００円だけが紛失したということなのですが、少し不自然だと思うのですけれども、普通だったら、２万２,１００円全部、盗難であれば盗難すると思うのですが、どう考えたらいいのかというのが１つと、結局、紛失の原因というのは何だったのか。それは判明したのでしょうかというのをお伺いします。","respondent":"藤村子ども育成課長","answer":"紛失の原因としては、先ほど申し上げたとおり、ボランティア報酬として受領した前渡金について、金庫にしまう際にダブルチェックをしていなかったですとか、館長以外の方が金庫の鍵に触れられる状態であったというところがあったのかと考えております。","voiceIndex":95,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"この紛失の捜査というのですか、その後は継続して行われているということなのでしょうか。それとも、そこはもう分からないので、終了ということなのでしょうか。伺います。","respondent":"藤村子ども育成課長","answer":"本件に関しては、まだ紛失か盗難かどうか分からないというところではありますが、こちらに関しては、先ほども申し上げましたが、警察に被害届を提出しておりまして、警察で継続して捜査をしていただいている状態になっております。","voiceIndex":97,"id":"exchange-031"},{"speaker":"ゆきた委員","kind":"確認","question":"１点確認なのですけれども、しかるべき対応がなされて、再発防止と今後の対応がなされていますが、１６日の土曜日の紛失から、１７、１８日という、これは休日だったと思うのですけれども、１７、１８日を挟んで、１９日の動き出しになっている点についてお聞きできればと思っています。","respondent":"藤村子ども育成課長","answer":"１９日の段階で初めて全ての職員がそろって、聞き取り調査というところ、再度の館内の捜索というところをしたので、こちらの記載になっているというところです。","voiceIndex":100,"id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"３番４番で再発防止をするということなので、ぜひ二度と起こらないようにしていただきたいと思います。あるいは、行われなかったとすると、今後、何らかの注意というか、訓告とか、そういうことを行う予定はないでしょうか。","respondent":"柏原子ども未来部長","answer":"もちろん職員に対しては、まず我々の中の組織の中で話はしているところですが、これは別の部署のところから何らかの形で、どういう形のものが出てくるかはまだ分かりませんけれども、今後そういうことが出てくるのであろうと考えていますけれども、二度とないような形で。","voiceIndex":103,"id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、その点は、今、ほかの部署からそういうのがあったということですけれども、そういった結果が出た際には、個人情報のあれもありますから、そういう措置が出たかどうかぐらいは報告していただければと思いますが、その辺、いかがでしょうか。","respondent":"柏原子ども未来部長","answer":"どのような形になるかはまだ分かりませんけれども、そうした事態が起こった際には、しかるべき話といったのは、処分という言い方はあれなのですが、部署との相談になりますけれども、何らかの形でと思っています。","voiceIndex":105,"id":"exchange-034"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。９,９００円というのはどうなるのですか。例えば、この間、夏に問題になったのが、学校のプールの水を出しっ放しで、先生に請求をするという話があって、賛否があって、どうなのだというのがあるのだけれども、今の責任の話ではないですが、この９,９００円を誰がどのように処理をするのかというのを教えてください。","respondent":"藤村子ども育成課長","answer":"こちらは、紛失か盗難かといった内容のところはまだはっきりしていないところなのですが、そちらの内容がはっきりした時点で、どうしていくかということを検討していこうと思っています。","voiceIndex":107,"id":"exchange-035"},{"speaker":"高橋（伸）委員","kind":"確認","question":"ご説明ありがとうございました。１点確認なのですけれども、４番目の(2)、館長以外の職員にも扱わせたということで、今後は金庫の鍵の管理についても職員単独で行わずと記載されているのですけれども、これ、実際の管理というのは、館長が管理しているのですか。鍵の管理。","respondent":"藤村子ども育成課長","answer":"館長から鍵を借りて、金庫の鍵を開けるというような形です。館長が不在の場合は、鍵の置いてある場所から取って、金庫を開けるという形態を取っていたというところです。","voiceIndex":109,"id":"exchange-036"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今回、そのようになったから、これはどうしようもないことだと思うのですけれども、また行政のほうも、こういう事案があって、振込先とか、やはりいろいろ大変な作業の中、今回そのように銀行振込にしたというのは分かるのですけれども、これは本当に残念です。先ほど部長からもご説明あったとおり、今後、こういうことが一切ないように徹底していただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-037"},{"speaker":"吉田副委員長","kind":"提案","question":"細かいお金になると、かなり煩雑になってしまうということもあると思うのですけれども、こういうことが起きた場合には、その後の現金の扱いというのを、基本は総務委員会案件になるのだと思うのですが、この事故が起きた児童センターの所管のほうから、こういうことも工夫すべきなのではないかというような提案がされる予定があるのか、その辺についても伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"その他、児童センター側から何か提案をというところなのですけれども、その点を踏まえて、会計管理室のほうでこういった形の今後の対応というところを取らせていただいているところもあるので、提案を踏まえた内容というのが。","voiceIndex":113,"id":"exchange-038"},{"speaker":"吉田副委員長","kind":"提案","question":"ここは所管の委員会ですので、会計管理室のほうの対応は総務委員会だとして、今回の問題が起きてしまったことの要因はこの辺にあるのではないかというようなことがあれば、ぜひ会計管理室のほうに所管から言っていただきたいと思っての質問なのですけれども、ごめんなさい、繰り返しになってしまっているかもしれませんが、やはりあのとき会計管理室からの制度の見直しというか、変更といいますか。","respondent":"藤村子ども育成課長","answer":"過去の総務委員会の件で、現金の扱いに課題が多いというお話があったというところですけれども、そちらを踏まえて、今、現金でこういった形でお支払いをしている例というのは相当少なくなっておりまして、会計管理室のほうで全庁調査した際も。","voiceIndex":115,"id":"exchange-039"},{"speaker":"吉田副委員長","kind":"意見","question":"分かりました。は二度とこういうことがないようにというのを申し上げるしかないのですけれども、過去の監査意見とかを見ても、なかなかなくならないというのがどうしてかと思うのです。どうしてと追及しても、これ以上のご答弁はないと思いますので、ぜひ今後はこういうことがないようにということで、改めて念押しさせていただいて、私からは以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-040"},{"speaker":"つる委員長","kind":"確認","question":"それがあるかなと思ったところです。１円でも違ったら帰れないのです。そうならないように、毎回、店長とか副店長が現金を確認するのです。これは監査のほうを見ていないのだけれども、そういうまず管理になっていたかというところと、この９,９００円、残を見れば分かるのでしょうけれども、金種別で見たときに、どういう金種がないのかというのが分かれば、参考までに教えてください。","respondent":"藤村子ども育成課長","answer":"前段のところで、新たに手数料等で発生するというところですとか、対面でのお支払いができなくなってしまったというところにつきましては、これまでどおり、ボランティアの方は協力していただいているところですので、しっかり感謝の気持ち等を伝えていきたいと考えていますし。","voiceIndex":120,"id":"exchange-041"}]},{"id":"topic-06","title":"すまいるスクールでの仕出し弁当試行結果","agenda":"すまいるスクールでの仕出し弁当試行結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１回でも利用した児童が約１割ということだったのですが、利用した以外の方というのは、全て家庭から弁当を持参したということになるのか、それとも、昼までいなくて、昼前に帰ったということなのか、そこら辺、どんな感じなのかというのを伺うのと、それと、補助員の方のお仕事の内容と、どんなところに委託されたのかというのを伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"２名来た方につきましては、昼食時の補助ですとか、あと、お弁当が届いたときの引取りですとか、そういったところもご対応していただいたということになっております。","voiceIndex":126,"id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"質問の仕方が悪かったのですけれども、自宅から弁当を持ってこようが、自分で購入したかというのは、別にどちらでもいいのですけれども、昼前に帰った方とかも含めての数字なのかというか、夏休みですから、大体夕方ぐらいまでいると思うのですけれども、昼食を取った方のうち１割がこの仕出し弁当だったのかというのをお伺いしたので、分かれば教えていただきたい。そこら辺はどうでしょうか。お願いします。","respondent":"藤村子ども育成課長","answer":"昼食前に帰られた方もいらっしゃるというところですけれども、このアンケート自体がすまいるスクールに登録している方全体に対してのアンケートですので、そこの利用した方が１割いたという形です。","voiceIndex":128,"id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。大切なのは、私はすまいるに通う子どもたちがいかに豊かな育ちの環境というのですか、そういうのを整えるかということがまず第一で、同時に保護者の子育て支援も行っていくということなのだと思うのです。課題は多いと思います。学校給食でのすまいるの夏季休業中の昼食提供というのは検討すべきなのではないかと思うのですけれども、いかがでしょうか。","respondent":"藤村子ども育成課長","answer":"すまいるスクールの特性上、いつでも誰でも好きなときにご利用いただけるというところがありますので、学校のほうというのが、決まった児童の方が基本的には毎日いらっしゃるというところで給食を出しているので、今のすまいるスクールの在り方としましては。","voiceIndex":130,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"現状で言うとそうなってしまうと思うのですけれども、やはり課題が何なのかとか、そういうほかの事例がないかとか、様々工夫すればできると思うのです。私は、検討はやはり少ししてみる必要があるのではないかと思うのですけれども、それについては、最後いかがでしょうか。","respondent":"藤村子ども育成課長","answer":"いろいろな事例はあるかと思うのですけれども、こちらのほうとしましても、子ども育成課としてどういった形がいいかというところを検討して今の形を試行したというところですので、まずはこの形を試行して、本格実施というところに動かせていけたらと考えております。","voiceIndex":132,"id":"exchange-045"},{"speaker":"ゆきた委員","kind":"意見","question":"すまいるスクールでの仕出し弁当の提供の初日に、我が会派も当日の様子を視察させていただきました。ここで紹介されている保護者の声と、あと、お子さんの声といったところで、アンケートで、共感できる前向きな回答や課題などもありますが、こういったアンケートの中で、すまいるスクールのスタッフのよかった点とか、そういった現場からの声があれば、聞かせていただければと思います。","respondent":"藤村子ども育成課長","answer":"ただ、今回、初めて試行実施という形でしたので、弁当業者のお弁当が例えば９時までに届くとか、少し遅れてしまったですとか、昼食対応で仕出し弁当の方と、ご自宅から持ってこられた方を分けなければいけないですとか、そういった新たな対応というか、出てくる点については。","voiceIndex":135,"id":"exchange-046"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"様々、今後課題が出てくることかと思いますけれども、子育て世代の方々から根強い要望があることですので、今後またさらに引き続き検討していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-047"},{"speaker":"せお委員","kind":"確認","question":"状況も少し確認させていただいた中で、今、ご答弁の中にもあったと思うのですけれども、食べる場所を変えていたのですよね。その準備とかも、すごく早めの時間に集まって、「集まったよね」という確認もきちんとして、上がっていってという。何かそこの部分、すごく最初なので、この試行期間については理解できるのですけれども、今後、そういったところは、今どういう検討をされているのか。","respondent":"藤村子ども育成課長","answer":"そういった対応を取っていくというところが、今回試行実施の中でやっているところなのですが、今後やっていく中で、教室の数でしたり、担当指導員の数でしたり、継続していくと何かしらハードルが出てくるのかというところはありますので、もし本格実施していって、例えば。","voiceIndex":139,"id":"exchange-048"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"このアンケートの数なのですけれども、結果として、アンケートを取った方の中から、利用したという人は３３件という読み方でよろしいのでしょうかというのと、せっかくいろいろな議論もありながら試行してきたことなので、もう少し多くの方からの声を伺う必要があるのではないかというのが、事前の打合せをしたときのうちの会派からの意見でした。ごはんが大盛りでよかったという意見なのですか。","respondent":"藤村子ども育成課長","answer":"対応した者の反応というところですけれども、先ほど担当指導員の反応というのも申し上げたところですが、同様に、今回こういった仕出し弁当の実施をすることによって、お母さん方から喜びの声が聞かれたりですとか、そういったところがございましたということになります。","voiceIndex":143,"id":"exchange-049"},{"speaker":"吉田副委員長","kind":"意見","question":"いや、でも、給食室を使うのは難しいと思うよみたいなのは話合いながら、そうなったらいいねという希望が非常に多いということだけはお伝えしていきたいというのと、それから、会派の中では、このアンケート結果で、利用した人たちというのがそんなに、一定いらっしゃったことについて、成果であるという評価ですけれども、逆の見方をしてしまうと、もう少し利用者が試行した中でわっといるのであれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":145,"id":"exchange-050"},{"speaker":"高橋（し）委員","kind":"確認","question":"第一日野でやるという仕出し弁当というときに、前の課長の、どうしてここなのですかと聞いたときに、条件が４つか５つかあるということで、もう一回それを確認したいので、それをクリアしたのでここにするというお話がありました。それがどんな条件かというのが１つ。それから、本格実施というのはどういう意味なのかということで、３７校の小学校全てやるのかということです。","respondent":"藤村子ども育成課長","answer":"予算につきましては、何校実施するかというところは、今検討中の段階なのですけれども、今回、１校で試行を実施したので、少し増やしていけたらと考えております。","voiceIndex":147,"id":"exchange-051"},{"speaker":"高橋（し）委員","kind":"質問","question":"それぞれありがとうあります。拡大するならば、条件をクリアするかどうか検討と。利用者との関係というお話だったのですけれども、物理的なものとか、逆に言うと、クリアできないのだったら、やらない小学校も出てくるという認識でよろしいですか。","respondent":"藤村子ども育成課長","answer":"クリアできる条件というのは、例えば、配達された弁当を最長で３時間２５度以下で保管できるスペースを確保できるかというところでいうと、そういった環境を確保できる学校があれば要するに実施するというところですので、必ずしもこの５つというところを全てクリアできなければ。","voiceIndex":149,"id":"exchange-052"},{"speaker":"高橋（し）委員","kind":"質問","question":"クリアできないからやらないというわけではないと言われて、なぜ言っているかというと、全校でやらないとすると、あそこの学校でとか、この学校でという話がどうしても出てきてしまうので、それは何らかの理由がきちんとした理由があって、そこではなかなかこういう条件でというような説明ができないといけないと思うのです。","respondent":"藤村子ども育成課長","answer":"私の申し上げ方がよくなかったのですけれども、今回のこの５つの条件を挙げたというのが、今回、仕出し弁当を実施したシャショクラブというところとお話しして、こういった条件であれば、お弁当は安全に配達できるし。","voiceIndex":151,"id":"exchange-053"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"すまいるなのですけれども、利用人数が書いていますが、特別支援児２２０人というのは、３,７００人のうち２２０人という意味なのでしょうかということと、それとあと、医療的ケアを必要とする児童が利用している人数というのは何人なのかというのを伺います。それと、特別支援児と医療的ケア児それぞれについて、受け入れに当たってはどのような体制を取っているのか、伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"医療的ケアが必要な方に関しましては、学校に準じた対応を取っているというところで対応しております。人員については、医療的ケアが必要な方については、看護師を１名つけたり、特別支援の方についても、人数をつけて、加配というような対応を取っておるところです。","voiceIndex":159,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。それと、下のこども冒険ひろばなのですが、やはり貴重な遊びがなかなかできないような、やんちゃ遊びも含めて、機会を提供するひろばだと思っていまして、荏原地区への整備というのが重要な課題があると思っておりまして、様々議会での要望、質疑がありますけれども、荏原地区への整備の考えがあると思うのですが、現状どうなっているかということと、課題は何なのかを伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"こちらにつきまして、課題としては、一定の冒険ひろばという形で今実施してきていない状況で、引き続き今検討事項になっているのですが、何らかの形でやっていけたらいいと考えているところです。","voiceIndex":161,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうですね。公園として整備をしていただきたいと、改めて要望をさせていただきたいと思います。この育成と配置を私は進める必要があると思っていまして、あと、児童センターのほうにプレイワーカーという感じの人というのは配置されているのでしょうか。ぜひ児童センターのほうにも、プレイワーカーの育成を進めながら配置を進めていただきたいと思いますけれども、いかがでしょうか。","respondent":"藤村子ども育成課長","answer":"プレイワーカーの方については、これは委託でやっている事業なので、特に児童センターのほうに配置というところの考え方ではないので、児童センターのほうにこういった方を配置するという考え自体は今のところございません。","voiceIndex":163,"id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"子どもたちに寄り添いながら、子どもたちと一緒に時に遊び、豊かな遊びなどを、育成することを通して、成長などを支援していくという専門性が私はあると思いますので、ぜひ現在、冒険ひろば等で活躍されているプレイワーカーの役割などをしっかり把握していただいて、広げていただくよう要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":165,"id":"exchange-057"},{"speaker":"ゆきた委員","kind":"質問","question":"先日、文教委員会で兵庫県尼崎市のユース交流センターの視察に行かせてもらったのですけれども、その中でも、ユースワーカーが大学生とか、そういった研修を受けた方が児童センター、各拠点に配置をされて、いろいろな相談事に乗ったりとか、そういう取組を行われているというところで、ある一定の成果を出されているというところもありましたけれども、こういった観点から、今後の考え方といったところで。","respondent":"藤村子ども育成課長","answer":"そういった機能を複合的に使っていくという形で対応していけたらと考えております。","voiceIndex":167,"id":"exchange-058"},{"speaker":"ゆきた委員","kind":"質問","question":"最後、１点だけ。児童センターの職員の年齢層というか、概算で大体このぐらいの年齢層がいますというのが分かれば、教えていただければと思います。","respondent":"藤村子ども育成課長","answer":"児童センターの職員の年齢なのですけれども、以前も委員会で説明さしあげているところがあるのですけれども、５０代より上の職員と、あと、３０代以下の職員というところで、二極化しているというところが今のところあります。","voiceIndex":169,"id":"exchange-059"},{"speaker":"せお委員","kind":"質問","question":"行けないというのもありますし、それでいいのかというお話もあったりして、現在、把握している範囲で大丈夫なのですけれども、そういう特別支援児で、このアンケートだと１,８２０人、自宅でいらっしゃるのですけれども、中学生、高校生とかでいわゆる障害があるお子さんとかは、どれぐらいのお子さんが、例えば児童センターを利用していたりとか、ほかもそうですけれども。","respondent":"藤村子ども育成課長","answer":"子ども育成課のほうでは、すまいるに登録されている方ですとか、そういったところは把握しているのですけれども、中高生の方というところまではデータは持っていない形になるので、お答えしかねるところです。","voiceIndex":172,"id":"exchange-060"},{"speaker":"せお委員","kind":"提案","question":"厚生委員会のほうとかにもなってくると思うのですけれども、でも、福祉のほうではなく、ここにも書いてくださっているインクルーシブでという意味でいくと、今後、私もこれから他の自治体とかがどのようにやっているのかというのを調べようとしていたところなので、まだそんな私からこうしたほうがいいのではないかという提案はできないのですけれども、児童センターがこうやって。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":174,"id":"exchange-061"},{"speaker":"高橋（し）委員","kind":"質問","question":"児童センターのところで、中学生、高校生とあるのですけれども、中学生、高校生が右側にあるようなことをしているのはいいのですが、遊びはもちろん大事なのですけれども、そこに一歩踏み込んで、中学生とか高校生、特に高校生の活躍の場というか、ほかの自治体などだと、所管を越えてしまうか分からないのですけれども、多摩市とか富田林市などは、高校生が主役になって、様々な自治体の問題点とか。","respondent":"藤村子ども育成課長","answer":"長期基本計画のほうで記載している子ども・若者センターというのは、どちらかというと、生きづらさを持った若者というところと、今、委員おっしゃられたように、前向きな若者というところを両方支援していけるような役割というところはあると思いますので。","voiceIndex":176,"id":"exchange-062"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。すまいる、児童センター、こども冒険ひろばとありますけれども、これ、年間、件数とかではなくていいので、大体肌感覚で、ほかの自治体から視察に来られる方はどのくらいいるのか。結構いますとか、ほかの課からすればそうでもないですとか、肌感覚でいいので、それが大体どのくらいいて、その方たちが実際何を見に来ているのか。分かる範囲で教えてください。","respondent":"藤村子ども育成課長","answer":"冒険ひろばにつきましても、たしか大学の教授の方が見に来たいという話をしたりしているというところなので、やはり子どもの発育という中で、自然の中でなかなかできない体験をして、家の中のゲームとかではなくて、土とか砂を触ったりとか。","voiceIndex":181,"id":"exchange-063"},{"speaker":"石田（し）委員","kind":"質問","question":"特色的なことをやっている。品川区はそんなにメニューがあるのだねというので評価をいただいて、詳しく教えてくれと言われたので、改めて品川区の児童センター、そうやっていろいろやっているのだと。なので、ぜひそういった視点も持って、さらに発展をしていただけると、もっといいものができてくるのかと思うので、ぜひそういった視点も持っていただければと。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":183,"id":"exchange-064"},{"speaker":"吉田副委員長","kind":"質問","question":"いろいろありがとうあります。それで、先ほど児童センター職員の年齢層のご質問があったのですけれども、例えば、職員として働いておられる方の資格といいますか、どのような経歴というか、どういうことを得意分野としておられるのかということを伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"ただ、保育士の方だからといって、小さいお子さんの相手しかできないということではなくて、最初は若干戸惑うところはあるかもしれないですけれども、保育士の方だったとしても、児童センターのほうでしっかり一緒にバンドをやっていたりとか、大きいお子さんというか、中学生。","voiceIndex":185,"id":"exchange-065"},{"speaker":"吉田副委員長","kind":"質問","question":"おっしゃるとおり、本人のそういう資質というところが一番大きかったりするのかと思いますけれども、いろいろな経歴を持った方がいらっしゃると、それぞれの学び合いとか、そういうこともうまくいくのかと思います。児童センターというのは、よく、前、私も質問の中でも使ったのですけれども、斜めの関係というのでしょうか。そういうことが体験できるいい場所かと。もし何かありましたら、お願いいたします。","respondent":"藤村子ども育成課長","answer":"様々な職員がおりますので、その職、資格にこだわらず、例えば、こちらの資料に書かせていただきましたけれども、ティーンズミュージカルですとか、ミュージカルというのを趣味にして、得意にしていたりする方がいたりとか、バンド活動が得意な方がいたりとか、いろいろな皆さん。","voiceIndex":187,"id":"exchange-066"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"時間を忘れてほしいという。だけど、北浜のほうの運営を受託している方が、ここはサンクチュアリは無理なので、ここはどちらかというと、昔の道路遊びをみんなで子どもたちがしていて、それを近所の人が見守るというような場としての冒険ひろばというのでいいのではないかと思って運営しているというお話を伺ったことがあるのですけれども、その視点もすごく大事だと思います。これは要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-067"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、自宅で過ごしているというのが１,８２０人と書いてあるのだけれども、コロナだったから自宅で過ごしているという、私はそういう取り方を持っておりまして、すみません、このアンケートというのは、毎年やっているのかどうかということと、あと、もう１点は、このアンケートの回答者の対象が区内小・中・高生等２,０４４人となっているのですけれども。","respondent":"藤村子ども育成課長","answer":"令和３年度はコロナの影響で、確かに自宅の比率が多かったというところはあるかもというところはありますが、アンケート、こちらは毎年取っているわけではなくて、児童センターのあり方検討というところに合わせてアンケートを実施したという形になっております。","voiceIndex":191,"id":"exchange-068"},{"speaker":"高橋（伸）委員","kind":"意見","question":"そうすると、分析すると、もっと伸びてもいいのかと思うのだけれども、これはコロナの令和３年度だから、登録していたのだけれども、自宅で待機しているという取り方でいいわけですよね。以降、もしアンケートを取るのであれば、登録している方をアンケート対象にしているわけだから、そうすると、すまいる、学童、児童センターの伸びというのも当然、伸びるということですよね。","respondent":"藤村子ども育成課長","answer":"恐らく推測でしかないのですけれども、コロナの関係で、児童センターにいらっしゃっている方にアンケートを取ったのですけれども、児童センターが伸びなかったという形になっているかと思いますので、次回、もしアンケートを取るという形になった場合には。","voiceIndex":193,"id":"exchange-069"},{"speaker":"高橋（伸）委員","kind":"質問","question":"アンケートというのは、例えば、３年に１回とか、５年に１回とか、少なくとも計画で何かそういうアンケートというのをいつやるというのがあるのですか。","respondent":"藤村子ども育成課長","answer":"アンケートはあり方検討というのを行うためにアンケートを取ったので、定期的に取っているものではないです。","voiceIndex":195,"id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5112#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":70467,"voices":201}},{"id":"r05-20231107-5","meetingId":"r05-cm11","date":"2023年11月7日","dateIso":"2023-11-07","committee":"総務委員会","time":"午後 １時００分～午後 ２時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"先ほど申し上げましたとおり取り上げる順番を変更し、初めに、(2)八潮児童センターにおける公金紛失の対応","agenda":"先ほど申し上げましたとおり取り上げる順番を変更し、初めに、(2)八潮児童センターにおける公金紛失の対応","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"なかなかお金の管理というのは難しいかと思います。自分自身もちょっとどこかに置いておいたものがなかなか見つからないということも多々あります。非常に残念だと思います。事務的なもの金銭的なものが出てくるので、今後こういうふうにしたということですが、どう対応していくか。人間ですからやはり間違いはあるかと思います。今後注意して対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"令和５年職員の給与等に関する報告及び勧告の概要","agenda":"令和５年職員の給与等に関する報告及び勧告の概要","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"勧告の概要ということでお聞きしましたが、それについてはやはり大手ではなくて、一般区民の意見とすれば、今回公民比較の結果ということで職員の給与が人事委員会勧告で出されましたが、我々が聞いている話ですと、民間の中小企業レベルでは、零細企業もいらっしゃいます、個店のお店もありますが、逆に皆さん大変な中、このような給料はやはり頂いていない、所得がないというのが。","respondent":"崎村人事課長","answer":"ただ、今回公務員全般的に上がったのですけれども、この給与勧告については、基本的には人事院の指針に基づいて同種同等の業務を行う民間従業員の給与を広く把握して反映させるといったことですとか、また、企業規模でいいますと５０人以上。","voiceIndex":11,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"このまま減ってきて、というよりこれはどこかで回復できるのですか。それが非常に心配なのです。やはり人事というのは人を集めて、そういう方たちに区で働いていただくということが大事でして、区で働くということは多くの区民を支えるのだからそれだけ人材もいなければ駄目だということを考えると、非常に先行きが心配されるデータがあるのですけれども、そういうのは大丈夫なのですか。教えてください。","respondent":"崎村人事課長","answer":"初任給の引上げにつきましては、民間のほうでも例えば大卒ですと民間企業で大体５割弱の企業が初任給を引き上げているというようなところ、高卒でも６割弱の企業が引き上げているところ。","voiceIndex":13,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後にちょっと意見だけなのですが、皆さんもご存じのとおり、この品川区近辺、周りの区も含めて家賃がすごく高騰しているのです。私はぜひ若年層に対しては借上げ住宅とか、それから災害対策住宅を何とか確保して、若い人を品川区に職員として残して、それで区民のために働いてもらうように努力をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"意見","question":"今、須貝委員からこういう話があったので、ちょっとだけ触れようかなと思ったのです。だけれども、２０代の後半ぐらいから３０代の、２５歳から３５歳ぐらいまでの間、ここのやりがいがどうしても私は問題だと思っています。だからそう考えるのであれば、そういうところだってもう手を打ちますよとやっていくしかないわけだから、ぜひそこら辺を考えてほしいなというので、何か意見があればいただきます。","respondent":"崎村人事課長","answer":"今回の人事委員会の勧告の中で、職員のやりがいを高める環境づくりということも触れられておりますけれども、環境づくりについては、ここに述べられておりますテレワークですとか時差勤務制度については取り組んでいるところで、今後拡大していきたいと考えているところです。","voiceIndex":17,"id":"exchange-005"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"東京都のページに行ってしまうのは課長も分かって、東京都に「すいません、変えてください」と言って、だから品川区はデータを出さなくてはいけないわけだけれども、そうすると東京都のほうは囲ってあるわけではないですか。そこに至るかどうかは品川区ではなかなかできない。こういうのはどうしたらいいのですか。というか、どこで誰がやるのという意味で、どう思っていらっしゃるのかなと。","respondent":"辻広報広聴課長","answer":"やはりアクセシビリティ、そういったことで返事をするというような、区の中での調整は広報広聴課のほうでさせていただきました。ところが、都との関係ですとか、よそとの関係ということですと、そこまでは実態としては今はできていないところです。","voiceIndex":24,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここに書いてあるとおり、歴史と文化とかいうのを、いかに品川にはこういう歴史と文化と面白いことがあって、これから売り出してほしいということで、今、ケーブルテレビの方は結構食いついていただいて、取材を進めてもらっています。再来年の５月に完成させるのですけれども、ケーブルテレビの方々にその話をしたら結構乗っています。年間予算が３,０００万円ぐらいしかないから。要望です。","respondent":"辻広報広聴課長","answer":"私のほうに区内の方ですとかいろいろな方からいろいろな情報をいただいて、それを例えば広報しながわで取り上げようとか、今申し上げたように「いいわ！しながわ」で取り上げよう、ケーブルテレビの番組でとか、いろいろ考えるわけですが、まずそのネタですね。","voiceIndex":26,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"意見","question":"だから、せっかくそういうのだったら区のほうでそういう人を任命して、その人が取材を受けたらとか、もっとどんどん情報を取ってきてください、その人がもし取材を受けたり何なり、そういうのはどこでもオープンでいいよぐらいの、何かそういう制度みたいなのをつくるということも、結局そういう今の法律が駄目だから、法的に、それはしようがないのだけれども、だから、そういうのではないところのものを。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-008"},{"speaker":"須貝委員","kind":"意見","question":"それならばシティプロモーション課というものをしっかり明確に作って、そこを推進していく。ただ、もう人も要らない。いや、品川区というより品川駅が品川区だと思っている方が多いので、品川というのは宣伝する意味があるのかどうか私には分からないのですが専門家にやはり入っていただいて一緒に取り組んでいくということは大事だと思うのですが、その辺広報広聴課長のご見解をお聞かせください。","respondent":"辻広報広聴課長","answer":"他自治体なんかで広報の専門家的な方を採用するというところもありますし、そういう検討をしたこともありますが、今のところそういう方は雇わないで、自分たちでこういう品川を作りたいという、こういう宣伝をしていきたいという意思の下に。","voiceIndex":30,"id":"exchange-009"},{"speaker":"須貝委員","kind":"意見","question":"今回の視察ではやはり事業部として立ち上げて、その方たちがどんどん率先して進めていく。コマーシャル、写真でもポスターでも、それから商品紹介など、やはりそういうところまで突き進めるには私は専門家がいないと難しいのではないかなと思います。意見だけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"２点目が定住人口を増やしていく。３つ目が、シビックプライドと言われている、今いる人たちのプライドを上げていくという、この３つがあると思います。だからこの政策なのだと。この点を、区長も代わられたということもありますので、もう少し目的と目標を、そしてそこからの事業ということで明確化していくということが大事ではないかと思いますけれども、ご見解を伺えればと思います。","respondent":"辻広報広聴課長","answer":"この右下の図にも示しているような大きな目標があって、それにひもづいたものがある。それぞれにＫＰＩなり目標の指標というのが必要になってくるかなとは思っておりますので、それはこれからいろいろ調整する中で課題となって考えていくところかなと考えています。","voiceIndex":34,"id":"exchange-011"},{"speaker":"大倉委員","kind":"確認","question":"すみません、ちょっと確認も含めて教えてください。目的のところで、当初のメインターゲットは若い女性だったと書いてありますけれども、今は違うのですか。どの世代が、例えば若い世代なのか、年配の方たちがさらに愛着を増やしていくのかとか、そういうような考え方はどうあるのか教えてください。","respondent":"辻広報広聴課長","answer":"住んでいる人が幸せなまちで盛り上げていこうとなれば観光にもつながっていくものですので、そこを起点として相乗効果で品川を活気づけていくというのがいいのかなと考えています。","voiceIndex":37,"id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"分かりました。周りの品川区に最近引っ越してきましたとか、ここ何か月で引っ越してきましたという人とお話しすると、本当に品川区は住みやすいですよねというお話をすごくされています。何で引っ越してこられたか。大変かもしれないですが、そういう声を聞けるような何か取組とかというのはどうですかというのは、いかがでしょう。","respondent":"辻広報広聴課長","answer":"もうちょっと大きい量的な調査として、今、転入時のアンケートというお話ですが、紙のアンケートではなく、何かＱＲコードを読んでとか、そういった形などは今後もうちょっと気軽にアンケートなり、小さな単位での調査というのはできるかなと思いますので。","voiceIndex":39,"id":"exchange-013"},{"speaker":"大倉委員","kind":"質問","question":"ぜひいろいろなインターネットを使ってのアンケート、もう既に区もやられていたりするところもあるのかななんて思っています。行政の箱物を造るというところになりますけれども、そういった何か一つ大きな柱を行政以外で民間も活用しながらという考え方もできるのかなというところで、そういった民間活用とかというところの視点というのはどのようにお考えなのかというのを教えてください。","respondent":"辻広報広聴課長","answer":"これからのシティプロモーションの進め方というようなご質問かと思います。","voiceIndex":41,"id":"exchange-014"},{"speaker":"大倉委員","kind":"質問","question":"そうするととんがると最後には判断が結構大変になってくるなというところで、でもとんがらないとなかなかシティプロモーションとして埋もれちゃう部分があるかなと思っているので、ただそこの判断が難しいなと思っているのですが、ぜひチャレンジしてもらいたいと思っているのですけれども、その辺はハードルがあるものの、いろいろ前向きにやってもらいたいと思うのですがいかがですか。","respondent":"辻広報広聴課長","answer":"割と振り切ってやると目立ちやすいのですが、ではそれ以外の、スポーツ契約した後に高齢者の人のと、いろいろな面があり、そこにあまり気を遣い過ぎると総花的になって結局どこにも刺さらないというようなことはあるのかなとは認識しております。","voiceIndex":43,"id":"exchange-015"},{"speaker":"塚本副委員長","kind":"質問","question":"最初に、今の品川区の地域というのですかね、そんなところの認識をお伺いしたいと思います。こういうところでいくとやはりシビックプライドみたいな、そういったところのシティプロモーションというのに結構重きを置いたほうがいいのかななんて思うのですけれども、その点、今の品川区の今後のシティプロモーションについての考え方を伺いたいと思います。","respondent":"辻広報広聴課長","answer":"それで地域にそのままいる方ともまたつながりができていくというのが理想かなと思っていますので、そういうことを私たちだけが仕掛けるのでなくて、区民の方と一緒にできていくのが理想かなと思っています。そんな活動を来年度はしていきたいなと思っています。","voiceIndex":46,"id":"exchange-016"},{"speaker":"塚本副委員長","kind":"質問","question":"今後またそういう、今は品川区というのはそういう意味では選ばれる、住んでもらえる形になっているかなと思いますけれども、本当に長期的に見れば日本全体の人口は減っていくので、シティプロモーションは長期基本計画とかとは違って適宜計画の期間を決めないので、適宜な見直しというか、そういうのはどう入れるべきなのかなというようなことがひとつあると思うので、その点について最後にお聞きします。","respondent":"辻広報広聴課長","answer":"そういった意味では、それは今回の反省というか課題であったと思いますので、これだけ社会の状況や人々の考え方がいろいろ変わる状況の中では適宜、ＫＰＩを達成したからそれがオーケーか、そういうことではなくて、やり方や課題を見つけながら方向は柔軟に変えていくだとか。","voiceIndex":48,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"意見","question":"すみません、最後に１点だけ。中途でそういう方が来られてうまくいく場合と、その人が来てしまってどうするのだ、５年間と。任期付で一応５年間だけれども、それは品川区の職員の人もしっかりやれているから、しっかりやれるからこの部分はオーケーだよという考えで来られた。だから多分感想でも同じことを言うけれども、こういうことが起きていると私は思っているということだけお伝えします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2280#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":26193,"voices":55}},{"id":"r05-20231108-14","meetingId":"r05-cm11","date":"2023年11月8日","dateIso":"2023-11-08","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時４２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"松本委員","kind":"質問","question":"これは参考で載せていただいている手引きの素案なのですけれども、私がいろいろ聞いていたところでは、エレベーターについて、車椅子の方が乗られるときには、前から乗っていくので、降りるときに後ろが見えないということで、かごの奥に鏡をつけたほうがいいのではないかというふうなことについて、いろいろなところで聞いてきたのですけれども、そういったところは、今回は記載はないのでしょうか。","respondent":"山下新庁舎整備課長","answer":"こちらにつきましては、ただいま委員ご紹介あったように、車椅子等のご利用者の方が、もちろん後ろに目がついているわけでございませんので、なかなか視認性が難しいというところ、また、現在の庁舎におきましても、本庁舎でありましたり、第三庁舎でありましたり。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"今回、２４０件という、私の感覚ではすごく多い、障害者団体が７団体で、性的マイノリティ支援団体、あと、各世代でということなのですけれども、かなり多いご意見があったようですけれども、この内容は、例えば障害種別でも様々あると思うのですが、この素案には、まず網羅的に反映を、少し難しいところはあるかもしれません。２点、お伺いしたいと思います。","respondent":"山下新庁舎整備課長","answer":"委員、今おっしゃられたところの網羅的というところが、どこまで完全にとか、完璧にというところでは、必ずしも１００％ということではないかもしれませんけれども、いただいたご意見を踏まえて、代表的なところではありますが、今回。","voiceIndex":9,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２４０件全てをというのは難しいと思うのですけれども、例えばですが、ここの資料の中には出てきていないところで、こういうご意見があったのだけれども、反映というところまでには踏み込めなかったというものがあれば、ご紹介をいただきたいということが１つです。それをお伺いします。","respondent":"山下新庁舎整備課長","answer":"反映という点で難しかった点ということですけれども、今回、配慮するですとか、そういうふうな形でつくっていく、設えていくという表現ではないところでは、主なご意見の３点目、「また」以下に記載をしておりますが。","voiceIndex":11,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今回、リフトの話があって、確かに難しいなというのは私も今聞いていて素人ながら思ったところですが、今回の中で、カームダウン・クールダウンルームというような表現もあったりして、正に当事者の方からのご要望ということで、こういうものを設置するというようなことが検討の中に入ってくるというところで、当たり前なのかもしれませんが、あとはもう本当に面積との兼ね合いなのかなと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"山本委員","kind":"質問・要望","question":"今、ウェブサイト上で広く一般の方々にご覧いただいて意見をもらっているという段階だと思っておりまして、素案としてできているものは非常にそういう多くの意見が反映されたものだと理解しているのですが、これ、せっかくなので区民の方々にできるだけ見てもらえたほうがいいのではないかというふうに思っておりまして、これはページの。","respondent":"山下新庁舎整備課長","answer":"１点目の子育て世代ですとか、若者世代の方のヒアリング、何件ぐらいご意見をいただけたのかというところですけれども、子育て世代、オアシスルームの利用者につきましては、およそ２０人ほどの方、２０件という形でカウントしておりますけれども、ご意見を頂戴しまして。","voiceIndex":15,"id":"exchange-005"},{"speaker":"山本委員","kind":"質問・要望","question":"ご回答ありがとうございました。オアシスルームの方々や若者世代の皆様の人数等を教えていただき、そして、その中で出てきた意見をこのように反映いただいているということが分かりまして、とてもよいことだと思いました。アクセシビリティの手引き以降も、新庁舎検討に当たって、様々ご意見を聞く機会があると思いますので、同じような形で進めていただきたいと要望いたしまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"先ほど課長からも、若い人の階段というのも、当然それがある中で、障害をお持ちの方も、それぞれ障害、機能が違うので、今、福祉のまちづくり条例の蹴上、踏面は確認できましたけれども、基本的にこれから高さとか基本設計に入っていく中で、これ、本当にいろいろ議論が、多分この階段に関しては、いろいろ議論があると思うので、それは今後、事細かく障害者団体。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"すみません、トイレのことで少し教えていただきたいのですけれども、意見の中にもオールジェンダートイレを導入してほしいというようなことで、今、世の中の要請として、こういったことに応えていくということは必要なことというふうに考えますけれども、こちらの資料の０８のトイレのところの図を見ると、これ、こういったオールジェンダーということの要望の解といいますか、答えとして。","respondent":"大友新庁舎建設担当課長","answer":"トイレとか更衣室などの性属性を示すピクトグラムにつきましては、基本的には文字を併記することと、補足的に配色で識別できることを検討するというところで考えているところではありますけれども、まだ現状、性別に関係なく入れるトイレにつきましては。","voiceIndex":23,"id":"exchange-008"},{"speaker":"塚本委員","kind":"質問・要望","question":"今の段階では、これだというものがなかなかないのかもしれないですし、やってみると、いろいろなところから、いや、これでは困るというお話が出てきたりとかすることがいろいろ想定されるので、大変悩ましいところなのだろうなというふうに思うのですけれども、少なくとも個別に１つの個室を設けるということは、このオールジェンダーということを要望されている方々か、お一人かは分からないですけれども。","respondent":"山下新庁舎整備課長","answer":"やはり男性の介護をされている女性の方が男性トイレにご入室されるのは、なかなかハードルが高い、また逆もしかりという中で、性別のいかんを問わずご利用いただけるお手洗い、個室のトイレを複数設置することで。","voiceIndex":25,"id":"exchange-009"},{"speaker":"えのした委員","kind":"質問","question":"なので、その辺を逆に新庁舎全体で誰もが使いやすいではないですけれども、音とか、光ですとか、色ですとか、そういった精神面、心理面に作用するような落ち着いた雰囲気が、障害者にかかわらず、区民の皆様にとってはいいのではないかなと考えますが、その辺、お聞かせ願えますでしょうか。","respondent":"山下新庁舎整備課長","answer":"１点目のリフト、またそれはスペースを要するというところにつきましては、委員ご指摘のとおりでございまして、そういった点でもやはりハードル、課題があるのかなというふうに受け止めてありますので、手引き（素案）の中でも、今回、設置するとか、配慮するということではなく。","voiceIndex":28,"id":"exchange-010"},{"speaker":"筒井委員","kind":"確認","question":"トイレについてなのですけれども、このイメージ図ですと、かなり幅広い面積をとるのかなと。面積のことはほかの委員もありましたけれど、これ、全フロア、このような同程度の面積のトイレを設置するのか。トイレに限らずですけれど、この素案のいろいろなイメージ図、イメージ図と言っていいのですか、これはあくまでもイメージであって確定ではないということでしょうか、その確認をしたいです。","respondent":"山下新庁舎整備課長","answer":"したがいまして、０８トイレというところも、どうしても注釈でしたり、ご説明をしたい項目を書いていきますと、このような大きなトイレが１つ出来上がっているような見え方にはなっておりますけれども、全てのフロアにこの形が全部整うということでは必ずしもございませんで。","voiceIndex":31,"id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"性的マイノリティ支援団体のご意見として、トイレについては少し記載がされておるのですけれども、そのほかにも性的マイノリティ支援団体から何かこうしてほしいとか、そういったご意見、ご要望はあったのでしょうか。","respondent":"山下新庁舎整備課長","answer":"したがいまして、今回、プライバシーに配慮した鍵により施錠ができるよう配慮という形をとることで、それは性別を問わずご利用いただけるようなというところも含めた配慮をしてまいりたいと考えています。","voiceIndex":33,"id":"exchange-012"},{"speaker":"筒井委員","kind":"質問・要望","question":"窓口カウンターのところで、私、ホームページに記載のイメージ図も見ているのですけれど、やはり今後、重層的支援体制も始まりますし、いろいろな方々が来て、そこでご相談とかお悩みをお話しされる機会もあるかと思うのですけれど、これ、隣接した個室相談ブースを設けるということなのですけれども、そうなる前に、窓口カウンターで隣の人に話が聞こえないような。","respondent":"山下新庁舎整備課長","answer":"窓口カウンターですけれども、先ほどと同様、手引き（素案）におきますこちらのイラストといいますか、絵については、あくまでも例示ということで、いわゆるハイカウンター、立って応対するようなところは、今現在の庁舎でもあまり仕切りはないかと思うのですけれども。","voiceIndex":35,"id":"exchange-013"},{"speaker":"筒井委員","kind":"質問・要望","question":"はい、分かりました。ぜひプライバシーに配慮した設えを積極的に検討していっていただきたいと思います。それで最後に、今のオープンハウスとか、電子申請フォームを用いて意見を募るということなのですけれど、まだまだ知らない方がいらっしゃるかなと考えていますので、もう１回広報をするとか、意見を募る期間の延長はお考えではないでしょうか。","respondent":"山下新庁舎整備課長","answer":"広報しながわは、先ほどご紹介申し上げましたとおり、１０月２１日号に掲載をしておりまして、こちらを重ねてというところまでは、現状考えてございませんけれども、ＳＮＳでの配信というところは重ねて行ってまいりたいと考えていますので、今週土曜日の武蔵小山と。","voiceIndex":37,"id":"exchange-014"},{"speaker":"松永委員","kind":"質問","question":"私からは２点あるのですが、１点目は、駐車場についてなのですけれども、今、品川区役所にあるか分からないのですが、福祉車両車が止められるようなところの設置をぜひお願いしたいということと、一般のトイレ、小便器のほうなのですが、今、現庁舎では水が出ないものがあるのですけれども、ぜひそれも水洗になるのかどうかということをお聞きしたいなという、案がありましたら、お願いします。","respondent":"大友新庁舎建設担当課長","answer":"２点目、トイレが水洗になるのかどうかというところにつきましては、そこの部分についての決定は、まだ設計上進めていないところですので、これからの整備検討の中で検討してまいりたいと考えているところです。","voiceIndex":40,"id":"exchange-015"},{"speaker":"松永委員","kind":"質問・要望","question":"駐車場のことについてですが、入り口の近くとか、エレベーター近くとか、ぜひ設置していただきたいと思います。今、水が出ない小便器ですけれども、やはり臭いがきつくて、やはり水の出るトイレのほうがいいかなというふうに思っておりますので、要望ではありますが、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問","question":"端的に３つお伺いします。２番目のこの素案について、ご意見をお伺いした２４０件を出していただいた団体とかについては、これはフィードバックを個別にしているのかどうか、こういう形でまとめましたということでお知らせをしているのか、それとも、一般の方と同じように、ホームページ等をご覧になって、追加があれば言ってくださいという形にしているのかというのが２つ目です。この３点を教えてください。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"トイレにつきまして、バリアフリートイレ、なぜ職員が使うものと、不特定多数の方が使うところで広さが３０cmほど違うのかというところなのですけれども、まず１点目として。障害者団体の皆様は、もちろん区内にいらっしゃるというところもございまして、明日以降になってまいるのですけれども、また素案の検討会と同様に、７団体の皆様が２回ぐらいに分かれまして、素案の報告ということで。","voiceIndex":44,"id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問","question":"ありがとうございました。１点目については分かりましたが、職員の方でも外国製の車椅子の方もいるかもしれませんので、その点も含めて、言っていることは分かりますよ、言っていることはよく分かりますし、十分な広さはそもそもあるのだからということは分かるのですけれども、あまり区別するのも申し訳ないかなというところもあって質問をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-018"},{"speaker":"せお副委員長","kind":"質問","question":"１点だけお伺いします。こちらで書かれているベビーケアルーム、授乳室なのですけれども、素案を見させていただいて、それも併せて少しお聞きしたいのですけれども、まず、いただいた資料で、主なご意見のところで、授乳室は安全でプライバシーに配慮した場所に設置してほしいと、これがあるのですけれども、まず、これ以外に授乳室に関して意見があったのかということを教えてください。","respondent":"山下新庁舎整備課長","answer":"今回の設置の場所につきましては、このアクセシビリティの手引き（素案）の中では、具体的な場所は当然これから設計していく中ですので、場所としてはお示ししておりませんけれども、考え方といたしましては。","voiceIndex":49,"id":"exchange-019"},{"speaker":"せお副委員長","kind":"質問・要望","question":"場所となると、また少し違ったところになるのかもしれませんね。すみません。民間はしようがないですけれども、できれば、そこは分けていただきたいという。場所をとるので、なかなか難しいとは思うのですけれども、そういった配慮もしていただければなということを要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-020"},{"speaker":"山本委員","kind":"質問・要望","question":"この第２回の委員会の中でもワークショップを取り組まれたということで、このワークショップの中身、ワークショップ中は、各委員から活発な意見交換とかがあったのでしょうかというところ、それから、今回、ワークショップをやってみて、今までの委員会ではワークショップ等はなかったのかなというところで、通常の委員会と比べて、各委員の方の意見がより出てきていたのかどうか。","respondent":"泉広町事業調整担当課長","answer":"委員の方とも顔見知りになったといいますか、お顔を合わせながらお話合いができたということで、今後の議論も活発に進むのではないかといったところの効果も生まれたのではないかというようなご意見もいただきまして、通常、確かにおっしゃるとおり。","voiceIndex":58,"id":"exchange-021"},{"speaker":"山本委員","kind":"質問・要望","question":"ご回答ありがとうあります。もう１点、全体のスケジュールのところで、現在、対話型市場調査が進んでいるですが、今、進めている途中というところで、ご発言も限られるところもあるかと思いますが、コメントをいただけるところがあれば、お聞きできればと思います。","respondent":"泉広町事業調整担当課長","answer":"情報を出すに当たりましては、各事業者の方に事前に確認をとりながらというところを前提に、対話型市場調査と呼んでいるところがありますので、そういったところの内容を踏まえながら出していきたいというふうに考えておるところです。","voiceIndex":60,"id":"exchange-022"},{"speaker":"山本委員","kind":"確認","question":"今、進捗中ということで、なかなか中身のところは、きついのかなと思っているのですが、それなりの社数の応募があって、今、無事に進んでいるということだと思うのですけれども、確認をします。社数とか、何か中身以外のところで、ご説明いただけることがあれば、お願いしたいと思います。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査に関しましては、ご質問の中身では、跡地でどういった活用をしていくのか、活用の用途でございましたり、また、その活用の範囲であったり、あとは、土地建物の権利の形態をどういった形が考え得るのかといったところを広くご意見をいただいたというところで。","voiceIndex":62,"id":"exchange-023"},{"speaker":"山本委員","kind":"質問","question":"ご回答ありがとうあります。度々質問して失礼いたしました。ぜひ、まとめていただいた資料を待ちたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問","question":"私もこれはごもっともだなというふうにやはり思っていて、それが１つと、それについての対応方針が、これ、右側のところがどこがどう対応しているのかが少し分からないのですけれども、その次のページのところにある第５回の検討結果の取りまとめというところに具体的に反映されるのかなというところで、どの程度の検討委員会としての答申というか、その内容となっていくのかなというところで。","respondent":"泉広町事業調整担当課長","answer":"委員の意見がアウトプットにどのような形で活用されていくのかというご質問ですけれども、そちらにつきましては、４ページに記載しています、例えば、令和６年６月頃を予定していると書いています第５回検討委員会の取りまとめの上に、活用の基本的な考え方というところで。","voiceIndex":66,"id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう１つ、これ、ページ数でいうと、２１ページの第１回ワークショップの実施結果というところで、ワークショップの中でいろいろなご意見が出た中で、庁舎跡地周辺のところに、少し小さい字ですが、「防災に強い」というような、３０年、４０年後に求めていくイメージとしてあるのですけれども、２２ページの公有地活用の事例のところを見ると。","respondent":"泉広町事業調整担当課長","answer":"最後の淀橋第二小学校跡地のところにつきましては、こちらは、例えば、にぎわいを創出したですとか、福祉施設が入ったですとか、そういった機能が区民のニーズをかなえるために入っていった事例といったところではなく、あくまで財政支出の抑制というところが。","voiceIndex":68,"id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"分かりました。どういう捉え方もできると思うので、第１回ワークショップの実施結果を踏まえてから抽出したような、そういうイメージだったのですが、そういうふうな書きぶりなのですけれども、というよりは、代表的なところを引っ張ってこられた、代表的というか、引っ張ってこられたのかなという印象だったので、あえて質問させていただきました。","respondent":"泉広町事業調整担当課長","answer":"面積の関係で類似の事例がどちらかといったところですけれども、まず、現庁舎の跡地という視点に立ちますと、第１回検討委員会のときに申しました現庁舎、第二庁舎なども含め、おおむね１万４,０００m2ほどあります。","voiceIndex":70,"id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"分かりました。定住の意味が、今おっしゃっていただいたように、子育てとか、高齢者福祉とかというふうにくくっていただいていたほうが、多分読むほうも、というか、参考にするほうも分かりやすかったと思うので、その辺り、実質私も議論に参加しているわけではないので、皆さんがご理解していればいいのですけれども、その辺りも少し丁寧に説明したほうがいいのかと思って質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-028"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、このワークショップに集まった全体のバランス、要は、年齢の幅というか、今、実施検討のグループ討議の成果を見ていると、例えば、スケボーの施設をつくってほしいという方もいたり、高齢者施設をつくってほしいという方もいたり、ドッグランをつくってほしいという方もいたり、集まってきてくれた年齢の幅というか、バランスはどうだったのかなということが聞きたいのと、あと、ごめんなさい。","respondent":"泉広町事業調整担当課長","answer":"検討委員会の中で行ったグループ討議におけるファシリテーターにつきましては、今回、学識経験者ということで３名ご参加いただいてございまして、その学識経験者、大学の先生の方々にファシリテーター役を担っていただきまして。","voiceIndex":74,"id":"exchange-029"},{"speaker":"まつざわ委員","kind":"質問","question":"分かりました。学識経験者ですね、そうでした。例えば、権現地域の方であるとか、二葉の方である、大井の方であるという、このワークショップも全体を集めることは大事なのですけれども、例えば、いろいろ騒音でも何でもそうなのですけれども、一番そこら辺の方のお声をやはり聞いてあげるべきというか、聞いていかなければいけないのかなという感覚が私はあるのですけれども、そこら辺を教えてください。","respondent":"泉広町事業調整担当課長","answer":"どういった形になるかといったところはありますけれども、こういった形で区民の意見をお聞きする場面がありますので、様々な場面で、こういうところには広く周知をするとともに、その中でもご意見をいただいてまいりたいと思ってあります。","voiceIndex":76,"id":"exchange-030"},{"speaker":"松本委員","kind":"確認","question":"この事業手法というのは、活用の内容とはまた異なるというか、どういうふうに活用していくのかというところと異なって、恐らく従来方式なのか、ＤＢなのか、またＰＦＩなのかというところをお示しいただくのかなというところなのですけれども、それでいいのかという確認と、新庁舎のほうの基本計画の策定のときには、各方式のメリット・デメリットのようなものも示されていたかと思うのですけれども。","respondent":"泉広町事業調整担当課長","answer":"ただ、これは跡地活用の検討委員会の中では、先ほど申し上げたとおり、事業手法を何かメリット・デメリットをつくって選定していくというようなところは考えてございませんで、この庁舎跡地活用検討委員会が終わって、この検討委員会の中でしっかり区民ニーズを捉えた上で。","voiceIndex":80,"id":"exchange-031"},{"speaker":"松本委員","kind":"質問・要望","question":"今回は、そういうところまではやらないということなのですけれども、今後というところで、私などは、今回は今のお話だと信託とかというところで、単純な従来方式とかＰＦＩとかというところではない別の手法、定期借款なのかどうなのか、信託なのか、いろいろな、またもっと違う形まで想定されているかと思うのですけれども、基本計画のときに、かなり問題だなというふうに思ったのが、当区は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"なので、実施結果のところで、「緑豊か」というキーワードが、２０ページ、２１ページの総括のところに出てきてしまうのですけれども、これ、なぜ「庁舎跡地周辺」というふうに質問をしたのか、どういう効果を狙ってこういう質問をされたのか伺います。","respondent":"泉広町事業調整担当課長","answer":"ワークショップの質問の仕方、地区全体と跡地周辺に分けたところですけれども、まずは庁舎跡地周辺、今回の活用検討の範囲ということでお示しさせていただいた現庁舎跡地と、しながわ中央公園一帯というところで、まずは、そういったところをお示ししながらも、地区全体。","voiceIndex":84,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"一体的なまちづくりということで、その周辺ということを聞くということは必要かと思うのですけれども、ということは、庁舎跡地そのものについては、今後、聞いていく予定はあるのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"庁舎跡地周辺、また今後、第２回のワークショップを控えているわけですけれども、そちらの場面でも、庁舎跡地周辺で、例えば、どういう過ごし方を期待するのかですとか。","voiceIndex":86,"id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"庁舎跡地周辺のイメージというか、委員の人に庁舎跡地周辺のイメージを聞いたり、ご要望を聞いて、逆算して、庁舎跡地そのものをどうしていくのかというふうに決めていくという、そういう流れの認識でよろしいでしょうか。","respondent":"泉広町事業調整担当課長","answer":"今回行ってありますワークショップにつきましては、区民ニーズを、どういった形の区民ニーズがあるのかということを広く捉えていくという趣旨でやっているものでございまして、例えば、活用の範囲をどの範囲でやっていくのかというのは、先ほど申し上げた。","voiceIndex":88,"id":"exchange-035"},{"speaker":"えのした委員","kind":"確認","question":"先ほど、まつざわ委員からもご質問がありましたけれども、年齢層の幅は分かったのですけれども、区内のどの辺にお住まいだったりとかという、この近隣地域の方というご意見もありますでしょうし、私も住んでいる地域、その辺はうまくバランスがとれているのかどうか、それだけ確認をお願いします。","respondent":"泉広町事業調整担当課長","answer":"区民ワークショップに参加された方のお住まいの地区ですけれども、こちらは本当に幅広く来ていただきまして、当然、近隣の方からも来ていただいていますし、荏原ですとか、品川のほうの地区ですとか、本当に様々なところから集まっていただきまして。","voiceIndex":91,"id":"exchange-036"}]},{"id":"topic-02","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"それと、先ほど、１１月１５日までに文言ということでしたけれども、少し考え方を当委員会でも整理をしたいのですが、例えば、裏面の環境性能についてというところで、「ＺＥＢ、ＣＡＳＢＥＥの目標水準について、適時適切なタイミングで公表すること」と(2)であるのですけれども、これ、前回の委員会で、一応この意味で公表はされたと思うのですが、そういう意味なのか、それと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"私からお聞きしましたけれども、あってもいいのかなと。今回でまだこのアクセシビリティも素案というところですし、環境性能についても、Ｎｅａｒｌｙ ＺＥＢからＺＥＢ Ｒｅａｄｙに変わったみたいなことも前回報告もあったのですが、これから基本設計を進めていく中で、どういう変更がまたあるかも分からないので、残しておいてもいいのかなというところで。ほかにご意見があればというところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"この基本計画についてはです。だから、それについて、基本設計においては、品川区新庁舎整備基本計画を忠実に遵守すること、これは私、前にも発言しているのですけれども、これは部長にも、課長にも確認しました。その点については、また文書は一文入れますけれども、今日は議論をしないのであれば、次回また皆さんのご意見も伺いたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-039"},{"speaker":"筒井委員","kind":"確認","question":"本当に基本的な確認なのですけれども、この取りまとめ、今までこの委員会で出た、それぞれ各委員からのご発言を議事録とかで確認して抽出されたと、それは正副のご判断で文章化してこのように記載したという理解でよろしいでしょうか。","respondent":"こんの委員長","answer":"はい、そのとおりです。","voiceIndex":109,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6158#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":35581,"voices":113}},{"id":"r05-20231109-19","meetingId":"r05-cm11","date":"2023年11月9日","dateIso":"2023-11-09","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ４時０２分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区地域防災計画の素案","agenda":"品川区地域防災計画の素案","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、今回示された被害想定では、下水道は被害が６％に減ったということで、ほとんどのところが被害がなく、そのまま使えるということになるのかと思うのですけれども、そうすると、さらにそれを１００％にしていくという計画があるのかどうかというところも伺いたいと思います。避難所のトイレの耐震化ということですが、伺いたいと思います。","respondent":"平原防災課長","answer":"下水道の被害ですけれども、こちらは被害想定上、かなり減少したということで、東京都下水道局による下水道整備が進展しているものと認識しております。","voiceIndex":6,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"学校トイレは、各避難所で１か所はできているということですので。それで、今後さらにそれを広げて、複数の、最終的には全部のということになるかもしれませんが、避難所のトイレを使えるようにしていくお考えなのかどうかというところ、増やしていただきたいとは思うのですけれども、伺いたいと思います。では、続けて伺います。","respondent":"平原防災課長","answer":"実は区のオペレーションも、災害対応は災害対策本部なのですが、復興は復興本部というものがまた別に立って、息の長いものを行っていく形になりますので、そういったことは別で定まっていくのですが、今お話のございましたように。","voiceIndex":8,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"マンホールトイレは、今、そうすると公園と避難所を合わせて４００か所ぐらいあるということですか。それで実際足りているのかということだと思うのですけれども、必要数がもし出ているのであれば伺いたいのと、やはり、それをしっかり国でも基本方針に反映させていくということが言われておりますが、品川区としてはマンホールトイレの基本方針というのはあるのかどうかも含めて伺いたいと思います。","respondent":"平原防災課長","answer":"続きまして、マンホールトイレの４００基で足りるのかといったところですが、先ほども答弁させていただきましたが、マンホールトイレだけで何か全てをという形ではなくて、まず先ほど言いました耐震化されたトイレ、あるいは携帯トイレ、簡易トイレ、それから。","voiceIndex":10,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、しっかりと、トイレに困るようなことがないようにしていただきたいのと、あと構造上、学校の上層階でできるかどうかという話がありましたけれども、上層階がどこまでか分からないですが、小学校で３階ぐらいまではやっているというところもあるみたいなので、ぜひそういった形で進めて、さらに増やしていっていただきたいと思いますし、まちづくりのほうは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問","question":"東京都の中でも幾つか、モデル事業地区の地区防災計画が公開されていますが、品川区では地区防災計画の定められたところがないので、新しい取組だと思われています。今後の検討ではあると思われますが、今後の動きで具体的なところが決められているものがあれば、お聞きできればと思います。","respondent":"平原防災課長","answer":"実際には、どういう地区から進めるのかとか、そういう順序といいましょうか、どのぐらいのスパンでといいましょうか、そういったところについては、まだ決まっていないところですが、今後そういったところが計画上位置づけられましたら。","voiceIndex":14,"id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"地区防災計画の作成後、自治体から防災倉庫や資機材を助成・貸与もされているとのことでしたが、まず品川区の中で、１３地域に限らず、モデルとなる地区防災計画を作成する地域を抽出していただき、さらにモデル地域をホームページ等でどんどん公開するような流れをつくっていただきたいと思いますが、この辺についてさらにお考えを改めてお聞きできればと思います。","respondent":"平原防災課長","answer":"それが１３地区の単位なのか、さらにそれとはまた別の単位なのかといったところにつきましては、まだそこまで検討には至っていないのですけれども、ただ、やはり品川区の場合、防災協議会という単位で１３地区が対応しておりまして。","voiceIndex":16,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"それで、防災区民組織への意見照会では１００団体からお答えが来て、高齢者障害者団体については２３団体からということなのですが、例えばどのようなご意見があって、それが、防災計画の中で修正されたところがあるのかといったことについても伺いたいと思いますが、いかがでしょうか。","respondent":"平原防災課長","answer":"もう一つは、先日も委員会でご説明させていただきましたが、避難行動要支援者の個別避難支援計画を今作成しておりますけれども、計画作成は進んできているのですが。","voiceIndex":19,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのご意見については、この修正の中で、先ほど１つは挙げられておりましたけれども、そういうふうに反映されていくということで、ぜひ反映していただきたいということなのですけれども、その確認でよろしいでしょうかということが１つ。一方で、持って帰るのも結構大変だったとは思うのですけれども、その辺についての配慮はどうなのでしょうか。","respondent":"平原防災課長","answer":"ですので、必ずしも電子上ではなく、実際に紙でと思っているのですが、何分、全部で１,１００ページぐらいに及ぶ計画ですので、貸出しといいましょうか、そこについては、今、私はこの場で把握していないのですけれども、持って帰るにしても重たいですし。","voiceIndex":21,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"何日間か、短い時間だったのですけれども。持ち帰れない方については、今までのいろいろな計画だと、もうその場で立って資料を読むしかないのかという感じだったのですけれども、持ち帰るのは大変という方については、どこかスペースを提供していただいて、じっくり見ていただくとか、そういう配慮もしていただきたいと思いますので、その点についていかがでしょうか。","respondent":"平原防災課長","answer":"頂きました意見につきましては、全てお答えを返させていただいて、反映した、あるいはもし仮に反映できないとすると、防災課としての、区としての考え方、さらには地域防災計画ではないところで見直すべきものがあれば、どういう方針で進めるのかといったところを。","voiceIndex":23,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、多くの方たちが意見を出しやすいような仕組みを考えていただきたいと思います。これは要望にとどめます。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に、何度も申し上げますけれども、防災計画をまとめるのは大変だと思いますが、できる限り自助・共助ができるような仕組みづくりをやってほしいし、最後は公助によって住民をやはりバックアップしていただけるようにやっていただきたいと思います。そして、その地域の人が、その地域の住民をよく知っているわけですから、その地域の人と併せて、やはり自助・共助でその地域を守る。意見だけで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。今回のこの素案を出される中で、まずちょっと確認させていただきたいのが、今後の会議の予定が、来年の２月、防災会議、計画案の審議となっておりますが、これが、決定して区民に周知されるのがいつになるのかということ。","respondent":"平原防災課長","answer":"２月の防災会議でご決定いただけましたら、こちらについては直ちに公表という形で、物理的な準備もありますので、即日というのはなかなか難しいかもしれませんけれども、速やかに公表してまいりたいと考えています。","voiceIndex":28,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"それが１点です。もう一点は、特に在宅避難の高層マンション、マンション、集合住宅に住んでいる方。トイレを使いたくなってしまうのですけれども、自分のところは漏れていないけれども、上下が漏れているという場合の、そこのチェック機能を今後どうしていくのかというところを、お考えが、検討されていることがあれば教えていただきたいと思います。","respondent":"平原防災課長","answer":"家庭内備蓄におけるトイレの重要性ですが、委員ご指摘のとおり、非常に重要なものと考えてございまして、先ほど、のだて委員からも、ご質問の中でトイレの量的な確保ということもございましたけれども、大多数の方が在宅避難になることを考えますと。","voiceIndex":30,"id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"例えば八潮団地などは、団地、号棟が自治会になっているということもあって、比較的そういうことが分かりやすい仕組みづくりがされていると思いますが、多くの民間の管理組合というところが、なかなか品川区との連携も取れているようで取れていない側面もあるかと思いますので、今後、大きなマンション、集合住宅に関して、管理組合のあるところはしっかり区と連携が取れる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"},{"speaker":"澤田委員","kind":"質問・要望","question":"開設するのでどうぞ」というのをお知らせするのかというのを教えていただきたいと思いまして、お願いいたします。","respondent":"平原防災課長","answer":"例えば震度６弱以上という形になりましたら、見渡すところでは建物の倒壊がないかもしれないですけれども、広く町会の範囲内でやはり倒壊家屋が出ているという可能性もありますので、そういったところを、全員の把握ができるまで避難所を開設しないなどという形になりましたら。","voiceIndex":34,"id":"exchange-015"},{"speaker":"澤田委員","kind":"確認","question":"例えばニュースやラジオ、携帯などで確認して、それぞれ区民の方が、震度６弱以上であれば、もう即、向かうという形で考えていらっしゃるということでいいのでしょうか。","respondent":"平原防災課長","answer":"もちろん、ラジオやテレビ、最近でいきますとスマートフォンもありますし、震度６弱といいましょうか、震度５弱以上になりましたら、防災行政無線でも、ただいまの地震の震度はというような形で放送が入りますので、様々なもので情報を取っていただいて、「震度６弱以上だった。","voiceIndex":36,"id":"exchange-016"},{"speaker":"こしば委員","kind":"質問","question":"私から、主な修正点の中の共助の在り方についてお聞きしたいと思うのですけれども、１つ目の、幅広い世代が参加する訓練の実施ということで、この幅広い世代、親子、また高齢者・障害者の方が訓練に参加するというのは、もちろん大切なことだとは思うのですが、これはまずもって品川区が主催する訓練を指すものなのか。","respondent":"平原防災課長","answer":"現在行っております防災区民組織による訓練、あるいは防災協議会による訓練、あるいは、区が実施する訓練というと、どちらかというと職員訓練になるので、あまりそぐわないかもしれませんけれども、様々な訓練で何かご支援することがあるかどうかと考えています。","voiceIndex":40,"id":"exchange-017"},{"speaker":"こしば委員","kind":"質問","question":"そういったところの地域の訓練を底上げしていくことが多分、課題になっていくと思いますし、それを既にもう実践されている町会・自治会もあると思うのですけれども、その辺の底上げに向けた訓練を促すことについてのお考えなどを教えていただければと思います。","respondent":"伊藤災害対策担当課長","answer":"来年度以降はまだ検討段階でありますけれども、例えば親子世代をターゲットにしたイベント性を入れたものや、なるべく高齢者や障害者も参加しやすいような訓練体系を取りまして、いろいろな方が参加して。","voiceIndex":42,"id":"exchange-018"},{"speaker":"こしば委員","kind":"意見","question":"ぜひ、そういった親子の顔の見えるような訓練、全体の訓練もそうですし、また地域・町会の訓練のほうも、ぜひお示ししていただきたく。一部の役員が集まっているだけだと、その発想がなかなか生まれてこないというのが実情でもありますので、その辺りを柔軟にまたお示しいただければと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-019"},{"speaker":"西村委員","kind":"質問・要望","question":"特に木密地域ですから、そういったことの防災訓練にも特化しておりましたし、また、今のご説明を伺って、地区防災というのはまさにこういうことなのかというのを体感しての今日のお話でしたので、改めまして、実際にお越しいただいておりますので、所感も含めて伺いたいのと、実際、今回の二葉三丁目の防災訓練をご覧いただいて。","respondent":"平原防災課長","answer":"感想といいましょうか、感じたところとしましては、やはり非常によくできた訓練ですが、一方で、二葉三丁目の課題ではないのですけれども、全区的に広げていくには、やはり相当、高度なものが必要なので、一朝一夕にはなかなか。","voiceIndex":46,"id":"exchange-020"},{"speaker":"西村委員","kind":"確認","question":"安否確認不明者保護の訓練をしたときに、シャッターの下りた花屋の中に救助が必要な方がいて、警察に通報を区民の方がするところからの訓練なのですけれども、近所の方々が、パトカーも来ますし、何があったのかとベランダからどんどん出てこられるというほど実践的だったというのは私自身も思っておりますので、こういったふうに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-021"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"避難所のトイレのことが先ほどから出ていますけれども、本当に、水や食糧の備蓄と同時にトイレの問題というのは本当に重要な問題だと思うのですが、避難所のトイレは、簡易トイレや仮設トイレ、そしてマンホールトイレということで、もう既に足りているということだったのですけれども、それは、何というのですか、これがこういうくらいでというところで。","respondent":"平原防災課長","answer":"マンホールトイレのガイドラインですけれども、国土交通省が下水道の直結方式のものを推奨しているということは私どもも承知しておりますが、ただ、これは一部、やはり都市部で特に課題となっているのですけれども、大規模な工事がなかなか難しいということもあって。","voiceIndex":50,"id":"exchange-022"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"だけど、ハード面でやはり公園のない町会というところは、そういうところがないと、より困難になってくるということであると思いますので、そこのハード面のところでの防災公園を全ての町会に造るというのも、区としても方針としてしっかりと持って、何というのですか、この防災計画の中でも位置づけてやることが必要ではないかと思うのですけれども、その点も伺いたいと思います。","respondent":"平原防災課長","answer":"続きまして町会組織ですけれども、コロナ禍で訓練が止まってというようなところで、改めてもう一度やり直しになっているようなところもありますが、そういったところ、ソフト面というお話がございましたけれども、しっかりとまた支援していますが。","voiceIndex":52,"id":"exchange-023"},{"speaker":"鈴木副委員長","kind":"質問","question":"もう一つ、やはり災害のところで本当に最も大事になるのが、下水道と上水道の耐震化というところではないかと思うのですけれども、これもかなり東京都も頑張ってくれているのだと思ったのですけれども、下水道では被害率が前回２８.７％だったのが６.４％になりましたし、上水道も断水率が４６.２％だったのが３０.２％ということで、かなり下がってきているというところなのですけれども。","respondent":"平原防災課長","answer":"東京都は、２０３０年までを目途といたしました強靱化の計画を立てておりまして、その中で様々なものが定められております。そういった中で、今ありましたような耐震化といったところも進めているところなのですけれども、０％という数字ではなかったかと思ってあります。","voiceIndex":54,"id":"exchange-024"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"以前、水道局に伺ったときに、かなりの巨大地震にも耐えられる、技術的にはできているのだということも伺いましたので、そういうところで、ぜひ進めて、水道が止まらないということになったら本当に、かなり災害のところではよくなるのではないかと思いますので、ぜひ進めていただきたいと思います。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-025"}]},{"id":"topic-02","title":"令和５年度区内一斉防災訓練の実施","agenda":"令和５年度区内一斉防災訓練の実施","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"１点だけなのですけど、これから品川区内で一斉防災訓練をやりますということで、防災行政無線で流しますけれども、やはり、もう少しボリュームを落としてもいいのですけど、ウーとか、ああいうので、皆さんが、あれは何なのだろうというふうな、私はそういう対応を聞くとか、これはいつもこんなに音が出ないよねとか、そういうことも流したほうがいいように思うのですが、やはりいろいろな。","respondent":"伊藤災害対策担当課長","answer":"今回の地域の総合防災訓練でも、訓練を実施する際に総合防災無線等を流して、地域の方々に訓練の実施、また中止などを呼びかけさせていただきました。防災行政無線本来の目的であるＪ－ＡＬＥＲＴや、他の緊急地震速報等も流しています。","voiceIndex":61,"id":"exchange-026"},{"speaker":"せりざわ委員","kind":"質問","question":"聞き逃したのかもしれないのですが、４６か所でやるということで、５２か所、もともと避難所というのが一覧であると思うのですけれども、やらないところの理由というのはどうなのでしょうか。","respondent":"伊藤災害対策担当課長","answer":"ただ、やはり区内一斉防災訓練ということで、同じ時間、同じ時期に訓練を実施するということが非常に重要だと考えていますので、できる限り同じ時期に開催していただけるように、今後も働きかけてまいりたいと考えています。","voiceIndex":64,"id":"exchange-027"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"ご答弁のとおりで、やはり一斉防災訓練なので、基本的にはやはり、どんな理由があっても一斉にやっていただくというのをベースにしたほうがいいのだと思います。以上、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6644#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":26926,"voices":70}},{"id":"r05-20231110-10","meetingId":"r05-cm11","date":"2023年11月10日","dateIso":"2023-11-10","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"定められた傍聴ルールに従うというのは当然だと思うのですけれども、現在のルールですと、第１０条、「規則に違反するときは、議長はこれを制し、その命令に従わないときは、これを退場させることができる」とあったと思うのですけれども、今のご説明ですと、具体的にはどういうことでしょうか。それはもう少しお伺いしたいです。","respondent":"渡辺議長","answer":"今、私が考えているのは、せんだってのことは、今までではなかなか想定外の行動だったので、対応し切れなかったと。次回、本会議開催の冒頭に、傍聴規則の案内を、私の口頭で行おうと考えています。","voiceIndex":15,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"個人に対する中傷や暴言というのは本当にあってはならないことだと、私もそのとおりだと思っています。うまく言えないのですけれども、傍聴規則を読み上げるだけでは、今のような行動を自粛しようというふうになるのかなというのは、私は疑問に思ったのです。そんな感じなのですけれども、どうでしょうか。","respondent":"渡辺議長","answer":"その際は、退席を含めた対応をしますという断りを、直近であったものでという断りで、様子を見る形で、次回は入れようと思います。そうすることで、会場にいる方の理解と、各議員の理解を得られるかなという考えです。説明を冒頭に持ってくるという考え方は以上です。","voiceIndex":17,"id":"exchange-002"},{"speaker":"安藤委員","kind":"提案","question":"議長が議場の秩序を維持していくという大事な役割なので、今ある規則をどういうふうに具体的には当てはめていくかというのは、ある程度、議長の裁量になると思っているのですが、今こういった表明があって、実際にこれから運用になっていくと思うのです。その上で、何か提案が出てくるようでしたら、改めて提案させていただきたいと思います。","respondent":"渡辺議長","answer":"特にこの間の振り返りの中では、やはり人格否定や、特定の個人を恫喝するようなことに値するときが退席というのを、私の中ではイメージしております。これはもう誰もが、万人が許されないこととして思われる範疇だと思いますので、そういった考えです。","voiceIndex":19,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"議長がせっかく注意したのに聞いていなくて、そのまま入ってくるという方もいらっしゃると思うので、それがいいかどうかは分からないのですが、傍聴者には様々な方が見えるので、良識のある人を守る意味でも、事務局にはお手数ですけれども、何か紙ベースで、来られた方にこれは守ってくださいというものを手渡ししたらどうでしょうか。それは判断ですけれども。","respondent":"渡辺議長","answer":"それで、あるたびに発言も私もないと思いますので、それを聞いていようが聞いていまいが、特に一線を越えるようなことは、説明があろうがなかろうが許されてはいけないということで進めたいと考えていますので、ぜひともまた、お気づきの点を含めて、ご協力をお願いします。","voiceIndex":22,"id":"exchange-004"},{"speaker":"西村委員","kind":"意見","question":"それは区民の皆様に理解していただく、紙の配布なのか、何か方法というのは新たに必要かと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-005"},{"speaker":"塚本委員","kind":"意見","question":"やはり、たくさんいる中での全員に対する呼びかけということは、その人本人に、なかなか個人に自分のことだと伝わらないようなことというのもあるのかとも思いますし、集団心理で、全体が騒乱してくると、なかなか抑えも利かなくなってくるというところもあるので、そういった事態にならないようにということでの一巡の考え方などというのは、今後も様子を見ながら、常に考えていきたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"先日、各常任委員会で行政視察を行ったのですが、私は文教委員ですけれども、非常に充実した視察だったのです。委員会資料や議事録同様、区議会のホームページに上げていく必要があるのではないかと思うのですけれども、そういった検討をこの場でできるのだったら、ぜひしていただきたいですし、必要なところで審議するというのであれば、ぜひ検討をお願いしたいと思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。どこの会議体でこれが検討材料になるのかということだけ確認させていただきたいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-008"},{"speaker":"せりざわ委員","kind":"意見","question":"さっきのところで私も発言すればよかったのですが、議会の傍聴について、反対も何もないのですが、傍聴ルールのところで、先ほど、多分本会議をベースにお話しいただいていたと思うのですけれども、やはり委員会も結構乱れているところがあって、本会議は議長裁量でというところで、第４回定例会にはルール改正は多分間に合わないだろうからというお話も頂いていたと思うのですが、これは常任委員長。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5520#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":9987,"voices":40}},{"id":"r05-20231121-10","meetingId":"r05-cm11","date":"2023年11月21日","dateIso":"2023-11-21","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の議事日程(1)(2)および追加議事日程","agenda":"の議事日程(1)(2)および追加議事日程","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"局長からもご発言がありましたが、一般質問２日目の２人目、当会派の木村議員なのですが、ご本人からの要望で、２０分間立ったままでの発言が難しいということでございまして、着座でお願いできないでしょうかです。演壇までは自力で歩いていけるです。どうぞご了承願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"死者の４割が子どもという深刻な状況に誰もが心を痛めているのではないかなと思うのですけども、品川区議会として、昨年の３月にはロシアのウクライナ侵略に対しても抗議をして、撤退を求める決議をしました。皆さんいかがでしょうかです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-002"},{"speaker":"せりざわ委員","kind":"意見","question":"我々も同じような方向性でいろいろ考えていまして、共産党にお声がけできていないのが恐縮なのですが、しっかりまとめて、議会全体で同じような方向性で結論を出したいと思います。そのように進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5522#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":5960,"voices":34}},{"id":"r05-20231127-6","meetingId":"r05-cm11","date":"2023年11月27日","dateIso":"2023-11-27","committee":"区民委員会","time":"午前１０時００分～午後 ０時０４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山本委員","kind":"質問","question":"順調に進んでいるという理解ですので、進めていただいてありがとうあります。現状、進んでいる中で、実際の集会所の移転に向けて、何か問題等がないかというところをお聞きしたいというのが一つ。具体的には、その建て替えまでの一定期間を暫定的にマイスクールとして活用されるということかなと推測しているのですけれども、そういった見通しについても、現状、分かるところでお教えいただければと思います。","respondent":"西村委員長、宮澤地域活動課長","answer":"跡地活用が企画部の所管になりますので、お答えいただける範囲でお願いできればと思います。修繕等をしてやっていけばですが、跡地活用に関しましては、企画部のほうで検討して、マイスクールというところで、本日補正予算の審議を含めて、文教委員会のほうで説明されているというふうに伺っております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"山本委員","kind":"質問・要望","question":"状況として問題なく進んでいるということで、確認できましてよかったと思います。跡地活用については、そういった条件があることを理解しましたので、文教委員会等、ほかの機会を通じて、会派としても確認させていただきたいと思ってあります。","respondent":"宮澤地域活動課長","answer":"契約の部分です。３０年の契約でございまして、駐車場や駐輪場を含めた月額の賃料につきましては、３３９万８,３４０円という形になってあります。","voiceIndex":8,"id":"exchange-002"},{"speaker":"山本委員","kind":"質問","question":"その金額が、区として妥当だというふうに判断されたその根拠とか理由を、簡単でも結構ですのでご説明いただけませんでしょうか。","respondent":"宮澤地域活動課長","answer":"金額につきましては、区の中で締結している、賃貸借契約をしている物件等と、ただ大きさや位置というのが同じようなものではございませんが、そういったところと比較して、また近隣にもやはり同じような大きさの貸物件というのはなかなか見当たらないところではありますが。","voiceIndex":10,"id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"今回初めて、そういう施設を民間企業から借りるということでございまして、それが無駄なく、割高ではなく使われているかというところは、一つ考えるべきところでもあると思いますので、その点については、私もまた今後ともその勉強をしていきたいと思いますし、無駄のない賃料の契約締結等、今後あるときには心がけていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ＪＲ西日本のいわゆる住宅部門の、ある一定のやはり富裕層と言っていいのか、ある程度のそういう物件であるということは確認できたのですが、そういう点において、そういった認識でいいのかどうかというところと、これもたしかその当時、課長にも確認したのですが、この持ち主というかオーナーは、ＪＲ西日本という私が調べたものと、地元の方たちが言っている企業とは違う企業だったのですけれども。","respondent":"宮澤地域活動課長","answer":"ＪＲ西日本の担当者とお会いしたところでのお話というところになって、ＪＲ西日本になるのですけれども、東京のほうであのような物件を構えて、末永く賃貸借の収益を上げていくというふうに伺っている中で。","voiceIndex":14,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"要するに安定性という点も含めて、区のものが入っているわけですから、あまりそういうのは好ましくないというところで、先ほどもありましたが、決して安くはない家賃を払っているわけで、そこについての安定性については、区はしっかり大丈夫だという認識があるのかということと、これも前回聞いたかな、町会への協力については、当然地域センターが入るわけですから、そこについては働きかけ。","respondent":"宮澤地域活動課長","answer":"地域センターの町会への支援というのはいろいろ行っておりますけれども、様々な事業が頻繁にありまして、ウェルカムセンター原にて地域のイベントというのも行われていきますので、そういった中を含めて、居住されている方の町会等への加入も含めて支援できたらと考えています。","voiceIndex":16,"id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"移転後の跡地の活用が決まったということで報告はされていて、これは企画部だというのでそこは伺わないですけれど、前回８月の委員会のときに、私の印象に残っているのは、もう４３年経っているのだと。だから私がそのとき質問したのは、大体この４０年ぐらいで老朽化というのであるならば、ほかの地域センターではどこがあるのですかという質問をたしかしましたよね。何かよく分からないのです。","respondent":"宮澤地域活動課長","answer":"地域センター自体につきましては、これから先も地域の人たちの町会・自治会の支援も含めてですが、まず、地域に最も身近な区役所としてこの先もサービスを提供していくという中で、４３年を迎えて老朽化の兆しも出てきた、老朽化も進んできたというところの中で、今後１０年。","voiceIndex":19,"id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"今の説明だと、何かよく分からないですね。それと今、課長の答弁で、１０年、２０年、３０年後を考えた、というふうにすると。つまり、何が言いたいかというと、途中でいろいろ事情があって、なぜなら民間のマンションなのだから、いろいろ事情があって「すみません、退去してください」とか「契約をこれで終わりたいです」といったら、何のためにこうやったか分からないではないですか。","respondent":"宮澤地域活動課長","answer":"その３０年後につきましては、３０年経ってからというところになりますが、引き続きというところで契約は可能だというところです。それは状況に応じていくというところにはなるかと思いますが、３０年は保障されていくものです。","voiceIndex":21,"id":"exchange-008"},{"speaker":"藤原委員","kind":"確認","question":"は若い議員たちに３０年後どうなったかを見てもらって、きちんと議事録にも残っているので、そういう意味で３０年後がどうなるかという思いがあるのですけれども、ただ、もう１回だけ確認しますが、老朽化もありますが、やはり、防災備蓄倉庫の話も出ましたけれども、その地域のために、大きいところをこれだけ金額をかけて借りても、これは、区民の、特にここを使用する町会の方々。","respondent":"宮澤地域活動課長","answer":"区民集会所が大きくなることや、防災備蓄倉庫ができること、またそれ以外にも、障害者向けの駐車場であったり、授乳室も設けたりとか、様々なサービスの使い勝手がよくなるように、機能を強化しておりますので、それらを含めまして。","voiceIndex":23,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"課長、そういうことをいい意味でどんどん答弁の中へ入れてください。障害者の方の駐車場ができるのですとか、そういう意味においてということを強く、こういう委員会で答弁してくだされば、地域で質問を受けたときに、きちんと「皆さん、こうなるのですよ、こうなるのですよ」と。賛成ですので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-010"},{"speaker":"えのした委員","kind":"質問","question":"例えばこれ、マンションはよく修繕とか大修繕をやると思うのですけれども、そういったところでお金がかかった場合には、賃料には全く影響してこないのかどうなのか。契約内容が分からないのですけれども、そういったところまで、３０年なので、長い期間ですとそういったことも考えられるので、その辺についても区としてはどのようなお考えですか。","respondent":"宮澤地域活動課長","answer":"月額の賃料につきましては、３０年間変わることのない金額で契約をしているというところです。ただし、地価の変動であったり、物価等々で、社会一般的に相応の、何か変動が起きた場合には、相談という形にはなっておりますが、基本的に賃料は変わらずです。","voiceIndex":27,"id":"exchange-011"},{"speaker":"えのした委員","kind":"確認","question":"多分含まれているのだろうなということで、それは確認できたので、やはり契約年数が長いので、その時代に合った、それが例えば地域の近隣のほかの賃貸物件と比較して、やはり下がってくる、上がってくるということがあれば、区としてもやはりそれに応じて、契約内容をＪＲ西日本と協議してやっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、防災備蓄倉庫のことで、防災機能の強化というところに今回力を入れている部分だと思いますので、その確認だけさせていただきたいのですけれども、こちらの建物自体は地上５階建てということでよろしかったですか。その中の一、二階を、今回地域センターに、という理解だと思うのですけれども、その全体の確認。","respondent":"宮澤地域活動課長","answer":"すみません、今回浸水ハザードマップ等々含めて、浸水被害を想定してというところは確認していないところですが、２階部分にできるということと、道路を挟んで反対側にはグラウンドを含めたウェルカムセンター原があるという所で。","voiceIndex":30,"id":"exchange-013"},{"speaker":"横山委員","kind":"質問・要望","question":"必ずそうなるかどうかは分からないのですけども、過去の実績等を見たところと、あとは今後の雨ですとか集中豪雨ですとか、様々な状況を見ていただきながら、配置等も検討いただきたいと思います。今現在がどうというところではありませんので、状況をよく確認していただきながらというところだと思うのですけれども、一言お願いできればと思います。","respondent":"宮澤地域活動課長","answer":"防災備蓄倉庫につきまして、所管となる防災課とも連携しながら、また、地域センターが入っておりますので、そこでも、日頃からの防災への備えというのも検討しながら、併せて進めていきたいと思います。","voiceIndex":32,"id":"exchange-014"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"どこかを取得するにしてもお金はかかってくるものなので、それはそうなのですけれど、３０年間契約で、やはり地域センターなどは地域に定着して愛着を持たれてというものになるので、それ以降買い取るということに、取得できるということになっていったりしないのか伺いたいです。この区民使用料のところだけ、金額を教えていただきたいのです。","respondent":"宮澤地域活動課長","answer":"３０年間賃貸借をしていくというところでありまして、その先買い取るとかどうこうというところに関しましては、ちょっと今現在では検討はないです。区民集会所の使用料につきましては、会議室タイプの第一・第二集会室につきましては、大きさが今よりも大きくなります。","voiceIndex":35,"id":"exchange-015"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"分かりました。地域にとって大事な施設ですので、私も反対するものではないのですけれども、やはり今後、今、ほかの委員からも出ましたけれど、どうなっていくのかちょっと分からないというところはありますので、ここは注視していかなくてはいけないなというふうに思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-016"},{"speaker":"せらく委員","kind":"質問・要望","question":"それで、先ほど出ました集会所の使用料のところなのですけれども、広さ等でちょっと上がってきているというところで、広さ以外に附属の設備などで、移転後にグレードアップする部分がありましたら教えていただきたいと思います。","respondent":"宮澤地域活動課長","answer":"区民集会所の中身の部分の設備につきましては、今回移転するということで、机と椅子等に関しましては新調する予定です。併せて、プロジェクター等の設備というのは引き続き設けて、音響設備も新たな物を設置する予定です。","voiceIndex":39,"id":"exchange-017"}]},{"id":"topic-02","title":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"これも繰り返しになってしまいますけれど、前回の補正予算は２億３,０００万円余を組んでいて、決算額が５,１００万円余ということで、不用額が１億８,０００万円弱出たということで、執行率が２２％ということで、どうしてなのですかという質問に対して、たしか答弁の中では、運送事業者の数が、国が出しているものをそのまま使って、それが実態と合っていなかったというような。","respondent":"小林商業・ものづくり課長","answer":"そのときは、大体この申請期間１か月で３００件ぐらいだったのですけども、今回この期間も少し多めにというか、できるだけ年度内に執行できるようにということも踏まえてですけれども、１.５か月としておりまして、その申請期間のペースが１.５か月ということで。","voiceIndex":63,"id":"exchange-018"},{"speaker":"あくつ委員","kind":"確認","question":"それと、運送事業者等燃料費高騰対策支援金のほうですけれども、今のお話だと期間が長くなったから申請件数がそれぐらい見込めるのではないかということと、実態も見据えたということですが、これ、業界の聞き取りというのは、今回は、前回もしたのかどうかというのは確認してないのですけれども、業界からどれぐらいの事業者がいるのかという聞き取りなどはしたのですか。","respondent":"小林商業・ものづくり課長","answer":"１,１００件というのが、これは関東運輸局からの聞き取りですけれど、それと合わせまして、昨年も実施するに当たりましては、各団体、トラック、タクシー、そういったところも含めまして、個別の事業者周知といいますか、いろいろご連絡もさせていただいたところです。","voiceIndex":65,"id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"特にトラック協会からも、我々も、随分前ですけれどこういうご要望もいただいていて、金額が１億５,０００万円以上売り上げている団体でも４０万円ということで、どれだけその効果があるか分からないけれども、やはり品川区から、行政がそういうところをサポートしてくれるという気持ちがうれしいということで、実質的には当然ありがたいということもあるのですけれども、ぜひ、漏れのないように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-020"},{"speaker":"横山委員","kind":"質問","question":"省エネルギー対策設備更新助成金と運送事業者等燃料費高騰対策支援金の、両方かぶる部分なのですけれども、こちらの申請につきまして、オンライン申請を原則として書類申請も可能ということなのですが、現在、２２２件の中で割合はどうなっているのかというのを教えていただけたらと思います。","respondent":"小林商業・ものづくり課長","answer":"ですので、我々としましてはやはり、行政手続のＤＸ化という意味ではオンラインをできればやってほしいですけれど、事業者の中にはやはりそこがまだできていないということもありますので、今回もこの両面でということでやってまいりたいと思います。","voiceIndex":69,"id":"exchange-021"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらはぜひお願いしたいなというところと、昨年度と同じスキームということだったのですけれども、関東運輸局からの聞き取りで、昨年１,１００件程度ということだったのですが、そちらの事業者数の変化みたいなところも、特に昨年と変わりはないのか、その辺り、どのような形で確認していただいているのかというところ。","respondent":"小林商業・ものづくり課長","answer":"私、先ほどから、所管業界、所管団体というのは個別にというお話をしておりますけれど、例えばですけれども、個人タクシー協同組合でいきますと、その中で支部単位というのもございまして、例えば品川支部とか城南支部とか、幾つか支部があるようでございまして。","voiceIndex":71,"id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"今の周知がきちんときめ細かくされているのですかというのは、これはするべきだと思うのですけれども、もう一つは、やはり申請の複雑化はないのですよね。すごく簡素ですよね。窓口がきめ細かくきちんと対応してあげる体制は取っているのですかということが質問なのです。今の決まりだと火葬するわけです。どんな方でも火葬するわけですから、火葬場等への助成というのはどうなっているのでしょうか。","respondent":"小林商業・ものづくり課長","answer":"火葬場につきましても、そういう意味では一つの業種、業界ということではありますけれども、全業種ですので、そういう意味では、特定の何か業種を排除してというような意味ではございませんで、そういう中で対応可能かなというふうに考えてあります。","voiceIndex":75,"id":"exchange-023"},{"speaker":"山本委員","kind":"質問・要望","question":"ほかの委員の方からも様々ご質問いただいておりますので、私からはそれ以外のところで１点追加で聞ければと思うのですけれども、こちらは全業種対象ですが、現在、申請されている中で、どのような業種がそれぞれ使われているのかというところの割合、傾向等があれば教えていただきたいというところと、あと、対象者、区内中小企業と、そして個人事業主ですが。","respondent":"小林商業・ものづくり課長","answer":"実際にどういう設備が導入されているか、買換えをしているかということでいきますと、冷凍冷蔵庫など厨房設備、調理機械というものが多くございまして、また、続きまして多いものが製造業ですけれども、サービス提供場所、工場等への業務用の空調設備。","voiceIndex":77,"id":"exchange-024"},{"speaker":"山本委員","kind":"質問・要望","question":"分かりました。そのような傾向があるのですね。ほかの委員からも質問がありましたが、それ以外のところの対象となる事業者の方々もいらっしゃると思いますので、そういった方々にもぜひ使っていただけるように周知をしていただければと思いますし、こういった状況を踏まえて、また、来年度以降も引き続き支援ができることをご検討願いたいです。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-025"},{"speaker":"えのした委員","kind":"質問・要望","question":"この運送事業者等燃料費高騰対策支援金のほうなのですけれど、これも各団体に個別周知しているということで安心したところですが、やはりいつも周知、周知と言っていますが、なかなかその情報というのは自分で取りに行かないと入ってこないのかなというところもありますので、そこをもう少し丁寧に、これ、今年の交付要領の最後のほうに、フォローアップという。","respondent":"小林商業・ものづくり課長","answer":"我々のほうで窓口に来られた方、経営相談にいらっしゃって、実際その場では申請しなくて、ちょっと家に持ち帰ってということもありますけれども、その際にもできるだけ電子申請でよろしくお願いしますということはお願いしておりますので、そういったことを引き続き。","voiceIndex":80,"id":"exchange-026"},{"speaker":"えのした委員","kind":"質問・要望","question":"安心したところですが、やはり一度、事業者の方が役所に出向いてくるという、そこも例えば電話ですとか、オンラインですとか、お互いにその辺ももう少しオンラインで申請が簡単にできるような取組も、要望としてお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-027"},{"speaker":"せらく委員","kind":"質問","question":"先ほど、電子申請と紙での申請の割合をほかの委員がお伺いしたところなのですけれども、やはり、行政ＤＸ化というところでオンライン申請を進めていきたいというご答弁がありましたが、オンライン申請にたどり着くまでの経路といったところはどのように想定されているか、伺えますでしょうか。","respondent":"小林商業・ものづくり課長","answer":"その際に、こういう電子申請の手続きのほうもちょっと、ということでありましたら、手続きをご案内して、分からないということであれば、改めてご説明の機会つくらせていただくか、あるいは、急いでいるのだということであれば。","voiceIndex":84,"id":"exchange-028"},{"speaker":"せらく委員","kind":"質問","question":"そういったところのホームページの改善だとかも進めていただいて、行政のＤＸ化、オンライン申請化、増えるのではないかと思ったのですけれども、ご見解を伺えればと思います。","respondent":"小林商業・ものづくり課長","answer":"ホームページの改善も随時やっていくというのに合わせて、我々の、紙の情報としまして産業ニュースで区内の事業者にお配りしているものがありますけれど、その中にはＱＲコードをご案内しながら、ここをたどっていただけると、というのをご紹介しつつ。","voiceIndex":86,"id":"exchange-029"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"助成金、支援金を出していただけるということで、しかも一般財源ということですので、よかったなと思うのですが、先ほどほかの委員からもありましたけれども、やはり納期が年度内ではないというものにはちょっと柔軟に対応していただきたいなというふうに思うのです。来年度も引き続きというところの意欲というのをお聞かせいただきたいと思います。","respondent":"小林商業・ものづくり課長","answer":"ただし、先ほど申し上げましたように４か月で２００件ペースで来ておりまして、恐らく当初、もともと予定していた１月末ぐらいまでに、恐らくこの１００件もそれぐらい来るペースで申請が上がってくるのではないかなというふうに考えてあります。","voiceIndex":89,"id":"exchange-030"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"業種が絞られているというところでは、先ほどのほかの委員からの質問でも、特に、こうしたガソリン等を使う業種ということだったのですけれど、特にというよりは、そのほかの業種も、エネルギー代から食費から様々、全てが高騰している中ですので、少しずつでもいいですから業種を広げていくという検討をしていくべきではないかなというふうに思うのですけれども、いかがでしょうか。","respondent":"小林商業・ものづくり課長","answer":"引き続き、いろいろ経済の状況あるいはその物価の動向などを見ながら、経済の下支えに何が必要かということを引き続き考えていきたいと考えております。","voiceIndex":91,"id":"exchange-031"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"今回は全て一般財源でやっていただいたということで、やはり健全財政ですし、急がなくていいものを今、一旦止めて、生活や仕事を支えるということが必要だと思いますので、ぜひ引き続き業種を広げて、こうした支援も継続を、状況を見てしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-032"}]},{"id":"topic-03","title":"令和５年陳情第４８号、持続が困難な小規模事業者を支援するための陳情","agenda":"令和５年陳情第４８号、持続が困難な小規模事業者を支援するための陳情","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"陳情の理由の2)「新たなる事業資金の貸付」のところでご説明をいただきまして、これは現状、品川区で様々な支援制度があることを私も理解しておりますが、一般的に事業者が使える小規模事業者向けの融資制度の枠、それから足元の物価高騰等の緊急融資制度の枠に対して、現状使っている方々がどれぐらいの金額で使っているか、要は、さらに追加的に利用できる枠がどれぐらいあるのかというところ、一つ。","respondent":"小林商業・ものづくり課長","answer":"２点目、品川区の融資あっせん制度を使ってどれぐらいの融資が通っているのかですけれども、実際に否決しているというもののほかに、金融機関を乗り換えるので自分のほうで一旦取り下げますというものも含めた数字になってしまうのですが。","voiceIndex":108,"id":"exchange-033"},{"speaker":"山本委員","kind":"質問","question":"緊急融資制度のところでも、上限１,０００万円の枠でやっているということなのですけれども、これも、その足元での利用率、大体どれぐらい使っているのかというところも追加でお聞きしてもいいでしょうか。","respondent":"小林商業・ものづくり課長","answer":"通常のいわゆる融資あっせんのメニューに加えて、プラスアルファで今、上乗せしている緊急の部分、１,０００万円の物価高騰等総合支援資金というものがありますけれど、こちらにつきましては、現時点での平均実施としましては８００万円から８５０万円ぐらいの間。","voiceIndex":110,"id":"exchange-034"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"要は、陳情理由の1)のところでは、様々なところから、区の事業も書かれていますけれど、様々なところから借りてきているわけです。先ほども区以外のところでの金融機関とのやり取りなどで借りている部分もあるかと思うので、免除そのものは困難ですというような説明もあったのですけれど、この返済に対しての支援というのは、区としてできることはあるのでしょうか。伺いたいと思います。","respondent":"小林商業・ものづくり課長","answer":"例えばコロナのときに資金を借りて、それから一定期間が経って、実際に元本の支払いや元利の支払いの金額が少し増えてきたというあたりで、その返済計画の見直しが必要な事業者に対しましては、品川区としては借換専用資金という形で一旦お金を借り換えていただく形で。","voiceIndex":114,"id":"exchange-035"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この、国がやっている物価高騰対応重点支援地方創生臨時交付金というのは、もう、この間追加でまた、案が出されたのですけれど、これまで品川区にはどれくらい来ているのか、これからどれくらい来るのかというものがあれば教えていただきたいのです。要は、こういうものも使ってどんどん支援できるのですよねというのをお聞きしたいのですけれど、伺います。","respondent":"小林商業・ものづくり課長","answer":"１点目のご質問に戻りまして、返済の借換専用資金のような、借換えもできないようなケースがあるのかどうかですけれども、先ほど申し上げたような、融資の審査率というところでは９割以上、その中にはほかの金融機関から借りますというような件数も含めてそれぐらいですけれども。","voiceIndex":116,"id":"exchange-036"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ぜひ漏れる方がいないようにしていただきたいなということなのです。それで、陳情理由3)のところに、緊急小口は、品川区で言えば社会福祉協議会、そしてあとは東京都ということで、私たち共産党もずっと求め続けているのですけれども、こうした中小企業の固定費の補助というのもやはり今少し踏み込んで進めていただきたいなというふうに思っているのです。","respondent":"小林商業・ものづくり課長","answer":"景気情勢の中で、どういったものが企業経営に一番影響が大きいのか、与えられるところなのかというところを引き続き注視しながら、経済の下支えの中で何が必要かということを引き続き検討してまいりたいと考えています。","voiceIndex":118,"id":"exchange-037"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それでさらにインボイスも強行されているという状況では、本当に踏んだり蹴ったりだなという、もう崖っぷちから落とされる勢いですという声も本当に寄せられていますので、ぜひ、固定費補助に踏み切るべきだなというふうに私は思います。先ほど言った物価高騰対応重点支援地方創生臨時交付金、これはある、そして話は聞いている、けれども使っていないということなのでしょうか。そこを伺いたいと思います。","respondent":"小林商業・ものづくり課長","answer":"現時点で、これは恐らく東京都、例えば区政課とかを含めてですけれども、国なりというところで、品川区のほうに幾らの金額でという形での正式な連絡なり調整がまだ済んでいないといいますか、現在協議中ということで認識しています。","voiceIndex":120,"id":"exchange-038"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"すみません、ではこれから来るということなのですね。ぜひそういうもの、いろいろメニューがどんどん追加されていると思いますので、ぜひ積極的に使っていっていただきたいなと思いますし、本当にこのままでは、中小企業のこの品川のまちが本当にどんどんシャッター通りになり、商店街も厳しい状況になってくると思います。支えていくことにさらに力を注いでいただきたいなという思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-039"},{"speaker":"えのした委員","kind":"意見","question":"本日結論を出すで、不採択にします。本当に、物価の高騰、エネルギー価格の高騰によって、中小事業者の経営は困難な状況だと思うわけで、支援が必要だと思います。先ほどの議案にも賛成させていただきました。そして、先ほどの理事者のご答弁どおり、品川区では様々な支援制度に取り組まれております。理解をしましたので、不採択にします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本日結論を出す、態度は不採択です。理由を述べます。陳情者のおっしゃるように、様々この物価高騰において、安定的な事業活動に影響が生じているということは、我々も事業者の皆様からお話を伺っているところです。利息の引き下げに関しても、３年間は無利子、その上、４年目以降も低い金利に抑えているということもやっていると。以上のことから、今回のこの陳情に関しては不採択ということにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-041"},{"speaker":"山本委員","kind":"質問・要望","question":"本日結論を出すで、結論は不採択でお願いいたします。私も長くなりますが、理由を述べます。これは要望です。そのような困っている方々へ、ではどうしたら周知できるか、どうしたら届くかというのは私も考えていきたいと思うのですけれども、区としても、ぜひ工夫をご検討いただきたいということと、ご相談にいらした方々への丁寧な対応に努めていただきたいというところで、こちらも要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-042"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"結論を出すで、採択でお願いしたいと思います。それで、この新たな資金の貸付。そうした部分では区としては、本当にこれを進めていただきたいなというふうに、もうずっと私たちも求めてきたことですので、もうこれは大賛成なのです。それを支援するということ、してほしいというところは、ぜひ応えていただきたいなと思いますし、私は議会として応えていきたいなと思いますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-043"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長、職員の方々の対面でしている大変さは分かりますが、本当に丁寧に、そして思いやりを持って、区の職員は法令・条例に基づいてそれを担保に動いていると思うのですけれども、やはり人として寄り添っていただいて、ご相談、相談を受けても結果というのは出てしまうかもしれないが、その辺は対面でやっていくわけですから、思いやりを持って接していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-044"},{"speaker":"せらく委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。理由といたしましては、区内の事業者の皆様、あと、生活する皆様も今、物価高騰、エネルギー価格の高騰ですごく大変な思いをされていることは理解しておりますけれども、区で提供している支援が今あるという、ご説明の中でもありましたが、そういう現状でそういったところをしっかり使っていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2974#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":40118,"voices":136}},{"id":"r05-20231127-7","meetingId":"r05-cm11","date":"2023年11月27日","dateIso":"2023-11-27","committee":"厚生委員会","time":"午前１０時００分～午後 ４時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を112件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"では、(1)第８３号議案、品川区国民健康保険条例の一部を改正する条例の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(5)の第９０号議案","agenda":"では、(1)第８３号議案、品川区国民健康保険条例の一部を改正する条例の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(5)の第９０号議案","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"ほかの指定管理者も同様なのですけれども、今回公募によらないということで、これまでの指定管理者を選定するということになっていると思うのですが、この公募によらない特別な理由というものは、この場合はどのような理由なのかを１点伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"この現行の指定管理者を更新した理由としては、先ほどの説明でも少し申し上げてはいるのですけれども、平成３１年３月の開設以降、高齢者を含む多世代の身近な交流の場として、様々な自主事業としての交流事業を盛んに実施してくださっています。","voiceIndex":14,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"この平塚ゆうゆうプラザについては、モニタリングのところでも、これは９月のときにご報告いただいたのですけれども、そのモニタリングのところで、収支のところに、障害者や高齢者の施設は人件費が書かれているのですが、ここは人件費が書かれていなくて、なぜ人件費というものが書かれないのかということでちょっと伺いたいということと、委託料は２,１８７万円余と書かれているのですけれども。","respondent":"川原高齢者地域支援課長","answer":"複数ご質問をいただきました。１点目が、配点の選考基準の評価項目ごとに点数が出せないのかというご質問に対しての回答です。こちらについては、品川区の指定管理者の基本方針に係る基準に基づいて、総合の評価のみという形でしています。","voiceIndex":16,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"施設運営費の大きな支出というものは人件費になるのかなと思うのですけれども、その辺のところが、大体人件費という形でなるのか、その辺のところを伺いたいと思います。それと、モニタリングで、地域ミニデイ卒業グループの元気ゆうゆう体操クラブについて書かれているのですけれども、多分地域ミニデイをされているということですよね、ここで。","respondent":"川原高齢者地域支援課長","answer":"そうです。","voiceIndex":18,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問","question":"多分運動支援員が１人いて、あとはボランティアの方でやるという、そのような体系でというものが総合事業を始めるときの説明だったと思うのですけれども、今もそのような形で、このゆうゆうプラザでもやっているのか、その点も伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"ご質問いただいた地域ミニデイの部分も、やり方、運営の方法については、以前から大きくは変わっておりませんで、高齢者や地域のボランティアの方を介護予防の事業に配置させていただいているのですけれども、そのボランティアの金額というところのご質問ですが。","voiceIndex":20,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのようなボランティアの方の、募集したら必要な数だけ応募があるという、そのようなことになっているのか、ちょっとその点も伺いたいと思います。それから先ほどの、多分モニタリングのときも私申し上げたような気がするのですけれども、人件費はぜひ、この次は入れていただけるようにお願いをしたいと思います。これから改善をしていただきたいと。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-005"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"鈴木委員のお話にあったように、人件費のことはぜひ進めていただきたいと思います。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-006"}]},{"id":"topic-02","title":"第８３号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第８３号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"おぎの委員","kind":"質問・要望","question":"こちら新設の措置ですので、ぜひ進めていっていただきたいと思います。私のほうは１点だけ、質問というよりは希望なのですけれども、この届出を世帯主がしなければいけないということで、周知する方法、先ほどホームページや出産育児一時金支給などというときということでしたが、あと母子手帳交付時など、知らないでもらえなかったということがないように、広く広報に努めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問","question":"例えば出産育児一時金を国保から出すことになるので、そこのところで、これが漏れていたら、何というのですか、この申請が漏れていますよというようなことや、そのような形で漏れのない取組というものは、本人のところに申請してくださいというような形でできることが幾つもあると思うのですけれども、その辺のところの、もしも漏れてしまった場合はどのようにされるのかについて伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"ただ、財源としましては、区のほうでの４分の１の部分が負担という形になります。","voiceIndex":42,"id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これは健康保険法の一部改正ということで、今回も、国民健康保険も免除ということが出されたと思うのですけれども、社会保険のほうは、健康保険料と併せて厚生年金も、本人も事業主も免除されるということになっているのではないかと思うのですが、それで免除されても、年金受給時は払ったこととみなして受給できるということで、社会保険のほうはなっているのではないかなと思うのですけれども。","respondent":"池田国保医療年金課長","answer":"今のご質問ですけれども、実はこちらの出産時の保険料の減免につきましては、先に実施されている国民年金の保険料のやり方をまねしたというか、それを継承した形でやっておりまして、実際にはもう２年、３年以上前から、国民年金の保険料については、申請によりますけれども。","voiceIndex":44,"id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"子育て世帯の負担軽減、次世代の育成支援ということでうたっているので、子どもの均等割も無料にすべきなのではないかなと思うのですけれども、それは国会では議論にならなかったのか、分かっていたらお聞かせいただきたいですし、この子どもの均等割の無料化という方向もぜひやっていくべきではないかなと思うのですが、区のほうとしてもそのようなことを声も上げていただきたいと思いますし、もし、国。","respondent":"池田国保医療年金課長","answer":"それとお子様の、要するに出産した後の保険料が、今未就学児までが５割減額という形になって、その後無料になるのかとか、年齢拡大の話とかということでのお話かと思うのですけれども、こちらについては、実際には、私ども品川区としましても、また特別区としましても。","voiceIndex":46,"id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今の課長の答弁で、少し矛盾なのではないかと思うのです。それから、１８歳まで無料化するのに必要な財源はどれぐらいかということで、何回かこれまでも伺って、随分前は１億５,０００万円という、たしかそのような額だったと思うのですけれども、今の段階で、１８歳まで国民健康保険料を無料にするとしたら幾らぐらいかかるかということが、計算されていて分かったら教えてください。","respondent":"池田国保医療年金課長","answer":"そしてもう一つは、国民健康保険料の増額もあるかもしれません。ちょっとはっきりとしないところで、来年の３月ぐらいにはまた新しく積算したいと考えているところです。","voiceIndex":48,"id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これからも求め続けていきたいと思っていますので、ぜひ計算はしておいていただきたいと思います。それで、本当に全国の市長会でも、ずっとこの子どもの国民健康保険料の無料化ということは、今課長が言われたように、どこでも求め続けているので、これはぜひ強力に求めて実現をさせていただきたいし、区独自にも無料化ということを検討していただきたいということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-012"},{"speaker":"鈴木委員","kind":"提案","question":"この３施設についても、特別な理由がある場合は公募によらずということで今回も公募せずに、これまでの事業者ということでの提案ですけれども、その特別な理由というものは福祉施設の継続性ということなのかなと思うのですが、それであれば、私は特別な理由というところに、その理由もしっかりと明記していただきたいなと思うのですけれども、その点を伺いたいと思います。","respondent":"松山障害者支援課長","answer":"３施設とも、区と同じ課題認識の下、区全体のことを考えていらっしゃるご提案をいただいたものです。","voiceIndex":64,"id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問・要望","question":"心身障害者福祉会館から伺いたいのですけれども、今の移動支援のところでは、本当にぜひそうしていただきたいなと、もっと使いたくても人が足りなくて、実際使える時間まで使えないということをいつも伺っていますので、ぜひ移動支援の従事者を増やしていただいて、そのところで従事者の派遣をするというところで、ヘルパーステーションも開設をしていくということは、本当に期待したいと思います。","respondent":"松山障害者支援課長","answer":"正確には少し難しいのですが、概要で申し上げます。生活介護、５０人定員で、今現在４７名の方が通所されているです。医療的ケアが必要な方は実際１名ですが、そうですね、今２０名ぐらいは重度の方が通所されています。高度障害の方は７名ぐらいだと認識をしております。","voiceIndex":66,"id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問・要望","question":"トータルで何人ぐらいの方が、その心身障害者福祉会館の職員体制になっているのか、全体で何人ぐらいということを教えていただきたいと思います。それからあと、心身障害者福祉会館の虐待の報告件数というものはあるのか、相談件数ですね。相談というものがあるのか、調査に入ったことというのはあるのかも、伺いたいと思います。取りあえずそこで、心身障害者福祉会館は以上でお願いします。","respondent":"松山障害者支援課長","answer":"虐待についての相談件数ですけれども、それはございません。全体のはちょっと計算をしないとならないので。","voiceIndex":68,"id":"exchange-015"},{"speaker":"鈴木委員","kind":"提案","question":"大丈夫です。相談件数がなくてよかったと思います。発達障害者の９月のモニタリングで、収支のところが赤字になっていたと。それから、先ほど連携体制の強化ということで、様々、この発達障害に関わるところで連携していくということで提案をされていて、それを本当に進めていただきたいと思うのですけれども、具体的にどのような形で連携をしていくという提案なのかも伺いたいと思います。","respondent":"松山障害者支援課長","answer":"発達障害者支援施設の財務状況の評価についてです。こちらは施設というより、法人全体の財務評価になりまして、ただ４０点中２４点ということは６割、６割ということなので、過半数は超えているので、低いということではないかと考えています。安定して運営をしているものです。","voiceIndex":70,"id":"exchange-016"},{"speaker":"鈴木委員","kind":"提案","question":"本当にこの連携というものはすごい大事なことだと思うのですけれども、このような場合は、何というのですか、品川区のほうから働きかけて、ここにそのようなことで担ってくださいという、そのような区としての方針というものが必要なのではないかなと思うのですが、発達障害者支援施設ぷらーすのほうからも提案という形になったのか、それとも区のほうから働きかけて今回の提案になったのか。","respondent":"松山障害者支援課長","answer":"区としても、発達障害者支援施設を、きちんと中心的な役割になるということを明示させていただきまして、その後、連携は必要だという認識は区としても持っておりましたので、モニタリング等では、発達障害者支援施設の現指定管理者である社会福祉法人げんきとは。","voiceIndex":72,"id":"exchange-017"},{"speaker":"鈴木委員","kind":"確認","question":"世話人について、この資格を問われないということが、もっと本当にきちんと資格が問われるべきなのではないかなといつも思っているのですけれども、結局この勉強会というものがその中でされているということは評価されるものですが、上大崎つばさの家では非常勤の方ということで、人員体制としては、有資格の方はいらっしゃらなくて、資格のない方が世話人の勉強会などに参加されながら。","respondent":"松山障害者支援課長","answer":"世話人の状況です。世話人は、職員体制の中で夜間支援を含めまして８人の方がいらっしゃいます。その中で常勤が３人、それから非常勤が５人という人数です。その常勤の方の中には、介護福祉士の資格を持っていらっしゃる方もいらっしゃいます。","voiceIndex":74,"id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"先に、議会といたしまして、１人１００点として４名で計算して４００点、そしてその評価の点数を決めているものというのは、この後ろに別紙である指定管理候補者選定基準の評価項目と配点のところという理解でよろしいでしょうか。それがもしこの内容でよいとしたら、財務状況の評価の、この１人持ち点の１０点分というものは、その別紙についてのどの項目に当てはまるかということも、併せて教えてください。","respondent":"松山障害者支援課長","answer":"こちらのほうにつきましては、報告書については財務状況等の評価というものを加えさせていただいているのですけれども、こちらの評価項目の配点につきましては、もちろん、これ以外１００点満点ということで、１人１００点満点ということで評価項目をつくっているものです。","voiceIndex":78,"id":"exchange-019"},{"speaker":"ひがし委員","kind":"提案","question":"そうなってくると、１人が１００点満点で評価をして、提案内容評価のところの３６０点のようなところは点数が合わないと思うのですけれども、ごめんなさい、もしかしたら皆さん違うかもしれないですが、採点表というところも１００点というものは、１人の持ち点の１００点というものは、この別添えのところの表記されているところの１００点で評価されて、それでここに合計されているのかなと。","respondent":"松山障害者支援課長","answer":"この別添えの中の３「管理を安定して行う物的能力および人的能力を有していること」の中の、「福祉サービスを安定的に提供できる経営基盤を有しているか」、この中に、含まれていました。","voiceIndex":80,"id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問・要望","question":"前回、指定管理全般のことで言わせていただいたのですけれども、今のところでいうと、この点数というものはすごくよく分かりやすくて、大体平均６点ぐらいで出ているのかなというところで把握ができるのですが、ほかのところの項目が満点の３６０点にまとめられてしまっていて、どこが高くて低いのかというようなところの理解ができないというところが現状でありまして、特に気になるような項目でいくと。","respondent":"松山障害者支援課長","answer":"独自に福祉部だけ、あるいは課だけということではならないのではないかと考えております。そのところ、企画のほうには伝えていこうと考えています。","voiceIndex":82,"id":"exchange-021"},{"speaker":"ひがし委員","kind":"質問・要望","question":"もう１点聞かせていただきたいことは、品川区で統一して、この評価の基準を使われているということだったのですけれども、ほかの区のところなどを調べてみると、点数の差がなかったり、項目が少し違ったりという市などもあるのですが、これは東京都全体でこの項目を使っているのか、それとも品川区がこれを使っているという理解だったとすると、配点のところなど。","respondent":"松山障害者支援課長","answer":"区全体で品川区の指定管理者制度活用に係る基本方針、あとはその実施要領というものがあります。ですから、東京都ではなく、品川区として決めている、大枠決めているものです。","voiceIndex":84,"id":"exchange-022"},{"speaker":"ひがし委員","kind":"質問・要望","question":"区が決めているということで理解をしますと、この内容の項目について、例えば５点のところがあったり、１０点のところがあったり、１５点のところがあったりと、確かにこの１５点が入っている経営の実績などというところはすごく大切な項目だから１５点なのだろうなということは理解しているのですけれども、逆に言うと、家族の要望・意見などのところの５点は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-023"},{"speaker":"筒井委員","kind":"確認","question":"今回公募方式によらず、現行の指定管理者を選定されたということで、その品川区指定管理者制度の活用に係る基本方針の規定に基づいたということなのですけれども、まず確認として、これ今回の３施設の指定管理者は、今まで、今までというか、令和６年３月まで、５年間今までやっていたということでよろしいのでしょうか。","respondent":"松山障害者支援課長","answer":"品川区指定管理者制度活用に係る基本方針が令和３年度に改定されまして、１５年間は公募によらず、理由がある場合は継続、そのまま公募せず、公募によらずに指定管理者としての選定ができるという規定がありますので、その規定に基づきまして行っているものです。","voiceIndex":88,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"それとも、令和４年度末に指定管理期間の終期を迎える施設以外はずっともう、ずっと延長できるということなのですか。","respondent":"松山障害者支援課長","answer":"基本方針によると、１５年までということで指定期間としてはされております。そのため、心身障害者福祉会館については、第１期目は終了したということで、あと２期、３期が残っているです。","voiceIndex":90,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"逆に言うと１５年まで延長できるということで、その指定管理者の方も、１５年までできるのかなという期待を抱かれてしまうのかなという、今回きちんと選考などしておられるので、緊張感を持たせることもできるのですけれども、もう指定管理者の運営側も、どうせ１５年できるだろうというように見込んでしまうのではないかと思ってしまうのではないかなという懸念があるのですが、もうその点の歯止めというか。","respondent":"松山障害者支援課長","answer":"今回の指定管理期間は令和６年４月１日から令和１１年３月３１日という５年間ですので、また議決いただければ、５年後にはまた予備委員会、選定委員会ということで、外部の有識者も入れてきちんとご審議いただいて、指定管理者候補者として選定し。","voiceIndex":92,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"ちょっとまた逆説的になるのかもしれないのですけれども、その１５年たってまた公募をかけなければいけないという状況があるかと思うのですが、結局それ公募で集まる指定管理者の方が現れるのかという、５年後のことなのでどうなるか分からないのですけれども、区としてほかに何か当てがあるというか、何となくこのような事業者があるなというような想定、５年後もし公募に応じなかった。","respondent":"松山障害者支援課長","answer":"そのためには、やはり指定管理、あるいは品川区を魅力的に、今、実際にこの事業をやってみたいというような事業者が今後でてくるように、やはり私たちもサービスの向上を図っていくという必要があります。","voiceIndex":94,"id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"提案","question":"要望なのですけれども、先ほどひがし委員の評価基準や配点についてのことにやはり提案内容の評価のところが３６０点というところですごい大きくあって、ボリュームがあって、財務状況は４０点切り分けられていますけれども、もう少しこの提案内容の３６０点のところを切り分けて、地域交流とか、利用者対応とか、そのように分けていただいたほうが分かりやすいのかなというところと、あと何というのですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-028"},{"speaker":"おぎの委員","kind":"質問・要望","question":"先ほどの評価項目の表のお話を聞いていて、１点ちょっと確認をさせていただきたいのですけれども、配点で５点、１０点、１５点とばらつきがあるという点で、これ、例えば３番の「福祉サービスを安定的に提供できる経営基盤を有しているか」、５点掛ける２となっているのですが、これはこの１行にまとまっていますけれども、実際に私は見たことがないのですが。","respondent":"松山障害者支援課長","answer":"それぞれ項目について、重要だと思われるものについて２倍ということになっております。","voiceIndex":99,"id":"exchange-029"}]},{"id":"topic-03","title":"第９１号議案、診療報酬等の返還請求に関する民事訴訟の提起","agenda":"第９１号議案、診療報酬等の返還請求に関する民事訴訟の提起","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"これが令和２年１月までの間、看護職員の人員配置基準は満たさなかったということなのですけれども、それ以後は解決して満たした状況で、運営されているということなのか、そのところも伺いたいと思います。それが返還しないということは、病院側の理由としては何かあるのか、その点についても伺います。","respondent":"豊嶋生活福祉課長、池田国保医療年金課長","answer":"どこに該当するかということは、そこまでは把握はできておりません。人数については、生活福祉課分については２名の方が入院をされておりました。現時点では、１名の方は既に退院をされておりまして、１名の方は現在も入院中です。国保の被保険者につきましても、２名の方が入院していたというような形での返還請求という形になります。","voiceIndex":133,"id":"exchange-030"},{"speaker":"鈴木委員","kind":"質問","question":"そのような形で、実際加算されていないのに請求していたという不正請求なのに、なぜ返還命令に応じなくて、長い間、９月に返還命令に応じなくて、このような民事訴訟にせざるを得なくなったのか、その病院の言い分というか、何かそのようなものはあるのか、伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"もう１点、訴訟費用についてですが、こちらについては、今後ご議決いただいた後に集団提訴という形になろうかと思いますので、その辺りは手を挙げる他区、それから東京都と十分に協議していきたいと考えております。","voiceIndex":136,"id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"確認","question":"ちょっと確認なのですけれども、時効はいつまでということはお分かりでしょうか。","respondent":"池田国保医療年金課長","answer":"こちらのほうですけれども、請求してからの時効については、これは民法第７０３条ということで、１０年間になります。","voiceIndex":139,"id":"exchange-032"},{"speaker":"やなぎさわ委員","kind":"質問","question":"実際その報酬の返還分プラス、例えば損害遅延金のような形の請求もされるご予定でしょうか。","respondent":"池田国保医療年金課長","answer":"遅延金についても、請求について考えているところではありますけれども、こちらのほうも各区統一でというようなことも、課長会のほうでは申合せをしています。","voiceIndex":141,"id":"exchange-033"}]},{"id":"topic-04","title":"第９４号議案、指定管理者の指定","agenda":"第９４号議案、指定管理者の指定","exchanges":[{"speaker":"鈴木委員","kind":"提案","question":"事業費としての提案というものはあったのか、現事業者より高い事業費となるということが提案としてあったのか、その点についても伺いたいと思います。それから、区民の健康増進につながる具体的かつ実現可能な提案ということもあるのですけれども、これは具体的にどのようなことなのか、そのこともお聞かせください。取りあえず、以上お願いします。","respondent":"若生健康課長","answer":"こちらについては、そもそも事業者についてはこれまでも取り組んでいただいているところなのですが、気軽に楽しく利用できる施設といたしまして、フリー料金、これは品川健康センター５００円、荏原健康センター４００円、このフリー料金内で。","voiceIndex":159,"id":"exchange-034"},{"speaker":"鈴木委員","kind":"提案","question":"事業費なのですけれども、この事業費が、安い提案というようなところは、選ぶ基準として加味されることがあるのか、その点を伺いたいと思います。それから、指定管理者の利益というものはどのような状況になるのかも伺いたいと思います。インストラクターは正規の職員でやっているのか、その点もお聞かせください。","respondent":"若生健康課長","answer":"むしろ、区のほうで補填をさせていただいているような状況ではあるのですけれども、今後、今年度以降は、見込みとしては利用料のほうが戻ってきておりますので、還元も一定程度出てくるということで見込んでいるところです。","voiceIndex":161,"id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうすると、これは２社でやらないとできないというものなのか、ちょっとそこのところは、住友不動産だったら施設の維持もできるのではないのかなという思いがするのですけれども、それは、なぜこの２社が一緒に管理するということになっているのか、その点も伺いたいと思います。","respondent":"若生健康課長","answer":"それから収入基準額についてですが、こちらについては年度当初の協定のほうで積ませていただいて、利用料金に対して、利用人数を当初見積もりまして、それに対してどのぐらいの来客が見込めるか、どのぐらいの利用があるかというところを、区のほうである程度算定しています。","voiceIndex":163,"id":"exchange-036"},{"speaker":"筒井委員","kind":"質問・要望","question":"本件の指定管理の選定に当たって、その利用料金５００円にするということは区側の求める要件だったのか、それともそういった条件をつけずに公募をかけたのか、その辺り、利用料金についてどういった条件や評価でこれが行われたのか、ご説明ください。","respondent":"若生健康課長","answer":"利用料金の設定に関しましては健康センターの条例で規定しておりまして、その条例に基づいて事業を実施していますので、こちらについては指定管理の公募の要領にもその表記のままで、これは条例を改正しない限りは、利用料金というものはそのまま５００円。","voiceIndex":166,"id":"exchange-037"},{"speaker":"筒井委員","kind":"質問","question":"ではその利用料金という前提の下、皆さんプレゼンをやったということだと思うのですけれども、今回決まった住友不動産エスフォルタ・ＮＴＴファシリティーズ共同事業体ということで、ＮＴＴファシリティーズ、特に財政状況もよくて、資本金１２４億円、従業員数５,１００人ということで、かなり大手なのですが、今回ほかの応募してきた事業者も、会社の規模というか。","respondent":"若生健康課長","answer":"ほかの応募事業者の財政、規模ですか、そういったところになりますが、ちょっと具体のところは申し上げられないところなのですけれども、やはりこれだけの施設を運営するには、それなりの事業規模のところですとか、体力というか、財務的にもしっかりした事業者でないと。","voiceIndex":168,"id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。会議要旨などを見ると、環境、ＣＯ２排出量とか、光熱費削減とか、そうした環境配慮ができるかどうかということがポイントになったのかなと思っているのですけれども、今後、例えば品川健康センター、荏原健康センター、その施設を環境配慮型のものに改修していくということも想定しての、こうした環境配慮にポイントを置いたというようなことなのでしょうか。","respondent":"若生健康課長","answer":"健康センターについては、もう荏原健康センターは今移転して、仮という形で運営しているところで、一定程度環境に配慮した形にはなっているのですが、品川健康センターのほうは、従来建ててから２４年くらいが経過していて、それなりに施設も傷みが出てきているところで。","voiceIndex":170,"id":"exchange-039"}]},{"id":"topic-05","title":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"確認","question":"この期間が今、令和５年の４月から令和６年の３月までということなのですけれども、これまでもされていたと思うのですが、これまでされていた期間というものは、令和５年の３月までだったということなのですか。そこの確認をお願いしたいと思います。それで、東京都は年間１６万円、１６万円ぐらいでしたか、そこの東京都の制度そのものも教えていただけたらと思います。取りあえずお伺いします。","respondent":"若生健康課長","answer":"公衆浴場への支援、こちらは同等の補助を昨年度も、１２月の際に補正予算のほうで提案させていただきました。その際も、令和４年４月から令和５年３月分までということで、１２か月分、休業月は除くという形で、同様の形で支給をしています。","voiceIndex":185,"id":"exchange-040"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それはよかったと思います。本当に公衆浴場というものはだんだん少なくなっていっていて、今ある浴場はぜひ存続していただきたいと思いますので、このようなことをするのはすごく大事なことだと思います。都全体でも、前回のところでは１３区ということで、さらに増えているのかと思うのですけれども、都全体の状況が分かったら、それも教えていただきたいと思います。","respondent":"若生健康課長","answer":"都全体の浴場の支援ですが、私どもで把握しているところで、７月２０日時点で都内の調査がございまして、その中で把握したところですと、２３区では２３区中１６区、区外のところでは、一部条件あるのが１市のみが補助となっているというような状況を確認しています。","voiceIndex":187,"id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それがこのような形で出されるということは大事なことだと思いますので、このような状況が続く限りは、ぜひこの制度は、来年３月だけで終わりというのではなく、続けていただきたいということで要望もさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"今回、公衆浴場に対して、電気、ガス等の物価高騰の影響を受けたということで、支援を一月当たり１０万円行うということなのですけれども、その１０万円を交付するに当たり、なぜ公衆浴場という特定の業種に対して交付をするのか、ほかの飲食店などもこの物価高騰で大変な影響を受けておりますし、また、私の聞いたお話ですと、アニメーターなどもすごい電気を使うので。","respondent":"若生健康課長","answer":"いずれの業態にも当てはまるところとして、やはりこういった燃料が大量に使用するというところで、そういった物価高騰、特に光熱費の高騰というところが非常に経営に対して打撃が大きいと聞いておりますので、そういったところをまず区としては重点を置いて支援するという考えで。","voiceIndex":191,"id":"exchange-043"},{"speaker":"筒井委員","kind":"質問","question":"やはり、特にそのお仕事において燃料などの料金が大きいところ、その事業をするに当たって、燃料費というものが非常に重要なところを占めるという業種だからこそ支援するという理解でよろしいのでしょうか。","respondent":"若生健康課長","answer":"やはり物価高騰というように、公衆浴場はそのような形でやっておりますので、必ずしもそれは燃料だけを絞ってというわけではないですが、やはりその中でも大きい割合を占めるというところでは、やはり燃料費の支援というところが区としては考えなければいけないということで。","voiceIndex":193,"id":"exchange-044"},{"speaker":"やなぎさわ委員","kind":"確認","question":"確認なのですけれども、この支援金はどのようなスキームで支払うのでしょうか。申請があったら支払うのか、一括で組合などに支払われるのか、お願いします。","respondent":"若生健康課長","answer":"こちら補正予算のほうが議決されましたら、まずご案内を全ての事業者、浴場のほうに、これは書面を通して周知させていただきまして、申請については各浴場事業者のほうから直接区のほうに申請をいただきまして、それで一括して。","voiceIndex":196,"id":"exchange-045"},{"speaker":"おぎの委員","kind":"質問・要望","question":"こちら区民の保健衛生の向上のみならず、地域のコミュニケーションの場ともなっていますので、現在も引き続き支援していただきたいと思います。大きく賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":205,"id":"exchange-046"}]},{"id":"topic-06","title":"令和５年請願第１７号、パンデミック条約締結及び国際保健規則改正に係る情報開示を求める請願","agenda":"令和５年請願第１７号、パンデミック条約締結及び国際保健規則改正に係る情報開示を求める請願","exchanges":[{"speaker":"おぎの委員","kind":"質問・要望","question":"今回パンデミック条約と国際保健規則改正の情報公開を求める請願をお受けしました。２、議員、有識者、その他一般国民から意見を聴取する手段を早期に開始していただきたい。利害ですから、利する側と害する側が両方存在するわけですが、利する側は参加しても、害する側は参加できません。そして、ＷＨＯに最も献金しているのが、利する側の製薬企業の団体であることが、ＷＨＯのホームページで確認できます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-047"},{"speaker":"鈴木委員","kind":"質問・要望","question":"加盟国は公平性を考慮し、備えを促進し、連帯を確保し、国家主権の尊重を含む国際的な合意を求めるとともに、来年の５月のＷＨＯ総会において成果物を提示することを目指していますということで書かれていまして、我が国としては、パンデミックの予防、備えおよび対応、このＰＰＲ、これを強化するために、国際的な軌範や規制を強化することが重要であるとの立場であり、交渉の結果は予断しないものの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":214,"id":"exchange-048"},{"speaker":"こしば副委員長","kind":"質問","question":"それで、国権の最高機関たる国会というものは、当然民主的な選挙で選ばれた議員より審議がされるわけですから、当然そこには民主主義が担保されていると思いますので、そもそも論、中身をいろいろと説明のほういただきましたけれども、本来この区議会の厚生委員会の場で話す、議論する場にふさわしいかというと、若干そうではないのではないかという印象は、やはり説明を受けましても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":216,"id":"exchange-049"},{"speaker":"おぎの委員","kind":"質問・要望","question":"１２月の頭には７回目が行われます。ところが今回、国民の生活に影響が出るかもしれない条約について、一切公表がないのはどのようなことでしょうかと私も思います。不安をあおるというなら、なおさら広く告知し、国民を安心させるべきではないでしょうか。中身がよい悪いといったことよりも、こういったことを広く知ってみんなで議論していただきたいということを求めている請願であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-050"},{"speaker":"筒井委員","kind":"質問","question":"記憶に新しいことかと思います。ですから本当に、なぜ今の今までにこのような議論が日本で進んでいなかったということは、非常に問題かと思います、その国会での審議を進めさせるためにも、国会議員に伝えるためにも、また政府に対して意見を伝えるためにも、やはりその条約の賛成反対以前に、賛成反対を意思表明する前提の、もっともっと情報提供、周知が必要かと考えております。私からの意見は以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-051"},{"speaker":"やなぎさわ委員","kind":"確認","question":"おぎの委員に１つ確認なのですけれども、この理由のところにある、先ほどから理由のところにも先進国、途上国というようなお話があるのですが、日本はどちらに該当するのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":222,"id":"exchange-052"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これはもう、このＷＨＯの話合いの中で、その枠組みで話し合われているということでよろしいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-053"},{"speaker":"おぎの委員","kind":"意見","question":"ただ、先ほど言いました国連加盟国１１か国、反対をしている国がある、そちらの国が、ベラルーシ、ボリビア、キューバ、エトアニア、エリトリアなど、いわゆる、どちらかというとベネズエラ、ジンバブエなど、供給される側の国が反対の署名を国連に提出していますので、実際この枠組みの中で、その枠組みを必要としているのかというものも、発展途上国側の意見だけではなく。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":225,"id":"exchange-054"},{"speaker":"やなぎさわ委員","kind":"質問","question":"要旨の部分と理由の部分が結構、個人的に差があるというか、やはりまだ草案の段階というところもあり、そして日本としてのスタンスもまだ決まっていないような状況だったりするところで、ここの理由のところは、何というのですか、まだ本当にこれからどうなるか分からないというようなところは正直感じます。ただ、要旨は賛同できると、個人的には考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":227,"id":"exchange-055"},{"speaker":"おぎの委員","kind":"意見","question":"そうですね。今、完成のものはまだ出てきていないので、どこの国でも待っているものは草案です。ただ、草案の段階ですが、決まってからではもう遅いので、広くほかの国のように議論していくことが、日本国内でも重要だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":230,"id":"exchange-056"},{"speaker":"ひがし委員","kind":"意見","question":"ただ、現状で書いている懸念することや危惧することというところは、本当にこのままのとおりだとするなら確かに心配かなというようなところは、すごくお気持ちも分かるなというところなので、その皆様に調べるタイミングと、あと説明の仕方というところ、この決まっていく段階の中で、今すごく国の中でも議論してくださっているというところで、超党派の議連としても協議をしてくださることだと思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":231,"id":"exchange-057"},{"speaker":"鈴木委員","kind":"質問","question":"それで、本当に今回このような形で、今ＷＨＯがパンデミック条約と国際保健規則の改正を検討するということは必要なことだと思いますし、世界的にこのような体制を取っていくというようなことは必要だと思いますので、ここのところで書かれている懸念だったり、何というのですか、先進国の援助義務だったり、そのようなことに対しての懸念というか、否定するようなということそのものが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":235,"id":"exchange-058"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ちょっとこの要旨と一歩踏み込んだ話になってしまうのですけれども、おぎの委員に確認させていただきたいのですが、この懸念されていることは、このとおり、この理由に書かれているとおりのＷＨＯの条約が可決されて、日本も合意した場合に、最も危険なのはワクチンなどを強制的に日本国民が接種させられるという、そこが一番問題だというお考えでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-059"},{"speaker":"おぎの委員","kind":"意見","question":"後進国への援助を含め、先進国がやっていくという、そちらの責任に対しては、もちろん日本も先進国として援助をしていくべきだとは思いますが、ただ後進国での希望とのギャップ等が出てきているようでは、それはただの押しつけになってしまいますので、この辺含め、国連などでしっかりと、こちらＷＨＯでも審議していただいて、その内容を、今回はこちらの請願の趣旨としましては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":238,"id":"exchange-060"},{"speaker":"こんの委員","kind":"質問","question":"もう一定の皆さんのご意見も出ましたし、態度表明もほぼほぼ出ている状態だと思います。これで意見陳述のほうは必要がないのではないかと判断しますが、皆さんいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":241,"id":"exchange-061"},{"speaker":"こしば副委員長","kind":"質問・要望","question":"私も今、こんの委員と同じように、おぎの委員の説明でこの趣旨も理解はできましたし、また意見については先ほど私がお話ししたとおりであります。ですから、これ以上の意見陳述は求めなくていいのではないのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":243,"id":"exchange-062"},{"speaker":"鈴木委員","kind":"意見","question":"私はこの請願は反対ですけれども、意見陳述は常に聞くべきだと思いますので、意見陳述をしていただいてよいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":246,"id":"exchange-063"},{"speaker":"筒井委員","kind":"意見","question":"こうした状況でしたら、最初に意見陳述を聞きたかったと思うのですけれども、私としてはせっかく請願を出されて、お越しいただいているということなので、意見陳述の申出を受けたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":247,"id":"exchange-064"},{"speaker":"おぎの委員","kind":"質問・要望","question":"議会運営の慣例にのっとり、来ていただいているので意見陳述を私は求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":248,"id":"exchange-065"},{"speaker":"やなぎさわ委員","kind":"意見","question":"そうですね。区民の方の思いがあっての請願ですし、わざわざお越しいただいて、恐らく話す内容もしっかりと考えてきていただいたというようですので、私は区民の声はしっかりと委員会で聴くべきだと思いますので、ぜひお話を聞ければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":249,"id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いいたします。ただ、この危惧されている点などについては理解できるところもありますので、その点については先ほどお話あったように国会を中心として国でしっかりと議論をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":256,"id":"exchange-067"},{"speaker":"鈴木委員","kind":"提案","question":"結論を出すということで、この請願に対しては不採択でお願いしたいと思います。先ほど、第３条のところのことも言われておりましたけれど、そのテキストというのは、加盟国から出されている提案全てを暫定的に書き込んだものであって、今後成案づくりを主導するＷＨＯの検証委員会はその案を採用しないという旨を既に表明しておりますので、主権の侵害ということには当たらないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":257,"id":"exchange-068"},{"speaker":"おぎの委員","kind":"意見","question":"本日結論を出すで、お願いします。こちら、今まだ素案の段階ですので、内容等含め、決まったものはございませんが、広く国民に周知して議論していくことが非常に大事だと私も考えます。こちらのほう、採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":259,"id":"exchange-069"},{"speaker":"やなぎさわ委員","kind":"意見","question":"というところで、現状においては、まだはっきりとしたことが言えないというところで、不採択といたしますが、議会としても今後注視していく必要は十分にあると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":260,"id":"exchange-070"}]},{"id":"topic-07","title":"令和５年請願第１８号、補聴器購入費助成制度を求める請願","agenda":"令和５年請願第１８号、補聴器購入費助成制度を求める請願","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"今おっしゃっていた、アンケートの内容というのはいつ頃に決まって、この委員会でもぜひ内容というのは共有していただきたいなというふうに思うのですけど、その予定とかあれば教えてください。","respondent":"川原高齢者地域支援課長","answer":"そのやり取りを経てからお送りをいたしますので、実際の発送は早くても年内か年明けあたりになるかと予想しています。このアンケートの内容の状況につきましては、集計次第、具体の中身を確認いたしまして、またこちらで、実施するかに関しては検討してまいりたいと思います。","voiceIndex":268,"id":"exchange-071"},{"speaker":"ひがし委員","kind":"質問・要望","question":"このアンケートの内容というのもぜひ知りたいなと思うのですけど、どういうふうにそのアンケートの内容を決めていくというのは、今のご説明ですごくよく分かったのですが、この助成を金額上げるとか、非課税ではなくて課税者にも、みたいなことの話をするとき、そのアンケートでどうやって使用していて金額が足りなかったのかとか、今ずっと使っているとか、そのアンケートの内容が分からないと。","respondent":"川原高齢者地域支援課長","answer":"こちらの委員の皆様への公開については、今いただきましたご意見を踏まえまして検討させていただきたいと思います。","voiceIndex":270,"id":"exchange-072"},{"speaker":"ひがし委員","kind":"質問","question":"申請をした人の中でも、何割かの方は、課税者だったから助成がされなかったとか、高度難聴ということもあるのかなというふうに思っているのですけど、今後の見込み、この今決まっている予算というのは３５５万円余でしたか、予算が当てられていて、人件費とかを乗せると大体８０人ぐらいがカバーできると以前説明いただいたと思うのですけど、今度の見込みはどのぐらい増える予定なのかなというのがもし。","respondent":"川原高齢者地域支援課長","answer":"それが８０人分の約半数を少し超えるぐらいですので、今後の見込みとしては、その支出のケースに関しては、その方が医師の診察を経て、補聴器店で見積りをもらうまで、人によってタイムラグが出るので、必ずしも一律ではない形なのですけれども、これから支出を予定している方。","voiceIndex":272,"id":"exchange-073"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ただ、予算額がやはり、これから先オーバーしてしまうのではないかなという、知られれば知られるほど、やはり受けたいという方も多いのではないかなというふうに思いますし、前回お話しいただいた非課税の高齢者の割合も４万人近くいらっしゃるというところでいくと、その分の３分の１の方が耳の聞こえづらさを感じていて、３分の１となると１万２,０００人、今の８０人の規模の予算だと。","respondent":"川原高齢者地域支援課長","answer":"それで次の予算の組立に対しての、という内容よりかは現行の制度できちんと実施が、効果が図られていたかというのが中心の内容のアンケートとして今は考えているところです。","voiceIndex":274,"id":"exchange-074"},{"speaker":"鈴木委員","kind":"質問・要望","question":"７月から実施されて、この補聴器の補助制度というのは、荏原医師会の先生方からの要望としても、たしか平成２７年度ぐらいから要望されていて、長い間ずっと要望されていてやっと実現したし、また認定補聴器技能者の皆さんからも、もうずっと要望されていたものだったと思うのですけど、改めてこれが品川区でも実施されるようになったことを受けて。","respondent":"川原高齢者地域支援課長","answer":"それで、ようやくその実施に結びついたというところで、非常に喜んでくださっていたというところが、私も実感をしています。","voiceIndex":277,"id":"exchange-075"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、東京都からもし半額が出るとなったら、８０人というのはその倍の人数を受入れ、助成ができるというふうなことになるのかなと思うのですけど、そういうことも含めて、もしそれでも足りなかった場合は、補正を組んででも申請者は全員助成しますよという姿勢なのか、その点についても伺います。","respondent":"川原高齢者地域支援課長","answer":"東京都の補助事業の助成に対することなどのご質問です。委員のご指摘のとおり、補助率は２分の１ですので、歳入が約半数、半分、見込みがあるところではありますけど、現在申請をしています。","voiceIndex":279,"id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ、さらにこれを拡大していただきたいというふうに思います。そういう方が、やはり非課税だけということになると対象にならないということに関しては、対象として課税者までというのは、もうぜひ、この高齢者の実態からも必要ではないかと思うのですけど、その点は、高齢者の生活実態というふうなところからしたら、区としてはどう考えられているのかを伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"現行では非課税の要件にはなってしまうのですけれども、今後実施するアンケートでも、その方の購入金額も踏まえて、予算額に例えばそれが見合っていたかであるとか、購入者で、両耳ではなくて片耳のみ購入する方もいらっしゃるので。","voiceIndex":281,"id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、各会派から、請願に賛成しない会派も含めて、住民税課税まで対象にしてほしいという要望というのは出されていると思うのですけど、そういうふうに各会派から、多分、全会派から出されているかなというぐらいな思いがしているのですけど、そういうふうに、各会派から出されていながら、来年度まだ予定がないということで、住民税課税者までやりますよというような方針が取れないのは。","respondent":"川原高齢者地域支援課長","answer":"高齢者の社会参加やフレイルのほうの促進からも、現在は現行のスキームで実施をしていますので、現在のところは実施の予定はございません。今後の見込みに対しても、現在も引き続き検討をしています。","voiceIndex":283,"id":"exchange-078"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に、これだけ強い要望が各会派からも出されていますし、それから高齢者の実態からも必要だというふうなところで区も認識されているということですし、それから、額的にもそんなに、区の予算でできない額ではないですし、そういう点では、もう来年度、今から検討して来年度やるというふうな可能性というのはあるかどうか、その点も伺いたいのですけど、そういうところで、ぜひ……、言いましたか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":285,"id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"要望のような形になってしまうかもしれないですけれども、まず、この請願の趣旨、すばらしいなと思いまして、何かというと、２行目のところに、区民としては大変感謝いたしているというところで、やはり、こういった事業が始まったことで、区民の皆さん、大変喜ばれているということで、すばらしい取組だなといった、事業が始まったなというふうに、まず思っております。","respondent":"川原高齢者地域支援課長","answer":"今後のそういった拡充であるとか増額につきましても、現在は全くまだ、引き続き検討しているところでございまして、都の補助事業の内容であるとか来年度の状況も確認するのと、あと、他の自治体も本当にいろいろな要件の設定が異なってきますので、そこも含めて来年度。","voiceIndex":287,"id":"exchange-080"},{"speaker":"こしば副委員長","kind":"意見","question":"結論を出すで、今回の請願については、先ほど課長からの答弁にもありましたとおり、アンケートの内容についてまたこれから出てくると、そういった情報をしっかり吟味した上でまた判断をしていくのがいいのではないかと考え、不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":292,"id":"exchange-081"},{"speaker":"こんの委員","kind":"質問・要望","question":"先ほど質疑はしませんでしたけれども、先月の決算委員会で我が会派から、民生費のときにこの補聴器の購入についての質問をさせていただきました。そのときに、制度のはざまをつくらないで誰もが対象となるように、そうした体制を求めたところ、区としては、今時点でという答えではありませんでしたけれども、それを検討していきますという前向きなご答弁をいただいておりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":293,"id":"exchange-082"},{"speaker":"ひがし委員","kind":"質問・要望","question":"結論を出すで、お願いをいたします。結果としては不採択でお願いします。先ほどもお話をさせていただきましたが、補聴器の助成というところ、この制度始まったこと大変評価しておりますし申請も増えているということで、今後も使いたい方が使えるように、予算拡大そして対象者、課税者も含めてというところは、ぜひ前向きに検討していただきたいというふうに要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":294,"id":"exchange-083"},{"speaker":"鈴木委員","kind":"質問・要望","question":"結論を出すで、請願に対しては採択でお願いしたいと思います。予定がないということであれば、これは議会でこれを採択して、議会としてそれを求めていくということ、議会がここで採択をすれば区はやらざるを得なくなるわけですから、ぜひ採択をして、これを実施させていくということでお願いしたいなというふうに思っています。採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":295,"id":"exchange-084"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すということでお願いします。そもそも私としては、助成とかには所得制限などかけないほうがよいという考えであり、またこの補聴器が認知症予防等に効果があるというのならば、課税者までの拡大を検討していっていただきたいと考えておりますけれども、一方で税金を使うわけですから、しっかりとそのアンケート等々で効果の検証をしっかりとしていただくと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":296,"id":"exchange-085"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日結論を出すで、お願いします。９月末で１５０件申請があったということで、非常に区民の関心が高く、ニーズはあるのかなと思います。１５０人の中でも結局、高度難聴であったり、課税者だったので漏れてしまった方というのもいらっしゃるということで、漏れてしまった方は本当に必要としていたのだろうなと思います。それで、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":297,"id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"意見","question":"先ほど、鈴木委員のご発言のとおり、アンケートと課税者への拡大とはどこまで関係があるのかなというところを思いつつ、ただ、やはり、ほとんどの委員の方は、不採択と言われた委員の方は、アンケート結果を注視というようなことが多かったので、一刻も早くアンケートを実施して、集計をして、それを助成につなげるということをするのが、この委員会含め議会の役割だと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":298,"id":"exchange-087"}]},{"id":"topic-08","title":"令和５年陳情第４４号、品川区立重症心身障害者通所事業所「ピッコロ」移転・拡張に伴い、現在通所できない呼吸器利用者が通所可能になるための整備を求める陳情","agenda":"令和５年陳情第４４号、品川区立重症心身障害者通所事業所「ピッコロ」移転・拡張に伴い、現在通所できない呼吸器利用者が通所可能になるための整備を求める陳情","exchanges":[{"speaker":"やなぎさわ委員","kind":"質問","question":"現在のところは生活介護で、人工呼吸器の対応する施設はないと。ただ、八潮南の増改築含めて、これ、今後、人工呼吸器を対応したような施設を増やしていく。つまり、八潮南以外でもいずれ増やしていく可能性があるというような認識でよろしいでしょうか。","respondent":"川崎障害者施策推進課長","answer":"こちら、先ほどもご説明させていただいたとおり、病院とは異なるので、やはり人工呼吸器を使用するというのは、かなり看護師の職員配置、手厚い人員配置というものも求められますので、どの事業所についても、やはりその人材確保というのは大変難しい状況ではあります。","voiceIndex":307,"id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問","question":"決まっていればでいいのですけど、どれぐらいの人員の対応を見込んでいらっしゃいますでしょうか。","respondent":"川崎障害者施策推進課長","answer":"こちら、開設が令和９年度になりますので、まだ詳細のところは、現段階では決まってはおりません。ただ、やはり重度の障害者ではありますので、手厚い人員配置というところで考えていく体制ではおります。","voiceIndex":309,"id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"質問","question":"令和９年となると、まだまだ先かなと思うので、その間の期間に、八潮南の増改築、ピッコロの移転というものの前に、どこかで、人工呼吸器の対応というのを生活介護で考えていらっしゃるという計画は今のところはいかがでしょうか。","respondent":"川崎障害者施策推進課長","answer":"現時点では人工呼吸器対応というところで検討はございません。","voiceIndex":311,"id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"質問","question":"やはり、人工呼吸器対応の生活介護の施設があれば、そこで通所できたり、そして、それが活動、仕事などを、そのあることによってできるという方も多くいらっしゃるということで、そういった団体の方からのお話も伺っているので、ちょっと令和９年というところは一つの計画としてはあるとはいえ、少しやはり先だというところを考えると、やはり検討を進めていく必要があるのかなというふうには思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":313,"id":"exchange-091"},{"speaker":"鈴木委員","kind":"質問","question":"医療的ケア児者の直近の人数というのを、先ほどの一般質問で聞いたのですけど、そのところで、医療的ケア児者の直近の人数が、１８歳以下が３０人で１９歳以上が４人ということだったのです。これは、４人という人数はあり得ないのではないかと思うのですけど、その点、どうしてこうなったのか伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"もともと前提が、医療的ケア児者の人数については、令和５年２月末現在で、重症心身障害児者等在宅レスパイト事業および障害児支援等の利用者のうち、医療的ケアを要する人数が１８歳以下は３０人、１９歳以上は４人です。","voiceIndex":315,"id":"exchange-092"},{"speaker":"鈴木委員","kind":"質問・要望","question":"だからこれは結局、両方足せないということですか。そこを突き合わせないと、なかなか全部の人数というのは見えてこない部分があると思うのですけど、全体の人数が見えてこないと、今計画つくっていますけど計画の中にも反映できないと思いますので、保健センターとかも突き合わせをしながら、全体の医療的ケア児者の人数というのは把握していただきたいなと思うのですけど、いかがでしょうか。","respondent":"川崎障害者施策推進課長","answer":"病院に入院されている方もいらっしゃいますので、非常に、把握するのは困難ではあります。ただ、保健センターとは、この令和５年２月末現在の数字は突き合わせている、突合しているものです。","voiceIndex":317,"id":"exchange-093"},{"speaker":"鈴木委員","kind":"質問・要望","question":"だから少なくとも、１９歳以上は人工呼吸器の方が１０人、人工呼吸器というふうに限定しないとなかなか分からないというのが実態ということなのですかね。それなので、ぜひその連絡会は、もっと情報を共有しながら、課題も明確にして、その課題に対してどういうふうに区としては取り組んでいくのかというところの計画を、ぜひ明らかにしていただきたいなと思うのですけど、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"参加される人が医療従事者という方もいらっしゃいますので、なかなかコロナの間、開催するのは難しかったのですけれども、このたび、また１２月の上旬に開催を予定しておりますので、かなり、お子さんから大人まであると幅広い議題にはなってしまいますが。","voiceIndex":319,"id":"exchange-094"},{"speaker":"鈴木委員","kind":"質問・要望","question":"国のほうは医療的ケア児ということでの対応ということですけど、でも、医療的ケア児支援法の中には、やはりその医療的ケア児が１８歳に達し、また、高等学校を卒業した後も適切な保健医療サービスおよび福祉サービスを受けながら日常生活および社会生活を営むことができるようにすることも配慮して行わなければならない、支援に対して、そういうふうなことが法律の中にも明記されていますので。","respondent":"松山障害者支援課長","answer":"先ほど申しましたように、令和９年度に移転拡張予定のピッコロにつきましては、人工呼吸器を使用するなど、医療的ケアの程度が重篤な方についても受入れができるよう整備を進めているところです。","voiceIndex":321,"id":"exchange-095"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうことは本当に、区として早急に取り組まなければならない、区の責務というか、私はそんな思いがするのですけど、そういうご相談を受けてる方から、この方は１８歳まではずっと、高校まで本当に休まずに通い続けてきたのに、もう今、７年たちますけど、いまだに通うところがないために、もう家に閉じ籠もらざるを得なくて、もう本当に、今年こそ何とかしてほしいという願いを伺っているのですけど。","respondent":"松山障害者支援課長","answer":"様々、その方のご事情によって、過ごし方は変わってくるものと考えています。先ほど申しましたように、令和９年度に移転拡張のピッコロについては、人工呼吸器のご利用者が受け入れられるように今、具体的に整備を進めているところです。","voiceIndex":323,"id":"exchange-096"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなので、そういうことで、初めに、人工呼吸器受け入れますよ、酸素吸入の方も受け入れますよという明確な方針を持たないと、後で、これもできていない、これも施設として足りなかったというふうなことになるので、そこのところは、ピッコロがそうやって拡大されるというのは、一つの大きないい機会でもあると私は思うので、そこの方針を明確にした上で整備をしていただきたいと思うのですけど。","respondent":"川崎障害者施策推進課長","answer":"先ほどの答弁の繰り返しにはなるのですけれども、移転拡張するピッコロというのは病院とは異なります。ですので、高度な医療支援の対応というのは難しいところです。","voiceIndex":325,"id":"exchange-097"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今のだと、人工呼吸器の方は受け入れるかどうかまだわからないという、そういうことですか。いつまでたっても希望を持つことができないのです。それなので、人工呼吸器は受け入れます、酸素吸入の方も、酸素吸入だからといって断らずに受け入れます、そういうことでピッコロというのは整備しますというところで、確認させていただきたいのですけど、その点は確認できないですか。","respondent":"川崎障害者施策推進課長","answer":"ですので、重度の方もご利用いただけるような整備というのはもちろん、体制は構えます。ただ、人工呼吸器を使用となると、やはり、看護師の手厚い配置というのがありますので、今後、運営する法人の体制にもよります。そこの部分も含めて、今後十分検討していくことになります。","voiceIndex":328,"id":"exchange-098"},{"speaker":"鈴木委員","kind":"質問","question":"そうしますと、人員、ハードの部分というのは人工呼吸器の方も受け入れるという、そういうところで整備をするけれども、あとは人員体制が、ここを委託される事業所がそういうことで配置をしますよということで、区との協議が整えば人工呼吸器の方も受け入れる。区としては人工呼吸器の方も受け入れるという方向で事業者と話合いを進めていくと、そういうことでよろしいでしょうか。","respondent":"松山障害者支援課長","answer":"看護師の配置につきましても、全国重症心身障害児（者）を守る会のところで、やはりノウハウがありますので、高度な医療的ケアに対応できるスキルのある看護師を確保ということで、お話は進めているところです。","voiceIndex":330,"id":"exchange-099"},{"speaker":"鈴木委員","kind":"質問・要望","question":"守る会のスキルというのは、ほかの自治体でも話を伺って、本当にかなりの重度の方まで受け入れているというのは実態としても伺っておりますので、そういう守る会が、ここのピッコロの委託を受けていただいていますので、そういう点では、区はそういう方針を持てばできるのではないかなというふうに思いますので、ぜひ今回のピッコロでは、人工呼吸器の方ということも含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":332,"id":"exchange-100"},{"speaker":"ひがし委員","kind":"確認","question":"この状況について区として課題として考えているから、このピッコロが拡大することに向けて、令和９年度になりますけど、そのときには、落ち着いていれば人工呼吸器を使っていても、きちんとした場所の確保と人員の確保に向けて区としても取り組んでいるという認識でよろしいでしょうか。その１点を確認させてください。","respondent":"松山障害者支援課長","answer":"確かにおっしゃられるとおりで、健康状態が落ち着いていればというところで、区としては、人工呼吸器の方を受け入れるような具体的な整備を進め、あとは人員配置というのも確保に向けて協議をしているところです。","voiceIndex":334,"id":"exchange-101"},{"speaker":"ひがし委員","kind":"確認","question":"その点が確認できて安心しました。特に、この設備面ですか、ストレッチャー型の車椅子が入るだとか、電源の確保というところはもう重要だから、ここについても整備をしているということでお話は聞いております。それで、ソフトの面だと、やはり人材の確保が難しいということで、そこについてやはり予算というのをしっかりとつけていかないと難しいのかなというふうに思います。その１点について。","respondent":"松山障害者支援課長","answer":"委員おっしゃられるとおり、やはり医療的ケアの実施というのは看護師が行うのが基本になっています。なかなか人工呼吸器レベルですと、喀たん吸引の研修を受けた職員の方であっても、そこまではなかなかケアができないという現実があります。","voiceIndex":336,"id":"exchange-102"},{"speaker":"ひがし委員","kind":"質問","question":"ということはまだ具体的なところというのはこれからで、看護師の人数とかというところもこれからということですか。","respondent":"松山障害者支援課長","answer":"２０名に拡大した場合については、どの程度、医療的ケアの必要度がある方がどのくらい入られる、通所されるかによりますけれども、看護師としては今、現在、生活支援より多い状態になっておりますので、今後も看護師の確保は不可欠ということになっております。","voiceIndex":338,"id":"exchange-103"},{"speaker":"ひがし委員","kind":"質問・要望","question":"その点については要望をします。その点について何かあれば一言お願いします。","respondent":"松山障害者支援課長","answer":"医療的ケア者の人数把握についてのご質問です。なかなか、全体を統一するようなシステムは今ございませんので、それぞれのところの所管がどの程度把握し、それを個人の突合がどの程度できるかということになってまいりますので、可能な限り把握することに努めたいと考えています。","voiceIndex":340,"id":"exchange-104"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ、区として、この人数はどのぐらいなのだろうと思ったときに、聞いて分かるか、せめてこちらが調べられるような状況になっていただくと、必要性とニーズと必要な政策というところも導けるかなというふうに思いますので、ぜひ皆さんで協力してやっていけたらなと思います。こちらは要望で終了とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":342,"id":"exchange-105"},{"speaker":"こしば副委員長","kind":"質問","question":"結論を出すで、今回の陳情については不採択でお願いします。実際その現場で働く方、看護師の方の負担、またストレス等も考えると、やはりこういったことは医療機関で行うべきところが大きいのかなという認識をいたしました。そういうことを踏まえまして、これからまたさらにこの八潮のほうの環境整備も進めていくですので、こちらのほうに期待をしたいと考えまして、今回の陳情については不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":345,"id":"exchange-106"},{"speaker":"こんの委員","kind":"確認","question":"本日結論を出すで、お願いします。先ほどの質疑を聞いていまして、品川区としては受入れの課題と思っている点が確認され、ただ、そのことについて受入れのために体制整備をされている、また、運営事業者とも協議をされている。こうした、受け入れるための体制づくりは現在も進められているということがよく分かりました。よって、これは不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":346,"id":"exchange-107"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今回結論を出すで、お願いいたします。それで、不採択でお願いいたします。今後も、まだ計画をしっかりと含めて注視をしていきたいと思っているのと、先ほどお伝えしたように、移動中の安全の確保だったり、バイタルサインの異常の早期発見、あとは人工呼吸器の正しい使用ができる人材確保というところ、大変重要だと考えていますので、その点に向けても、前向きに協力しながら進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":347,"id":"exchange-108"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これは本当に切実な要望のご相談をいただいているので、それを取り上げてきたのですけど、令和９年ということで４年後になるので、その方は１０年間以上、もう本当に家に閉じ籠もらざるを得ないという状況になるのだなというのを、改めて本人の立場に立って考えているところなのですけど、このピッコロのところで、何としてもこれを実現させていただきたいと強く求めておきたいと思います。陳情には賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":348,"id":"exchange-109"},{"speaker":"筒井委員","kind":"質問","question":"本日結論を出すということで、不採択でお願いします。理由といたしましては、区としても課題を認識されている、そして、今後その整備をされて、方向性としては受入れの方向性ということであります。ただ、人材確保の課題や、その直ちにというのが現実的に困難という事情もありますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":349,"id":"exchange-110"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日結論を出すで、お願いします。医療的ケア児は今、通所できる場所がある。でも１８歳以上は、今のところ、人工呼吸器の方とかですと、やはり都の介助のところだったりとか在宅であったりとかということで、本人が希望しているのであればいいのですけれども、仕方なくそうなっているなら整備を進めるべきだとは思っていました。もう既にやるということですので、これに関しては不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":350,"id":"exchange-111"},{"speaker":"やなぎさわ委員","kind":"意見","question":"やはり、今のところ人工呼吸器の対応できる施設がないというところで、在宅を希望するか通所を希望するかというのを、どちらでも選べるという体制にするということは非常に大切なことなのかなと思いますし、ただ、その人員がというようなお話も複数の委員からも出ておりますし、そういった事情もあるということは承知の上ではありますけれども、議会としても、こういった整備を。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":351,"id":"exchange-112"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3676#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":83195,"voices":357}}]);
